// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святителю Феофану, Затворнику Вишенському","e":"Akathist to St Theophan the Recluse of Vyshensk","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Го́сподем Це́ркве Ру́ськия світи́льниче, ізря́дний подви́жниче і і́стинний служи́телю Христо́в, богому́дре святи́телю Феофа́не! Восхваля́єм тя любо́вію і чтим по́двиги і труди́ твоя́, ї́миже ві́рним лю́дем до́брі послужи́л єси́, і в затво́рі пребива́я, благода́тними уче́ньми путь спасе́нія начерта́л єси́. Ни́ні же, престо́лу Бо́жию предстоя́, о нас моли́ся, зову́щих ті:","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Ікос 1","ps":["А́нгельськия чистоти́ взиску́я і ве́лію любо́в ко Го́споду імі́я, по́двиг і́ночеськаго житія́ под'я́л єси́, святи́телю преди́вний. Му́дрости же дар, от Го́спода ті да́нний, стори́цею умно́жив, лю́дем во спасе́ніє послужи́л єси́. Сего́ ра́ди і ми с любо́вію вопіє́м ті:","Ра́дуйся, па́че всего́ земна́го Го́спода возлюби́вий;","ра́дуйся, на Него́ єди́наго все упова́ніє возложи́вий.","Ра́дуйся, от младе́нчества се́рдце своє́ Го́сподеві преда́вий;","ра́дуйся, от ю́ности ра́зум свой Бо́жиєю прему́дростію напита́вий.","Ра́дуйся, а́нгельськаго житія́ ревни́телю;","ра́дуйся, Ду́ха Свята́го стяжа́телю.","Ра́дуйся, на лови́тву челові́ков Бо́гом предизбра́нний;","ра́дуйся, я́ко лучеза́рний світи́льник, Го́сподем возже́нний.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Кондак 2","ps":["Ви́дів, я́ко вся́кая жите́йськая сла́дость бива́єть печа́лі прича́стна, свя́тче Феофа́не, суєту́ сує́ть возненави́діл єси́ і кра́сная ми́ра сего́ отве́ргл єси́, вседу́шно Бо́гу себі́ преда́в, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́нієм кни́жния прему́дрости оби́льно от Бо́га ізмла́да одаре́нний, ум свой чте́нієм святи́х писа́ній пита́л єси́, обріта́я в них си́лу вели́ку і світ духо́вний. Ми же, ві́дуще сіє́, со умиле́нієм к тебі́ взива́єм:","Ра́дуйся, благочести́вих роди́телей отроча́ богоізбра́нноє;","ра́дуйся, сокро́вище цілому́дрія, благода́тію сви́ше іспо́лненноє.","Ра́дуйся, ізді́тська к Бо́гу любо́вію пламене́вий;","ра́дуйся, от ю́ности к послуша́нію прилежа́вий.","Ра́дуйся, кро́тостію і незло́бієм Го́споду подража́вий;","ра́дуйся, путь ді́вства і чистоти́ ізбра́вий.","Ра́дуйся, і́ночеськаго житія́ всім се́рдцем возжела́вий;","ра́дуйся, всего́ себе́ на служе́ніє Го́сподеві преда́вий.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Кондак 3","ps":["Си́ла Бо́жия тя, святи́телю Феофа́не, немощни́й сосу́д челові́чеський, істо́чник прему́дрости соді́ла і па́стиря до́браго лю́дем дарова́, о спасе́нії їх ду́шу полага́ющаго і Го́споду непреста́нно вопію́щаго: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй в се́рдці твоє́м єди́наго Го́спода, ти, уго́дниче Бо́жий, с ра́достію ве́лією вся сокро́вища душі́ твоєя́ і ра́зума на служе́ніє Це́ркві святі́й отда́л єси́, уча́ і наставля́я вся прибега́ющия к тебі́. Ми же, ублажа́юще труди́ твоя́, вопіє́м ті си́це:","Ра́дуйся, ве́лією му́дростію Го́сподем напоє́нний;","ра́дуйся, в труді́х подви́жничества іспи́танний.","Ра́дуйся, архієре́ю. Бо́гом ізбра́нний;","ра́дуйся, моли́твенниче о нас ко Го́споду неуста́нний.","Ра́дуйся, святи́тельськаго са́на смире́нний носи́телю;","ра́дуйся, богому́дрія ві́рний учи́телю.","Ра́дуйся, душевре́дних раско́лов іскорени́телю;","ра́дуйся, ві́ри правосла́вния ревни́телю.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Кондак 4","ps":["Бу́рею см'яте́нія іспо́лнишася ча́да па́стви твоєя́, хотя́щу ті, святи́телю Феофа́не, по́двигу затво́ра себі́ посвяти́ти, посліди́ же возра́довахуся, ви́дяще тя найпа́че о спасе́нії їх пеку́щася, і воспі́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє о вселе́нії твоє́м в пу́стинь Ви́шенськую стека́хуся к тебі́ і, почита́юще тя па́стиря до́браго, проси́ша моли́тися о них і ко спасе́нію наста́вити. Ми же, ві́дяще сіє́, прино́сим ті похвали́ сицеви́я:","Ра́дуйся, я́ко оте́ць чадолюби́вий па́стві твоє́й би́вий;","ра́дуйся, непреста́нно о ней попече́ніє імі́вий.","Ра́дуйся, па́стирю, ду́шу твою́ за о́вці полага́вий;","ра́дуйся, неуста́нно спасе́нію їх соде́йствовавий.","Ра́дуйся, тишину́ і богоми́сліє найпа́че возлюби́вий;","ра́дуйся, благо́ю во́лею себе́ от ми́ра затвори́вий.","Ра́дуйся, і́ноков любвеоби́льний наста́вниче;","ра́дуйся, оби́телі Ви́шенськия неугаси́мий світи́льниче.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́ниче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́, святи́телю досточу́дне, во оби́телі бо Ви́шенстей в по́двизіх тіле́сних і духо́вних пребива́я, о́браз до́брий бил єси́ христолюби́вой бра́тії, на тя взира́ющей, науча́я всіх немо́лчно пі́ти Го́споду: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше бра́тія тя, во смире́нії і кро́тости по́двиг і́ночеський соверша́юща, прихожда́ху к тебі́ і назида́хуся. Та́кожде і ми, почита́юще тя і́стиннаго ізбра́нника Бо́жия, вопіє́м сицева́я:","Ра́дуйся, істо́чниче любве́ ко Го́споду неізсяка́ємий;","ра́дуйся, кла́дезю смире́нія і кро́тости, жа́ждущих напая́ющий.","Ра́дуйся, жи́тниці, пи́щею духо́вною всіх насища́ющая;","ра́дуйся, свіще́, сві́том ві́ри озаря́ющая.","Ра́дуйся, воздержа́нія до́брий рачи́телю;","ра́дуйся, спасе́нія душ усе́рдний попечи́телю.","Ра́дуйся, Правосла́вія пропові́дниче неуста́нний;","ра́дуйся, кри́не ра́йський, в пусти́ні процві́тшій.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Кондак 6","ps":["Пропові́дник немо́лчний і віща́тель і́стин Бо́жиїх бил єси́ во святи́тельстім служе́нії, просвіща́я і наставля́я па́ству твою́, досточу́дне Феофа́не, і, в затво́рі сий, не оста́вил єси́ благода́тними словеси́ твої́ми всіх, притека́ющих к тебі́, подвиза́я пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́, я́ко звізда́ пресві́тлая, му́дрость твоя́, ди́вний служи́телю Христо́в: Бо́жиїм бо ізволе́нієм із затво́ра, тя сокри́вшаго, яви́шася пото́ци живи́х слове́с твої́х і откри́ся цільбоно́сний істо́чник благода́тних уче́ній, утоля́яй вся́каго жа́ждущаго і с ві́рою к нему́ припа́дающаго. Ми же взива́єм ті си́це:","Ра́дуйся, устна́ми твої́ми му́дрость Бо́жию віща́вий;","ра́дуйся, є́юже жа́ждущия напоі́вий.","Ра́дуйся, в по́двизіх і́ночеськаго житія́ неутоми́мий;","ра́дуйся, сто́лпе правосла́вія непоколеби́мий.","Ра́дуйся, оби́чаєв гріхо́вних му́дрий іскорени́телю;","ра́дуйся, к доброді́телі неуста́нний води́телю.","Ра́дуйся, душ на́ших ціли́телю; ра́дуйся, благоче́стія на́шего окорми́телю.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Кондак 7","ps":["Хотя́ Ца́рствія Бо́жия дости́гнути, ти, святи́й о́тче, отре́клся єси́ ми́ра, і обрі́л єси́ благода́ть Ду́ха Свята́го, і с любо́вію служи́л єси́ лю́дем, подража́я Пастиренача́льнику Христу́ і поя́ Тому́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго подви́жника і уго́дника Христо́ва, смире́нія і кро́тости іспо́лненнаго, ви́дяще тя лю́діє, с наде́ждою устреми́шася в пу́стинь Ви́шенськую, ча́юще твоєя́ благода́тния по́мощі. Та́кожде і ми, по́мощі от тебе́ прося́ще, вопіє́м такова́я:","Ра́дуйся, кро́тостію ду́ха твоєго́ мно́гія к Бо́гу обрати́вий;","ра́дуйся, уми́ помраче́нния просвіти́вий.","Ра́дуйся, чистоту́ а́нгельськую на землі́ стяжа́вий;","ра́дуйся, стра́ждующия твоє́ю любо́вію уврачева́вий.","Ра́дуйся, незло́бія ди́вний наста́вниче;","ра́дуйся, благоче́стія всесві́тлий світи́льниче.","Ра́дуйся, к покая́нію всіх призива́яй;","ра́дуйся, по́мощі твоєя́ прося́щих не оставля́яй.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Кондак 8","ps":["Стра́нний і ди́вний по́двиг яви́л єси́, святи́телю, в житії́ твоє́м: в труді́х і непреста́нном богоми́слії пребива́яй, ра́зума духо́внаго сокро́вище стяжа́л єси́ і писа́ньми твої́ми це́ркві усе́рдно послужи́л єси́. Ми же, ви́дяще сіє́, во умиле́нії серде́ць на́ших благода́рно поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім вся явля́єшися, святи́телю Бо́жий: па́стир і оте́ць, учи́тель і наста́вник і і́стинний пропові́дник, писа́нія бо твоя́ во всіх граді́х і ве́сіх до ни́ні вопію́ть немо́лчним благові́стієм. Сего́ ра́ди ми, ча́да твоя́ духо́вния, с любо́вію глаго́лем ті:","Ра́дуйся, росо́ю Ду́ха Свята́го напоє́нний;","ра́дуйся, сві́том благода́ті Бо́жия осіне́нний.","Ра́дуйся, сокро́вище нетлі́нноє стяжа́вий;","ра́дуйся, дія́нієм апо́стольським поревнова́вий.","Ра́дуйся, к богопозна́нію путь указу́ющий;","ра́дуйся, му́дрость благода́тную взиску́ющий.","Ра́дуйся, Це́ркве Ру́ськия процвіте́ніє;","ра́дуйся, святи́х оте́ць украше́ніє.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нського житія́ наста́вниче."]},{"h":"Кондак 9","ps":["Всяк час привре́меннаго житія́ твоєго́, святи́телю, єди́ному на потре́бу рабо́тал єси́, і ду́шу твою́ хра́мину чи́сту Ду́ха Свята́го соді́лал єси́, возгріва́я се́рдце твоє́ непреста́нною моли́твою Ісу́совою і воспіва́я Го́споду: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я златовеща́нний, кро́ткий і му́дрий яви́лся єси́ всім, внима́вшим тебі́ с ві́рою, і си́лою слове́с твої́х науча́л єси́ пра́вді Бо́жієй. Сего́ ра́ди прийми́ от нас, блаже́нне о́тче, восхвале́нія сицева́я:","Ра́дуйся, святи́телю Бо́жий, смире́нний і кро́ткий;","ра́дуйся, па́стирю благи́й і чадолюби́вий.","Ра́дуйся, землі́ Россі́йськия златоу́сте;","ра́дуйся, богоявле́нію тезоімені́те.","Ра́дуйся, душ заблу́дших і́стинний путеводи́телю;","ра́дуйся, печа́льних ско́рий уті́шителю.","Ра́дуйся, немощни́м во ві́рі непоколеби́моє утвержде́ніє;","ра́дуйся, унива́ющим в труді́х мно́зіх ободре́ніє.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нського житія́ наста́вниче."]},{"h":"Кондак 10","ps":["Спасе́нія путь от гріхо́вних тене́т ча́дом Бо́жиїм начерта́л єси́, уго́дниче Христо́в, сказу́я о та́йнах бра́ні неви́димия, і віне́ць вожделі́нний жа́ждущим спасе́нія показа́л єси́, призива́я благода́рно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і защище́ніє ста́да Христо́ва от волко́в, губ'я́щих є, яви́шася богому́драя писа́нія твоя́, святи́телю Бо́жий, і́миже огражда́єши ві́рних на путі́ ко спасе́нію. Ми же, просвіща́ємії уче́ньми твої́ми, благогові́йно взива́єм ті си́це:","Ра́дуйся, пра́вило ві́ри;","ра́дуйся, наста́вниче прему́дрий.","Ра́дуйся, учи́телю благоче́стія;","ра́дуйся, іскорени́телю нече́стія.","Ра́дуйся, світи́льниче пресві́тлий;","ра́дуйся, пропові́дниче дерзнове́нний.","Ра́дуйся, я́ко сі́ятель до́брий ни́ву Христо́ву возде́лавий;","ра́дуйся, я́ко ко́кош, ча́да твоя́ охраня́ющий.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нського житія́ наста́вниче."]},{"h":"Кондак 11","ps":["Пі́ніє всехва́льноє прино́сим ті, святи́телю, і ублажа́єм тя, просла́вившаго житіє́м і по́двиги твої́ми свято́є і́м'я Творця́ і Бо́га на́шего. Сподо́би і нас моли́твами твої́ми благонра́вноє житіє́ препроводи́ти, да вку́пі с тобо́ю воспої́м Тому́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє житіє́ твоє́, преди́вний Затво́рниче, не скри́ся от і́щущих пра́вди Бо́жієй. Благи́й же коне́ць твой безм'яте́жний і ми́рний показа́ тя і́стинний сосу́д Бо́жієй благода́ті. Ми же єди́ними усти́ со умиле́нієм глаго́лем ті:","Ра́дуйся, чистоти́ душе́вния і тіле́сния сосу́де благослове́нний;","ра́дуйся, до конця́ Го́споду послужи́вий.","Ра́дуйся, по кончи́ні твоє́й блаже́нства ві́чнаго удосто́ївийся;","ра́дуйся. Ца́рствіє Бо́жиє наслі́довавий.","Ра́дуйся, оби́телі Ви́шенськия ди́вноє украше́ніє;","ра́дуйся, землі́ Тамбо́вськия і Ша́цькия просвіще́ніє.","Ра́дуйся, па́стви ряза́нськия похвалі́ і ра́дованіє;","ра́дуйся, душ на́ших попече́ніє.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нського житія́ наста́вниче."]},{"h":"Кондак 12","ps":["Благода́тію Бо́жиєю преізря́дно озаре́нний і па́стві твоє́й му́дре і предо́бро послужи́вий, ди́вний і кро́ткий святи́телю, не преста́ни о нас хода́тайствовати пред Го́сподем на Небесі́, іді́же предстої́ши в немо́лчном славосло́вії, со а́нгели взива́я Тому́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиги твоя́, со упова́нієм припа́даєм к честни́м моще́м твої́м (іли́: іко́ні твоє́й), святи́телю Бо́жий, і мо́лим тя, небе́снаго покрови́теля на́шего і вели́каго о нас предста́теля пред Престо́лом Го́спода Сла́ви, умиле́нно взива́юще:","Ра́дуйся, уго́дниче Бо́жий преізря́дний;","ра́дуйся, подви́жниче Христо́в преди́вний.","Ра́дуйся, предста́телю крі́пкий на тя упова́ющих;","ра́дуйся, засту́пниче ско́рий тя призива́ющих.","Ра́дуйся, дру́же Христо́в і люби́миче Бо́жий;","ра́дуйся, хода́таю те́плий спасе́нія душ на́ших.","Ра́дуйся, цілому́дренних усе́рдний охрани́телю;","ра́дуйся, в ско́рбіх на́ших уті́шителю.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нського житія́ наста́вниче."]},{"h":"Кондак 13","ps":["О, богому́дрий учи́телю, землі́ Ру́ськия похвалі́ і украше́ніє, святи́телю о́тче Феофа́не, кро́ткий і те́плий наш засту́пниче! Прийми́ от нас ма́лоє сіє́ моле́ніє, тебі́ приноси́моє, і душ на́ших благода́рноє восхвале́ніє. Не забу́ди нас, грі́шних, в моли́твах твої́х, да, упова́юще на тя, непреста́нно взива́єм Го́споду Сил: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськия чистоти́ взиску́я і ве́лію любо́в ко Го́споду імі́я, по́двиг і́ночеськаго житія́ под'я́л єси́, святи́телю преди́вний. Му́дрости же дар, от Го́спода ті да́нний, стори́цею умно́жив, лю́дем во спасе́ніє послужи́л єси́. Сего́ ра́ди і ми с любо́вію вопіє́м ті:","Ра́дуйся, па́че всего́ земна́го Го́спода возлюби́вий;","ра́дуйся, на Него́ єди́наго все упова́ніє возложи́вий.","Ра́дуйся, от младе́нчества се́рдце своє́ Го́сподеві преда́вий;","ра́дуйся, от ю́ности ра́зум свой Бо́жиєю прему́дростію напита́вий.","Ра́дуйся, а́нгельськаго житія́ ревни́телю;","ра́дуйся, Ду́ха Свята́го стяжа́телю.","Ра́дуйся, на лови́тву челові́ков Бо́гом предизбра́нний;","ра́дуйся, я́ко лучеза́рний світи́льник, Го́сподем возже́нний.","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Кондак 1","ps":["Ізбра́нний Го́сподем Це́ркве Ру́ськия світи́льниче, ізря́дний подви́жниче і і́стинний служи́телю Христо́в, богому́дре святи́телю Феофа́не! Восхваля́єм тя любо́вію і чтим по́двиги і труди́ твоя́, ї́миже ві́рним лю́дем до́брі послужи́л єси́, і в затво́рі пребива́я, благода́тними уче́ньми путь спасе́нія начерта́л єси́. Ни́ні же, престо́лу Бо́жию предстоя́, о нас моли́ся, зову́щих ті:","Ра́дуйся, святи́телю Феофа́не, прему́дрий учи́телю і христия́нськаго житія́ наста́вниче."]},{"h":"Молитва","ps":["О, святи́телю о́тче Феофа́не, архієре́ю пресла́вний і преди́вний затво́рниче, Бо́жий ізбра́нниче і Тайн Христо́вих служи́телю, богому́дрий учи́телю і апо́стольських слове́с ізря́дний із'ясни́телю, оте́чеських добротолю́бних сказа́ній описа́телю, христия́нського благоче́стія ізя́щний пропові́дниче і жи́зні духо́вния іску́сний наста́вниче, по́двигов мона́шеських усе́рдний ревни́телю і всім лю́дем благода́ті хода́таю! Ни́ні к тебі́, на Небесі́х Бо́гу предстоя́щему і о нас моля́щемуся припа́даєм і си́це взива́єм: іспроси́ у Всеще́драго Бо́га Це́ркві Росси́йстій і страні́ на́шей мир і благостоя́ніє, святи́телем Христо́вим — і́стини Боже́ственния досто́йноє охране́ніє, па́стви до́броє окормл'єніє, лжеучи́телей і єретико́в ізря́дноє посрамле́ніє, подвиза́ющимся — смире́ніє, страх Бо́жий і чистоту́ душе́вную і тіле́сную, учи́телем — богові́дініє і му́дрость, уча́щимся — ре́вность і по́мощ Бо́жию. І всім правосла́вним — утвержде́ніє на путі́ ко спасе́нію, да вку́пі с тобо́ю просла́вим Бо́жию Си́лу і Прему́дрость Го́спода на́шего Ісу́са Христа́, со Безнача́льним Єго́ Отце́м, со Пресвяти́м, Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Правосла́вія наста́вниче, / благоче́стія учи́телю і чистоти́, / Ви́шенський подви́жниче святи́телю Феофа́не Богому́дре, / писа́ньми твої́ми сло́во Бо́жиє із'ясни́л єси́ / і всім ві́рним путь ко спасе́нію указа́л єси́. // Моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Богоявле́нію тезоимени́тий, / святи́телю Феофа́не, / уче́нії твої́ми мно́гия лю́ди просвіти́л єси́, / со а́нгели ни́ні предстоя́ Престо́лу Святи́я Тро́йці, // моли́ непреста́нно о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Феофа́не, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святителю Тихону, єпископу Воронезькому, Задонському чудотворцю","e":"Akathist to St Tikhon, Bishop of Voronezh, Wonderworker of Zadonsk","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, Святи́телю о́тче Ти́хоне, возсія́вий ми́рові, я́ко світоза́рноє світи́ло, прославля́юще просла́вльшаго тя Го́спода, дарова́вшаго нам в тебі́ но́ваго вели́каго моли́твенника і помо́щника, ско́раго неду́гов душе́вних же і тіле́сних ціли́теля, похва́льноє воспіва́єм ті пі́ніє: ти же. Імі́яй ве́ліє дерзнове́ніє к Влади́чице небесе́ і землі́, от вся́ких нас бід свобо́ди зову́щих:","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов собесі́дниче і челові́ков наста́вниче, ни́ні, я́ко Бо́жий служи́тель, предстоя́ с ви́шніми ли́ки, Святи́телю Ти́хоне, мо́лиши о всіх нас Христа́ Бо́га на́шего і к ві́дінію спасе́нія ни руково́диши. Сего́ ра́ди благода́рні во умиле́нії вопіє́м ті:","Ра́дуйся, пречестно́є Святи́я Тро́йці селе́ніє;","Ра́дуйся, чистото́ю і святи́нею А́нгелом уподобле́ніє.","Ра́дуйся, світи́льниче Боже́ственнаго сві́та;","Ра́дуйся, всесві́тлоє благода́ті прия́телище.","Ра́дуйся, при́сний пред Го́сподем наш засту́пниче;","Ра́дуйся, те́плий пред Ним о нас моли́твенниче.","Ра́дуйся, ско́рий в ну́ждах і ско́рбіх су́щим помо́щниче;","Ра́дуйся, до́брий душ на́ших наста́вниче.","Ра́дуйся, Це́ркве правосла́вний утвержде́ніє;","Ра́дуйся, всея́ землі́ Россі́йськия сві́тлоє озаре́ніє.","Ра́дуйся, Воро́нежськия па́стви похвало́;","Ра́дуйся, оби́телі Задо́нськия украше́ніє.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя в творе́ніїх, а́ки в зерца́лі, прему́дрость і сла́ву Творця́ вся́чеських Бо́га, к Нему́ ду́хом ви́ну возноси́лся єси́, Богому́дре: сві́том же благоразу́мія твоєго́ і нас озари́, да вопіє́м ку́пно с тобо́ю: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум твой Боже́ственними уче́нми просвіти́л єси́, Богому́дре Ти́хоне, отве́ргнув вся́ко плотсько́є мудрова́ніє, с ра́зумом же і во́лю повину́л єси́ Го́сподеві: тім же сосу́д чист і селе́ніє Ду́ху і́стини яви́лся єси́. Сего́ ра́ди, я́ко богому́драго наста́вника, тя ублажа́юще, воспіва́єм си́це:","Ра́дуйся, Бо́жия прему́дрости созерца́телю і пропові́дниче;","Ра́дуйся, я́ко от тлі́ннаго ми́ра духо́вноє сокро́вище, услажда́ющеє ду́ші ві́рних, собра́л єси́.","Ра́дуйся, і́стиннаго благосло́вія златослове́сний учи́телю;","Ра́дуйся, я́ко уста́ Христо́ви, істоча́юща словеса́ жи́зні ві́чния, бил єси́.","Ра́дуйся, зако́на Бо́жия от всея́ ду́ші твоє́й взиска́вий;","Ра́дуйся, свиді́ній і оправда́ній Госпо́дніх возжада́вий.","Ра́дуйся, я́ко к небесі́ ве́дущими стезя́ми невозвра́тно шел єси́;","Ра́дуйся, я́ко на висоту́ доброді́телей возше́л єси́.","Ра́дуйся, я́ко ми́сленним о́ком к невече́рнему сві́ту — Христо́ву ви́ну взира́л єси́;","Ра́дуйся, я́ко виді́нія пренебе́снаго сві́та сподо́бился єси́.","Ра́дуйся, Бо́жия ра́зума іспо́лненний;","Ра́дуйся, благода́тію Ду́ха Свята́го приосіне́нний.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго чуде́сно спа́се тя от напра́сния сме́рти і я́ві показа́ тя си́на Ца́рствія Христо́ва су́ща, Святи́телю о́тче Ти́хоне, єгда́, во всю нощ пребива́ющу ті в благоми́слії, внеза́пу небеса́ отверзо́шася і яви́ся світ неізрече́нний. І та́ко преми́рния ра́дости іспо́лнився, возопи́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ві́ру несумне́нну і по́мисл чист, вся красна́я ми́ра сего́ презрі́л єси́, Ти́хоне блаже́нне, і в о́бразі А́нгельстім нелі́ностно послужи́л єси́ Го́споду Бо́гу: тім же, а́ки звізда́ путево́дная, сві́тиши всім, хотя́щим жи́ти в преподо́бії і вопію́щим тебі́:","Ра́дуйся, житію́ безпло́тних поревнова́вий;","Ра́дуйся, по́двигом дре́вніх святи́х оте́ць подража́вий.","Ра́дуйся, я́ко приї́м крест, Христу́ послі́довал єси́;","Ра́дуйся, я́ко о́браз страсте́й Єго́ в се́рдці твоє́м преднаписа́л єси́.","Ра́дуйся, я́ко вся ко́зні дия́вола си́лою креста́ Госпо́дня разруши́л єси́;","Ра́дуйся, я́ко похоті́нія гріхо́вная моли́твою і терпі́нієм побіди́л єси́.","Ра́дуйся, я́ко угожда́л єси́ Го́споду вся́ким благоугожде́нієм;","Ра́дуйся, преукраше́нная хра́мино доброді́телей.","Ра́дуйся, красото́ смиренному́дрія і воздержа́нія;","Ра́дуйся, о́бразе кро́тости і послуша́нія.","Ра́дуйся, по́стников весе́ліє і і́ноков похвало́;","Ра́дуйся, бо́лій в ли́кі преподо́бних.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній, недоуміва́ше раб Бо́жий, что рече́ть о нем Госпо́дь, єгда́ лю́діє проразуміва́ху єго́ досто́йна би́ти святи́тельства: оба́че всего́ себе́ Христу́ Бо́гу предаде́. Тому́ о всіх благодаре́ніє возсила́я, зови́й: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє о благопло́дних добро́тах ду́ші твоєя́, Богоно́сне Ти́хоне, жела́нієм вожделі́ша тя ви́діти на сте́пені святи́тельства. Єгда́ же собо́р Архієре́єв недоуміва́ше вда́ти тебі́ жезл па́стирства, зане́ юн бил єси́, а́біє трикра́ти сви́ше свиді́тельствован єси́, я́ко досто́йний сосу́д Боже́ственния благода́ті, вся немощна́я врачу́ющия і оскудіва́ющая восполня́ющий. Тім же, див'я́щеся чу́дному промишле́нію Бо́га о тебі́, прино́сим ті сицева́я благохвале́нія:","Ра́дуйся, Архієре́ю, от Самого́ Го́спода пронарече́нний;","Ра́дуйся, му́жу жела́ній, пасти́ ста́до Христо́во сви́ше ізбра́нний.","Ра́дуйся, Пастиренача́льника Ісу́са благоволе́ніє;","Ра́дуйся, Ієра́рхов украше́ніє.","Ра́дуйся, я́ко от у́тра жи́зні твоєя́ на стражбу́ слове́снаго ста́да ізбра́н бил єси́;","Ра́дуйся, я́ко і до ве́чера житія́ твоєго́ су́щия во ві́рі нелі́ностно назида́л єси́.","Ра́дуйся, па́стирю до́брий, я́ко гото́в бил єси́ ду́шу твою́ положи́ти за о́вці своя́;","Ра́дуйся, многосві́тлий Це́ркве світи́льниче.","Ра́дуйся, Апо́столов соприча́стниче;","Ра́дуйся, вели́ких святи́телей сопресто́льниче.","Ра́дуйся, я́ко первопресто́льнику па́стви твоєя́, Митрофа́ну освяще́нному, равноче́стен показа́лся єси́;","Ра́дуйся, я́ко преє́мником твої́м ві́рний ко спасе́нію путеводи́тель соді́лался єси́.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́ всім христия́ном, Святи́телю о́тче Ти́хоне: дія́нми бо і уче́нми твої́ми не то́чію во дні живота́ твоєго́ до́брі назида́л єси́ па́ству твою́, но і по честні́м успе́нії твоє́м всім ві́рним показу́єши пра́ви стезі́ Ца́рствія Христо́ва, і науча́єши при́сно взива́ти к Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя себі́ поста́влена на сте́пені архієре́йства, Святи́телю о́тче наш Ти́хоне, не дал єси́ сна оча́м твої́м, ніже́ ві́ждом дрема́нія, поставля́я па́стві твоє́й па́стирі сми́сленни і вся лю́ди управля́я ко спасе́нію. Ми же, ві́дуще тя би́ти пастиренача́льника богому́дренна і строї́теля до́му Бо́жия до́бра, взива́єм к тебі́:","Ра́дуйся, крі́пкоє корми́ло Христо́ви Це́ркве;","Ра́дуйся, ни́ви Госпо́дні удобре́ніє.","Ра́дуйся, ві́рних наде́жноє утвержде́ніє;","Ра́дуйся, неві́рних богому́дренноє обличе́ніє.","Ра́дуйся, Христо́ва вертогра́да ді́лателю неуси́пний;","Ра́дуйся, душетлі́нному зві́рю ста́до твоє́ расхища́ти не попусти́вий.","Ра́дуйся, хра́мов благолі́пія рачи́телю;","Ра́дуйся, ві́рний тайн святи́х строї́телю.","Ра́дуйся, я́ко страже́й до́му Бо́жия на стражбу́ недре́мленну угото́вал єси́;","Ра́дуйся, я́ко па́стирем пропові́дати благовре́менні і безвре́менні запові́дал єси́.","Ра́дуйся, благи́й і ві́рний ра́бе Бо́жий;","Ра́дуйся, я́ко вшел єси́ в ра́дость Го́спода твоєго́.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник воі́стину благоче́стія яви́лся єси́, Святи́телю о́тче наш Ти́хоне, єгда́ уви́дів безсту́дноє пра́зднество во гра́ді твоє́м, я́ко добр во́їн Христо́в, прите́кл єси́ на і́грище бісо́вськоє і сло́вом вразуми́л єси́ заблу́ждшия, науча́я всіх взива́ти Єди́ному І́стинному Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко звізда́ лучеза́рная, Воро́нежськой па́стві, блиста́нієм уче́ній твої́х озаря́я ду́ші ві́рних і разгоня́я тьму нече́стія і суєві́рія. І ни́ні сла́достію писа́ній твої́х насища́єши вся а́лчущия і жа́ждущия пра́вди, і́же благода́рні і взива́ють к тебі́:","Ра́дуйся, наста́вниче всіх к небесі́ направля́яй;","Ра́дуйся, пропові́дниче покая́нія, заблу́ждших к ісправле́нію воззива́яй.","Ра́дуйся, сла́ви Бо́жия і́стинний ревни́телю;","Ра́дуйся, стра́ннаго суєві́рія потреби́телю.","Ра́дуйся, я́ко душетлі́нния оби́чаї обличи́л єси́;","Ра́дуйся, я́ко безсту́дноє і́грище упраздни́л єси́.","Ра́дуйся, і́мже сатана́ посрами́ся;","Ра́дуйся, і́мже Христо́с просла́вися.","Ра́дуйся, я́ко і по сме́рті твоє́й ду́ші ві́рних назида́єши в благоче́стії сла́достію писа́ній твої́х;","Ра́дуйся, я́ко в них сокро́вище, драгоці́ннійшеє зла́та і сребра́, нам оста́вил єси́.","Ра́дуйся, златоу́сте Россі́йськия Це́ркве;","Ра́дуйся, па́стви твоє́й при́сноє ра́дованіє.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́й невозбра́нно возноси́тися ду́хом в го́рняя селе́нія, благоти́шіє пусти́ні возлюби́л єси́, Богоно́се о́тче Ти́хоне, і та́мо всели́вся, сподо́бился єси́ ви́діти Го́спода, от іко́ни, а́ки от Голго́фи, к тебі́ гряду́ща, вопія́ к Нему́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вим по́двигом духо́вним вдал єси́ себе́, Богоно́се о́тче Ти́хоне, єгда́ всесоверши́тельнаго Ду́ха благода́ть призва́ тя служи́ти Го́сподеві в безмо́лвії: іми́й бо по́мисл преви́ше ми́ра, возлюби́л єси́ смире́ніє глубо́коє і моли́тви непреста́нния. Сего́ ра́ди і крі́пость духо́вную подаде́ тебі́ Подвигополо́жник Христо́с і сподо́би тя виді́ній благода́тних, да і ми, ві́дуще такова́я, ублажа́єм тя:","Ра́дуйся, люби́телю безмо́лвія, ду́хом твої́м во ви́шніх обита́вий;","Ра́дуйся, самоотверже́ніє всеці́лоє показа́вий.","Ра́дуйся, во бді́ніїх і моли́твах неосла́бно пребива́л єси́;","Ра́дуйся, безстра́стіє умерщвле́нієм страсте́й твої́х стяжа́л єси́.","Ра́дуйся, Го́спода расп'я́таго на кресті́ ви́ну пред собо́ю предзрі́вий;","Ра́дуйся, і тіле́снима очи́ма ви́діти Христа́ Ісу́са сподо́бивийся.","Ра́дуйся, я́ко пречи́стим стопа́м Єго́ поклони́лся єси́;","Ра́дуйся, я́ко спаси́тельния я́зви Єго́ облобиза́л єси́.","Ра́дуйся, іспо́лнь весе́лія, єгда́ яви́ся тебі́ Богома́тер ку́пно со Апо́столи;","Ра́дуйся, я́ко в славосло́вії ликовствова́л єси́ со А́нгели.","Ра́дуйся, таї́нниче Бо́жий, єще́ на землі́ вкуси́вий небе́сних благ;","Ра́дуйся, А́нгеле земни́й і челові́че небе́сний.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нно і вели́ко незло́біє показа́, Преблаже́нний, єгда́ єди́н бу́ій і злонра́вний уда́ри єго́ в лани́ту; он же, А́гнцю Христу́ поревнова́в, до землі́ поклони́ся бію́щему, моля́ Бо́га о проще́нії єму́. Тім же див'я́щеся незло́бію єго́, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнь любве́ Христо́ви, Ти́хоне благосе́рде, ду́шу твою́ полага́л єси́ за дру́ги твоя́, і а́ки А́нгел Храни́тель прису́щ бил єси́ бли́жнім же і да́льним, озло́бленния укроща́я, вражду́ющия примиря́я, і спасе́ніє всім устроя́я. Сего́ ра́ди чтем святу́ю па́м'ять твою́ і усе́рдно вопіє́м ті:","Ра́дуйся, пропові́дниче любве́, є́юже Бог примири́ Себі́ челові́ки;","Ра́дуйся, О́тче благосе́рдий, взиска́вий спасе́нія мно́гих.","Ра́дуйся, смире́нія і незло́бія учи́телю;","Ра́дуйся, терпі́нія і миролю́бія наста́вниче.","Ра́дуйся, я́ко за пра́вду претерпі́л єси́ зауше́ніє;","Ра́дуйся, я́ко за враги́ твоя́ умоля́л єси́ Го́спода.","Ра́дуйся, єго́же любо́в побіди́ вся́ку вражду́;","Ра́дуйся, єго́же незло́біє покори́ бу́яя сердца́.","Ра́дуйся, миротво́рче благослове́нний;","Ра́дуйся, мзду миротво́рцев наслі́дивий.","Ра́дуйся, научи́вий за́повідем Христо́вим і сотвори́вий я;","Ра́дуйся, вели́кий в Ца́рствії Небе́снім.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 9","ps":["Всім бил єси́ вся, я́коже і святи́й Па́вел, да вся́ко ні́кия спасе́ши, Богому́дре: сразсужда́я бо немощно́му єстеству́ челові́чеському, не укори́л єси́ бра́та твоєго́, неподоба́ющия посту́ сні́ди яду́ща, но а́біє сі́дши ку́пно с дру́гом єго́, от трапе́зи тоя́ ма́ло вкуси́л єси́. Помина́юще у́бо таково́є благоснисхожде́ніє твоє́, вопіє́м к просла́вльшемуся в тебі́ человіколю́бцю Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї многовіща́нния не возмо́гуть по достоя́нію ізрещи́ твої́х благодія́ній мно́жество, Святи́телю о́тче Ти́хоне: щедрода́тельная бо десни́ця твоя́ всю́ду досяза́ше. Ми же, благосе́рдію твоєму́ подража́ти хотя́ще, во удивле́нії взива́єм к тебі́:","Ра́дуйся, лучу́ любве́ Бо́жия;","Ра́дуйся, сокро́вище милосе́рдія Спа́сова неістощи́моє.","Ра́дуйся, бли́жнія твоя́ па́че себі́ возлюби́вий;","Ра́дуйся, в ме́ньших бра́тіях твої́х самого́ Христа́ ви́дівий.","Ра́дуйся, я́ко ни́щія помина́я, хліб твой слеза́ми ороша́л єси́;","Ра́дуйся, я́ко питіє́ твоє́ пла́чем о них растворя́л єси́.","Ра́дуйся, я́ко імі́нія твоя́ неіму́щим расточа́л єси́;","Ра́дуйся, я́ко щедрода́тельная десни́ця твоя́ ніколи́же оскуді́.","Ра́дуйся, я́ко больни́я і в темни́ці заключе́нния посіща́л єси́;","Ра́дуйся, я́ко ну́жди бі́дних предваря́л єси́.","Ра́дуйся, сло́вом і приме́ром затворе́нния на благости́ню сердца́ отверза́вий;","Ра́дуйся, ми́лостивих блаже́нство от Го́спода стяжа́вий.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ся всім хотя́й преблаги́й Госпо́дь яви́ тя, Святи́телю о́тче наш Ти́хоне, о́браз житія́ пра́веднаго: кто бо не умили́ться, ви́дя твоє́ безмі́рноє ко всім благосе́рдіє. Тім же ве́лію к нам ми́лость Бо́жию сла́в'яще, вопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ бил єси́ по́мощі і заступле́нія всім безпомо́щним і напа́дствуємим, Святи́телю Ти́хоне, і милосе́рдія неістощи́моє сокро́вище. Сего́ ра́ди сла́в'яще Бо́га, ди́внаго во Святи́х Свої́х, і тя ублажа́єм:","Ра́дуйся, безкро́вних приста́нище;","Ра́дуйся, всіх безпомо́щних ско́рий помо́щниче.","Ра́дуйся, си́рих пита́телю і призрі́ніє;","Ра́дуйся, ску́дних земледі́льцев снабді́ніє.","Ра́дуйся, скорб'я́щим прибі́жище;","Ра́дуйся, печа́льним утіше́ніє.","Ра́дуйся, оби́димим заступле́ніє;","Ра́дуйся, оби́дящих вразумле́ніє.","Ра́дуйся, угнете́нним защи́тниче;","Ра́дуйся, си́льним ми́ра сего́ небоя́зненний Суда́ Бо́жия провозві́стниче.","Ра́дуйся, я́ко за пра́вду претерпі́л єси́ ско́рбі;","Ра́дуйся, я́ко стяжа́л єси́ блаже́нство гони́мих ра́ди пра́вди.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє у гро́ба твоєго́ уго́дниче Бо́жий, Святи́телю о́тче Ти́хоне, не умолче́ от дне блаже́ннаго успе́нія до дне сві́тлаго прославле́нія твоєго́: мно́зі бо ве́даху тя Богоно́сна і равноа́нгельна су́ща. Ни́ні же вся Россі́йськая земля́ благода́рно вопіє́ть просла́вльшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́ло бив, вся конці́ землі́ Россі́йськия озари́л єси́, Святи́телю приснопа́м'ятне. Єгда́ же приспі́ вре́м'я отше́ствія твоєго́, Боже́ственнії А́нгели прия́ша святу́ю ду́шу твою́ і в небе́сния оби́телі вознесо́ша; ті́ло же твоє́ честно́є Тро́йця вседі́тельная соді́ла нетлі́нно і істо́чник чуде́с показа́ на утвержде́ніє правосла́вния ві́ри, на обличе́ніє же неві́рія і суєві́рія. Тім же, помина́юще блаже́нноє успе́ніє і ве́ліє твоє́ на небесі́ і на землі́ прославле́ніє, с ра́достію прино́сим ті благохвале́нія сія́:","Ра́дуйся, вели́кий уго́дниче Бо́жий, тече́ніє благоче́стне сконча́вий;","Ра́дуйся, ві́ру, наде́жду і люби́ до конця́ сохрани́вий.","Ра́дуйся, по труді́х стра́нствія земна́го сла́дці в селе́ніїх небе́сних почи́вий;","Ра́дуйся, я́ко смерть прия́вий, тлі́нія же не позна́вий.","Ра́дуйся, со Христо́м, Єго́же возлюби́л єси́, на ві́ки соєдини́вийся;","Ра́дуйся, Ца́рствія Небе́снаго і сла́ви ві́чния наслі́дниче.","Ра́дуйся, я́ко нетлі́нієм моще́й твої́х спаси́тельную си́лу воскресе́нія Христо́ва явля́єши;","Ра́дуйся, я́ко о́ним зарю́ о́бщаго воскресе́нія нам показу́єши.","Ра́дуйся, і́стини правосла́вія несомні́нноє увіре́ніє;","Ра́дуйся, в Це́ркві прису́щия благода́ті нело́жноє ізвіще́ніє.","Ра́дуйся, земна́го оте́чества твоєго́ но́воє світи́ло і утвержде́ніє;","Ра́дуйся, ца́рства правосла́внаго покро́ве і защи́щеніє.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть чуде́с многообра́зних, всели́вся в небесі́, прия́л єси́ от Го́спода, преблаже́нне Ти́хоне. Сего́ ра́ди подає́ши ісціле́нія всім, притека́ющим к тебі́ с ві́рою. Ми же, див'я́щеся в тебі́ всемогу́ществу і бла́гости Бо́га, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́вноє прославле́ніє свята́го тілесе́ твоєго́, ви́дим тя, Богоблаже́нне Святи́телю Ти́хоне, при́сно зді істоча́юща пото́ки чуде́с, і в удивле́нії восхваля́юще тя, зове́м:","Ра́дуйся, живоно́сний істо́чниче, благода́ть ісціле́ній ізлива́ющий нам от всечестни́я ра́ки твоєя́;","Ра́дуйся, всіх одержи́мих неду́ги непости́дноє прибі́жище.","Ра́дуйся, сліпи́х прозрі́ніє;","Ра́дуйся, німи́х я́сноє глаго́ланіє.","Ра́дуйся, я́ко от одра́ разсла́бленния воздвиза́єши;","Ра́дуйся, я́ко стужа́ємия от бісо́в свобожда́єши.","Ра́дуйся, сухору́кия і сля́ченния к ді́ланію ісправля́яй;","Ра́дуйся, хроми́м і нича́щим хожде́ніє подава́яй.","Ра́дуйся, тіле́с на́ших благосострада́тельний врачу́ і хране́ніє;","Ра́дуйся, і душ на́ших к Ца́рствію Небе́сному возведе́ніє.","Ра́дуйся, єму́же сора́дуються А́нгели і о не́мже веселя́ться челові́ци;","Ра́дуйся, і́мже Бог ди́вен во Святи́х Свої́х явля́ється.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 13","ps":["О вели́кий і пресла́вний Чудотво́рче, Святи́телю Христо́в о́тче Ти́хоне, прийми́ сіє́ похва́льноє пі́ніє от нас недосто́йних во умиле́нії тебі́ приноси́моє, і твої́м те́плим предста́тельством у престо́ла Бо́жия іспроси́ нам утвержде́ніє во ві́рі і до́брих ді́ліх, ізбавле́ніє от всіх бід і напа́стей в жи́зні сей, в сме́ртнім же успе́нії на́шем благу́ю наде́жду спасе́нія, да сподо́бимся в ра́дості ві́чній воспіва́ти ди́вному во Святи́х Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов собесі́дниче і челові́ков наста́вниче, ни́ні, я́ко Бо́жий служи́тель, предстоя́ с ви́шніми ли́ки, Святи́телю Ти́хоне, мо́лиши о всіх нас Христа́ Бо́га на́шего і к ві́дінію спасе́нія ни руково́диши. Сего́ ра́ди благода́рні во умиле́нії вопіє́м ті:","Ра́дуйся, пречестно́є Святи́я Тро́йці селе́ніє;","Ра́дуйся, чистото́ю і святи́нею А́нгелом уподобле́ніє.","Ра́дуйся, світи́льниче Боже́ственнаго сві́та;","Ра́дуйся, всесві́тлоє благода́ті прия́телище.","Ра́дуйся, при́сний пред Го́сподем наш засту́пниче;","Ра́дуйся, те́плий пред Ним о нас моли́твенниче.","Ра́дуйся, ско́рий в ну́ждах і ско́рбіх су́щим помо́щниче;","Ра́дуйся, до́брий душ на́ших наста́вниче.","Ра́дуйся, Це́ркве правосла́вний утвержде́ніє;","Ра́дуйся, всея́ землі́ Россі́йськия сві́тлоє озаре́ніє.","Ра́дуйся, Воро́нежськия па́стви похвало́;","Ра́дуйся, оби́телі Задо́нськия украше́ніє.","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, Святи́телю о́тче Ти́хоне, возсія́вий ми́рові, я́ко світоза́рноє світи́ло, прославля́юще просла́вльшаго тя Го́спода, дарова́вшаго нам в тебі́ но́ваго вели́каго моли́твенника і помо́щника, ско́раго неду́гов душе́вних же і тіле́сних ціли́теля, похва́льноє воспіва́єм ті пі́ніє: ти же. Імі́яй ве́ліє дерзнове́ніє к Влади́чице небесе́ і землі́, от вся́ких нас бід свобо́ди зову́щих:","Ра́дуйся, Ти́хоне, вели́кий і пресла́вний Чудотво́рче."]},{"h":"Молитва перша","ps":["О, вели́кий Уго́дниче Бо́жий і пресла́вний Чудотво́рче, Святи́телю о́тче наш Ти́хоне! Со умиле́нієм прекло́нше колі́на і припа́дая к ра́ці честни́х і многоціле́бних моще́й твої́х, хва́лим, сла́вим і велича́єм просла́вльшаго тя Бо́га, і нам недосто́йним показа́вшаго в тебі́ ве́лію ми́лость, і всеусе́рдно, ві́рою і любо́вію чту́щий святу́ю па́м'ять твою́, мо́лим тя: принеси́ моли́тву на́шу к вся содержа́щему і спаса́ющему человіколю́бцю Го́споду, Єму́же ти ни́ні с ли́ки А́нгел і со всі́ми Святи́ми предстої́ши, да утверди́ть во святі́й Своє́й правосла́вной Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, да всі чле́ни єя́, чи́стії от суєму́дрія і суєві́рія, ду́хом і і́стиною покланя́ються Єму́ і усе́рдно пеку́ться о соблюде́нії Єго́ за́повідей, па́стирем єя́ да дасть святу́ю ре́вность попече́нія о спасе́нії вві́ренних їм люде́й — пра́во ве́рующия соблюда́ти, сла́бий і немощни́я во ві́рі укріпля́ти, неве́дущия наставля́ти, проти́вния облича́ти. І па́ки припа́дающе, с упова́нієм, я́коже ча́да отця́ нам су́ща, мо́лим тя, Святи́телю Ти́хоне, ві́руєм бо, я́ко ти, на небесі́х живи́й, лю́биши ни то́ю же любо́вію, є́юже вся бли́жняя твоя́ возлюби́л єси́, внегда́ пребива́ти тебі́ на землі́, іспроси́ у всеми́лостиваго Го́спода і всім нам пода́ти дар коєму́ждо благопотре́бен і вся, я́же к животу́ вре́менному і ві́чному поле́зная, ми́ра умире́ніє, градо́в на́ших утвержде́ніє, землі́ плодоно́сіє, от гла́да і па́губи ізбавле́ніє, от наше́ствія іноплеме́нних сохране́ніє, скорб'я́щим утіше́ніє, неду́гующим ісціле́ніє, па́дшим возстановле́ніє, заблужда́ющим на путь і́стини возвраще́ніє, подвиза́ющимся в ді́ліх благи́х укріпле́ніє, благоде́лающим преспі́яніє, роди́телем благослове́ніє, ча́дом в стра́сі Госпо́днем воспита́ніє і науче́ніє, наста́вником ві́дініє і благоче́стіє, неві́дущим вразумле́ніє, си́рим, неіму́щим і убо́гим по́мощ і заступле́ніє, отходя́щим от сего́ вре́меннаго житія́ к ві́чному благо́є уготовле́ніє і напу́тствованіє, отше́дшим блаже́нноє упокоє́ніє. Сих всіх, найпа́че, проси́ нам, Свя́тче Ти́хоне, у Щедрода́вця Бо́га, я́ко іми́й ве́ліє к Нему́ дерзнове́ніє: тебі́ бо стяжа́хом при́снаго засту́пника і те́плаго моли́твенника о нас пред Го́сподем, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє. Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О всехва́льний Святи́телю і Уго́дниче Христо́в, о́тче наш Ти́хоне! А́нгельськи пожи́в на землі́, ти я́ко А́нгел благи́й яви́лся єси́ і в ди́внім твоє́м прославле́нії. Ві́руєм от всея́ ду́ші і помишле́нія, я́ко ти, благосе́рдий наш помо́щниче і моли́твенниче, твої́ми нело́жними хода́тайстви і благода́тію, оби́льно дарова́нною тебі́ от Го́спода, при́сно спосо́бствуєщі на́шему спасе́нію. Прийми́ у́бо, ублажа́ємий Уго́дниче Христо́в, і в час сей на́ша недосто́йная моле́нія: свобо́ди ни твої́м заступле́нієм от облега́ющаго нас суєсло́вія і суєму́дрія, неправові́рія і злові́рія челові́чеськаго. Потщи́ся, ско́рий о нас предста́телю, благоприя́тним твої́м хода́тайством умоли́ти Го́спода, да приба́вить Своя́ вели́кия і бога́тия ми́лости на нас грі́шних і недосто́йних рабі́х Свої́х, да уврачу́єть Своє́ю благода́тію неісці́льния я́зви і стру́пи растлі́нних душ і тіле́с на́ших, да раствори́ть окамені́лая сердця́ на́ша слеза́ми умиле́нія і сокруше́нія о премно́гих согріше́ніїх на́ших і да ізба́вить ни ві́чних мук і огня́ геє́нськаго; всім же ві́рним лю́дем Свої́м да да́руєть в ни́нішнем ві́ці мир і тишину́, здра́віє і спасе́ніє і во всем благо́є поспіше́ніє, да та́ко, ти́хоє і безмо́лвноє житіє́ пожи́вше во вся́ком благоче́стії і чистоті́, сподо́бимся со А́нгели і со всі́ми Святи́ми сла́вити і воспіва́ти всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва третя","ps":["О святи́телю, о́тче наш Ти́хоне! Усли́ши нас і потщи́ся благоприя́тним твої́м хода́тайством умоли́ти Го́спода, да проба́вить Своя́ вели́кия і бога́тия ми́лости на нас, грі́шних і недосто́йних рабі́х Свої́х (імена́), да уврачу́єть Своє́ю благода́тію неісці́льния я́зви і стру́пи растлі́нних душ і тіле́с на́ших, да раствори́ть окамені́лая сердця́ на́ша слеза́ми умиле́нія і сокруше́нія о премно́гих согріше́ніях на́ших і да ізба́вить ни от ві́чних мук і огня́ геє́нськаго, да да́руєть в ни́нішнем ві́ці мир і тишину́, здра́віє і спасе́ніє, да та́ко сподо́бимся, со А́нгели і со всі́ми святи́ми, сла́вити і воспіва́ти всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в."]},{"h":"Молитва четверта","ps":["О вели́кий уго́дниче Бо́жий і пресла́вний чудотво́рче святи́телю о́тче наш Ти́хоне! Со умиле́нієм припа́дающе к іко́ні твоє́й, мо́лим тя: принеси́ моли́тву на́шу к человіколю́бцю Го́споду, да да́руєть же с долгоде́нствієм душе́вноє же і тіле́сноє здра́віє раба́м Бо́жиїм (імена́) і прихо́жанам свята́го хра́ма сего́, да проба́вить Своя́ вели́кия і бога́тия ми́лости на нас, грі́шних і недосто́йних рабі́х Свої́х, да раствори́ть окамене́лия сердця́ на́ша слеза́ми умиле́нія і сокруше́нія о премно́гих согріше́ніях на́ших і да ізба́вить ни от ві́чних мук і огня́ геє́нськаго, да поє́м і сла́вим неізре́ченния щедро́ти Человіколю́бця Бо́га, Отця́ і Си́на і Свята́го Ду́ха, і твоє́ оте́чеськоє заступле́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["От ю́ности возлюби́л єси́ Христа́ блаже́нне, / о́браз всім бил єси́ сло́вом, житіє́м, любо́вію, / ду́хом, ві́рою, чистото́ю і смире́нієм, / ті́мже і всели́лся єси́ в Небе́сния оби́телі, / іді́же предстоя́ Престо́лу Пресвяти́я Тро́йці, / моли́, святи́телю Ти́хоне, // спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["Правосла́вія наста́вниче, благоче́стія учи́телю, / покая́нія пропові́дниче, Златоу́стаго ревни́телю, / па́стирю предо́брий, / но́вий Россі́ї світи́льниче і чудотво́рче, / па́ству твою́ до́брі упа́сл єси́ / і писа́ньми твої́ми вся ни наста́вил єси́, / ті́мже вінце́м нетлі́нія / укра́шен от Пастиренача́льника, // моли́ Єго́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Апо́столов преє́мниче, / святи́телей украше́ніє, / Правосла́вния Це́ркве учи́телю, / Влади́ці всіх моли́ся, / мир вселе́нной дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Ти́хоне, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Олексію, чоловікові Божому","e":"Akathist to our Venerable Father Alexis, the Man of God","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, сви́ше нарече́нний челові́че Бо́жий, свя́те Алексі́є, похва́льноє пі́ніє прино́сим ті, любо́вію чту́щії твоя́ по́двиги, терпі́ніє і многострада́ніє, і́миже Бо́гу угоди́л єси́ і яви́лся єси́ равноа́нгелен на землі́; ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свобожда́й, да зове́м ті:","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний бил єси́, Алексі́є блаже́нне, от млади́х бо літ житія́ твоєго́ чистоту́ душі́ і ті́ла соблю́л єси́ і Христу́ любо́вію усе́рдною послі́довал єси́, Єго́же взиску́я, вся кра́сная ми́ра сего́ оста́вил єси́ і дости́гл єси́ соверше́нства духо́внаго. Сего́ ра́ди сли́шиши от нас сія́ достодо́лжния тебі́ похвали́:","Ра́дуйся, ве́тхаго Ри́ма рожде́ніє;","ра́дуйся, безча́дних роди́телей непло́дія разріше́ніє.","Ра́дуйся, моли́тв усе́рдних плод богодарова́нний;","ра́дуйся, от младе́нчества на богоугожде́ніє сви́ше предизбра́нний.","Ра́дуйся, в стра́сі Бо́жиєм до́брі воспита́нний;","ра́дуйся, Зако́ну Госпо́дню ві́рно науче́нний.","Ра́дуйся, о небе́сних па́че, не́же о земни́х, помишля́вий;","ра́дуйся, самоотверже́ніє чу́дноє показа́вий.","Ра́дуйся, чистоту́ ді́вственную Христа́ ра́ди непоро́чно сохрани́вий;","ра́дуйся, обру́чницю, красото́ю цвіту́щую, Ісу́са ра́ди оста́вивий.","Ра́дуйся, му́дрий стра́нниче, оте́чества го́рняго взиска́вий;","ра́дуйся, Бо́жий ізбра́нниче, вся прило́ги ми́ра, пло́ті і дия́вола побіди́вий.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дів непостоя́нство красо́т ми́ра сего́, тлі́нію прича́стних, Алексі́є богому́дре, возлюби́л єси́ бла́га нетлі́нная ві́чная, Христо́м обітова́нная во Єва́нгелії ві́рним рабо́м Єго́; сего́ ра́ди дом роди́телей твої́х і все бога́тство їх оста́вил єси́, нищету́ же во́льную ізбра́л єси́, да Христу́ уго́ден бу́деши і возмо́жеши невозбра́нно пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́л єси́ до́брі, Алексі́є блаже́нне, я́ко жив'я́ в ми́рі, в супру́жестві і бога́тстві, неудо́б обря́щеши спасе́ніє; ті́мже торжеству́ бра́чному приспі́вшу, ти бра́ка внеза́пно уклони́лся єси́, предпочита́я в ді́вственній чистоті́ Бо́гу благоугожда́ти. О сем диві́мся і тебі́ зове́м хвале́бно:","Ра́дуйся, Христо́в люби́телю, мре́жею любве́ к ми́ру сему́ неуловле́нний;","ра́дуйся, Ісу́сов послі́дователю, пло́ті угожде́нія ізбежа́вий.","Ра́дуйся, висото́ю по́двига твоєго́ А́нгели удиви́вий;","ра́дуйся, крі́постію проізволе́нія твоєго́ де́мони посрами́вий.","Ра́дуйся, град оте́чествія твоєго́ оста́вивий, да Ви́шняго Гра́да наслі́діє обря́щеши;","ра́дуйся, в путь дале́кий і многоско́рбний потеки́й, да путі́ спаси́тельнаго прича́стник бу́деши.","Ра́дуйся, нищету́ самоізво́льную себі́ усво́ївий;","ра́дуйся, гла́дом і жа́ждею мно́гажди томи́мий.","Ра́дуйся, в моли́твах денноно́щних пребива́вий;","ра́дуйся, слеза́ми умиле́нія лице́ твоє́ ороша́вий.","Ра́дуйся, терпі́нія сто́лпе непоколеби́мий;","ра́дуйся, ві́ри адама́нте крі́пкий.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укрепле́нний, путь дале́кий соверши́л єси́ і гра́да Єде́са дости́гл єси́, Алексі́є достохва́льне, в не́мже, я́ко єди́н от ни́щих, пребива́л єси́ в злострада́нії і нищеті́, ко хра́му Бо́жию ви́ну примета́яся і моли́тви усе́рдния со мно́гими слеза́ми принося́ Христу́, Царю́ і Бо́гу, зови́й: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́л єси́, свя́тче Бо́жий, не́бо покро́вом і зе́млю одро́м упокоє́нія, ру́бища же убо́гая одія́нієм многоподви́жному твоєму́ ті́лу, зно́єм опаля́єму і мра́зом померза́єму, єму́же ні ма́лаго угожде́нія не попуска́л єси́, да не возоблада́єть плоть над ду́хом твої́м, любо́вію ко Го́споду пламене́вшим. В такові́м по́двизі твоє́м єди́но утіше́ніє Христа́ імі́л єси́, І́же і нам внуша́єть вопи́ти тебі́:","Ра́дуйся, от за́пада на восто́к прише́дий взиска́ти Со́лнця Пра́вди, Світ Невече́рній;","ра́дуйся, Того́ во глубині́ твоєго́ боголюби́ваго се́рдця обріти́й.","Ра́дуйся, світи́льниче Боже́ственнаго сія́нія, ми́ра конці́ озари́вий;","ра́дуйся, твої́ми христопосле́довательними стопа́ми Єде́с освяти́вий.","Ра́дуйся, пра́вило ві́ри і́стинния;","ра́дуйся, о́бразе нищети́ духо́вния.","Ра́дуйся, в душе́ твоє́й доброді́телі висо́кия возрасти́вий;","ра́дуйся, цілому́дрія сокро́вище драго́є сохрани́вий.","Ра́дуйся, Єва́нгелія Христо́ва до́брий храни́телю;","ра́дуйся, за́повідей Ісу́сових усе́рдний ісполни́телю.","Ра́дуйся, на землі́ небе́сно пожи́вий;","ра́дуйся, Бо́гу соверше́нно угоди́вий.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рю страсте́й ю́ношеських воздержа́нієм укроти́л єси́, свя́те Алексі́є, і посто́м сугу́бим ув'яди́л єси́ красоту́ лиця́ твоєго́; ті́мже возсія́ в душі́ твоє́й нетлі́нная красота́ благода́тнаго безстра́стія, благоуго́дная красні́йшему па́че сино́в челові́чеських Христу́, Єму́же во умерщвле́ннем тілесі́ сла́дці воспіва́л єси́ піснь хвали́ і благодаре́нія: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав кли́рик це́ркве Єде́ськия во виді́нії глас от іко́ни Богома́тере, челові́ком Бо́жиїм тя нариця́ющ, досто́йним Ца́рствія Небе́снаго, єго́же моли́тва, я́ко кади́ло благово́нноє, восхо́дить пред Лице́ Бо́жиє, і повеліва́ющ ввести́ тя внутр це́ркве от притво́ра, іді́же ни́щетно пребива́л єси́, удиви́ся зіло́ такові́й свя́тости твоє́й, Алексі́є богоблаже́нне, і введ тя в це́рков Госпо́дню, ублажа́ше тя зва́нії си́ми:","Ра́дуйся, Ду́ха Свята́го жили́ще, преукра́шенноє чистото́ю;","ра́дуйся, Бо́жия благода́ті прия́телище, сія́ющеє доброді́телей красото́ю.","Ра́дуйся, Бо́жия Ма́тере словеси́ похвале́нний;","ра́дуйся, Цари́цею небесе́ і землі́ челові́ком Бо́жиїм найменова́нний.","Ра́дуйся, і́м'я но́воє і та́їнственноє от Влади́чиці ми́ра получи́вий;","ра́дуйся, смире́нієм висо́кая стяжа́вий.","Ра́дуйся, нището́ю бога́тство нетлі́нноє сниска́вий;","ра́дуйся, по́честь ви́шняго зва́нія досто́йно восприя́вий.","Ра́дуйся, моли́тв благоприя́тноє кади́ло;","ра́дуйся, Ца́рствія Го́рняго ре́вностний іска́телю.","Ра́дуйся, в притво́рі церко́внім дні і но́щі моли́твенно провожда́вий;","ра́дуйся, внутр хра́ма Бо́жия повелі́нієм Богома́тере че́стно введе́нний.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́бился єси́, Алексі́є свя́те, єгда́ ізбіга́я сла́ви челові́чеськія, от Єде́са удали́лся єси́ во іни́я страни́, оба́че Бо́жиїм Про́мислом кора́бль, на не́мже плил єси́, ко оте́чественному твоєму́ гра́ду Ри́му принесе́ся. Ти же, позна́во в сем во́лю Госпо́дню та́мо тебі́ подвиза́тися, прите́кл єси́ к до́му роди́телей твої́х, і я́ко єди́н от ни́щих, у врат єго́ водвори́лся єси́, слеза́ми омива́я лице́ твоє́ і вопія́ ко Го́споду: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів тя боголюби́вий роди́тель твой, свя́те Алексі́є, стра́нна і ни́ща о́бразом, милосе́рдова о тебі́ і хи́жину ма́лу повелі́ сооруди́ти тебі́ у врат своєго́ до́ма, в не́йже пита́ше тя Христа́ ра́ди, отню́д не познава́я в тебі́ своєго́ си́на; ти же, ни́щетно в до́мі роди́тельстем пребива́я, вся́кую ну́жду стра́нничеськую і поноше́ніє ни́щенськоє претерпі́л єси́, подвиза́я ни благохвали́ти тя си́це:","Ра́дуйся, му́жество вели́коє показа́вий;","ра́дуйся, в терпі́нії мно́зім преуспі́вий.","Ра́дуйся, в до́мі роди́телей твої́х незна́єм пребива́вий;","ра́дуйся, скорб їх о лише́нії твоє́м всегда́ созерца́вий.","Ра́дуйся, сі́тованія отця́ твоєго́ сли́шавий;","ра́дуйся, сле́зи ма́тере твоєя́ ви́дівий.","Ра́дуйся, плач обру́чници твоєя́ позна́вий;","ра́дуйся, се́рдце твоє́ си́ми болі́зненно уязвля́вий.","Ра́дуйся, поноше́нія і укори́зни от слуг роди́телей твої́х незло́бно восприя́вий;","ра́дуйся, біє́нія і зауше́нія от них молчали́во переноси́вий.","Ра́дуйся, за оби́девшия тя непреста́нно Бо́га умоля́вий;","ра́дуйся, самоізво́лен му́ченик воі́стину би́вий.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропові́дник єва́нгельськия кро́тости бил єси́, свя́те Алексі́є, о́бразом житія́ твоєго́ многотерпіли́ваго всім показу́яй, я́ко вся возмо́жна челові́ку о укріпля́ющем Бо́зі, Єго́же си́лою в немощні́й пло́ті вели́кия по́двиги соверши́л єси́ і мно́гія страда́нія претерпі́л єси́ любве́ ра́ди Христо́ви, досто́йно і пра́ведно воспіва́я Пресвяті́й Тро́йце Серафи́мськую піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в дре́внем Ри́мі необича́йними по́двиги твої́ми, Алексі́є блаже́нне, і си́ми озари́л єси́ благода́тно всю Це́рков Христо́ву: кто бо не умили́ться, сли́ша твоє́ пачеєсте́ственноє терпі́ніє і мно́гая злострада́нія, в до́мі роди́телей твої́х восприя́тая самоізво́льно, і ка́ко, наслі́дник сий того́ до́ма, от слуг єго́ укори́зни і ра́ни преноси́л єси́ ра́достно. Сего́ ра́ди прино́сим ті от усе́рдія на́шего сія́ песноглаше́нія:","Ра́дуйся, вели́кий уго́дниче Христо́в, в ми́рі премі́рно пожи́вий;","ра́дуйся, равноа́нгельний слуго́ Госпо́день, многоболі́зненно жизнь твою́ препроводи́вий.","Ра́дуйся, безче́стіє в сла́ву себі́ вміни́вий;","ра́дуйся, ра́ни на ті́лі твоє́м терпіли́во носи́вий.","Ра́дуйся, лани́ти твоя́ от зауше́ній не уклони́вий;","ра́дуйся, плещи́ твоя́ на ударе́нія преда́вий.","Ра́дуйся, оплева́нія христоподража́тельно принима́вий;","ра́дуйся, молча́нієм на укори́зни отвеща́вий.","Ра́дуйся, во Христі́ утіше́ніє єди́но обріти́й;","ра́дуйся, воспомина́нієм кре́стних страда́ній Ісу́сових ско́рби твоя́ услажда́вий.","Ра́дуйся, великоду́шний многострада́льче;","ра́дуйся, добропобі́дний подви́жниче.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хоті́ніє єди́но імі́л єси́, челові́че Бо́жий, є́же благоугожда́ти Бо́гу; ті́мже вся вре́менная в уме́ти вміни́л єси́, і наслі́дник мно́гаго бога́тства бив, сіє́ оста́вил єси́, нищ і стра́нен пребива́я, в роди́тельстем до́ме непознава́єм і зіло́ уничижа́єм, при́сно воздиха́я ко Го́споду і сле́зно моля́ся, да сподо́бит тя в страні́ блаже́нства ві́чнаго пі́ти Єму́ со святи́ми: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́во і необича́йно тече́ніє соверши́л єси́ житія́ твоєго́, свя́те Алексі́є, среди́ ми́ра чу́ждо мирськи́х пристра́стій і вся́кия скве́рни гріхо́вния; ті́мже прия́л єси́ в душі́ твоє́й богові́дінія дар соверше́н і бил єси́ одушевле́нний храм Трисія́ннаго Божества́, в не́мже Христо́с со Отце́м і Ду́хом оби́тель Себі́ сотвори́, нас же научи́ зва́ти тебі́:","Ра́дуйся, А́нгелов подо́бниче і челові́ков красото́;","ра́дуйся, ри́зу душе́вную ді́вства чистото́ю убели́вий.","Ра́дуйся, в ра́дость Го́спода твоєго́ вше́дий;","ра́дуйся, доброво́льною нището́ю превозви́шенний.","Ра́дуйся, терпі́нієм твої́м с многострада́льним І́овом сравни́вийся;","ра́дуйся, уничиже́нієм твої́м єва́нгельському Ла́зарю подража́вий.","Ра́дуйся, болі́зньми мно́гими здра́віє душі́ стяжа́вий;","ра́дуйся, страда́ньми неісче́тними Ца́рствіє Христо́во приобріти́й.","Ра́дуйся, ве́тхаго Ри́ма благода́тноє обновле́ніє;","ра́дуйся, Це́ркве Христо́ви Боже́ственноє удобре́ніє.","Ра́дуйся, обітова́ній Ісу́сових наслі́дниче;","ра́дуйся, Пресвяти́я Тро́йці таї́нниче.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць, бил єси́ во гра́ді оте́чествія твоєго́, свя́те, ви́ну взиску́я Ви́шняго Гра́да, Ієрусали́ма Небе́снаго; єгда́же приспі́ вре́м'я отше́ствія твоєго́ к Бо́гу, ти на хартії́ та́йну житія́ твоєго́ начерта́л єси́, в позна́ніє твої́м роди́телем, і неосла́бно пребива́л єси́ в по́двизіх поста́ і моли́тви, приуготовля́яся ко ісхо́ду умиле́нним пі́нієм Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, Алексі́є свя́те, моли́тві би́вшей на уста́х твої́х, преда́л єси́ пра́ведную ду́шу твою́ в ру́ці Бо́жії ми́рно і безм'яте́жно, я́ко усну́л єси́; смерть бо тебе́ воі́стину упокоє́ніє бисть от страда́ній і подвиго́в непреста́нних, і прохожде́ніє от ху́ждшаго на лу́чшеє. О такові́м блаже́ннім успе́нії твоє́м ми ра́дующеся, сія́ прикла́дния тебі́ прино́сим глаго́ли:","Ра́дуйся, свя́тче Бо́жий, свя́то і пра́ведно жизнь земну́ю соверши́вий;","ра́дуйся, во благоуха́нії святи́ні сном сме́ртним опочи́вий.","Ра́дуйся, на ло́но Авраа́ма А́нгели несе́нний;","ра́дуйся, пі́нієм неземни́м от святи́х Небожи́телей встре́ченний.","Ра́дуйся, вінце́м безсме́ртния жи́зні от Го́спода увінча́нний;","ра́дуйся, во оби́телі ра́йськия со сла́вою восприя́тий.","Ра́дуйся, Пресві́тлоє Лице́ Влади́ки Христа́ ви́ну созерца́яй;","ра́дуйся, Пресвяті́й Тро́йці Трисвяту́ю піснь немо́лчно возглаша́яй.","Ра́дуйся, Созда́теля го́рних і до́льних моли́твами твої́ми умилостивля́яй;","ра́дуйся, весь мир христия́нський предста́тельством твої́м об'є́мляй.","Ра́дуйся, А́нгелов і челові́ков ра́дованіє;","ра́дуйся, почита́ющим святу́ю па́м'ять твою́ ві́рний хода́таю.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 9","ps":["Всі лю́діє ри́мстії в тре́петь прийдо́ша, сли́шавше глас в собо́рній це́ркві гра́да своєго́, во вре́м'я Боже́ственния литургі́ї сви́ше от олтаря́ глаго́лющ і повеліва́ющ поіска́ти тя, челові́че Бо́жий, да моли́тв твої́х сподо́б'яться. Ті́мже во удивле́нії і у́жасі би́вше, моли́твенно возопи́ша они́ ко Го́споду, да яви́ть їм тебі́, Своєго́ ізбра́нника, зову́ще ди́вному во святи́х Свої́х Влади́ці: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство челові́чеськоє не довлі́єть к похвале́нію тебі́, свя́те Алексі́є, сви́ше похвале́нному Гла́сом Боже́ственним, Єго́же ізвіще́нієм лю́діє ри́мстії обріто́ша тя, ме́ртва лежа́ща на одрі́, с хартіє́ю на лице́, є́же сія́ше солнцеподо́бними луча́ми, і благоуха́ніє ве́ліє ісхожда́ше от многоподви́жнаго твоєго́ тілесе́. Ті́мже обрі́тенієм твої́м обра́довани, цар, святи́тель і весь наро́д возгласи́ша тебі́:","Ра́дуйся, сві́тлий луче́ Трисо́лнечнаго Сві́та, оживля́ющаго весь мир;","ра́дуйся, денни́це, возше́дшая просвіща́ти Це́рков Христо́ву мно́гими чудеси́.","Ра́дуйся, свя́тости і чистоти́ кри́не благоуха́нний;","ра́дуйся, дарова́ній Боже́ственних сокро́вище.","Ра́дуйся, роди́телем твої́м хартіє́ю себе́ яви́вий;","ра́дуйся, плач їх го́рестний на сла́достний преложиви́й.","Ра́дуйся, сіди́ни отця́ твоєго́ прославле́нієм твої́м просла́вивий;","ра́дуйся, сле́зи ма́тере твоєя́ благода́тно вознагради́вий.","Ра́дуйся, честну́ю обру́чницю твою́, ві́рность тебі́ сохра́ншую, духо́вно уті́шивий;","ра́дуйся, весь наро́д ри́мський обрі́тенієм твої́м зіло́ возвесели́вий.","Ра́дуйся, ісціле́нія чуде́сная от святи́х моще́й твої́х оби́льно істочи́вий;","ра́дуйся, на небесі́ і на землі́ по́честь посме́ртную досто́йно восприя́вий.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим примі́р благи́й житіє́ твоє́, свя́те Алексі́є, і́мже вся ни поуча́єши отреша́тися сує́ть ми́ра, іска́ти же єди́но на потре́бу, є́же єсть богоугожде́ніє. Помози́ у́бо нам, челові́че Бо́жий, в сем тебі́ подража́ти, укріпи́ немощно́є проізволе́ніє на́ше, вдохни́ в нас му́жество душе́вноє, украси́ нас доброді́тельми і яви́ би́ти наслі́дники Ца́рствія Небе́снаго, да с тобо́ю на землі́ живи́х воспоє́м Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ ві́рний послі́дователь бил єси́, Алексі́є блаже́нне, Єго́же Стра́шному Престо́лу ни́ні предстої́ши во сла́ві небе́сній, о не́йже ми, земні́ї і пе́рстнії, ніже́ поми́слити мо́жем; оба́че любо́вію усе́рдною к тебі́ понужда́єми, ми́сленно созерца́єм тя, го́ре за ни моля́щагося пред лице́м Бо́жиїм, і бре́нними усти́ возсила́єм ті пі́ніє таково́є:","Ра́дуйся, ві́рно чту́щим тя ско́рий помо́щниче;","ра́дуйся, моли́твенно призива́ющих тя усе́рдний засту́пниче.","Ра́дуйся, пра́ведниче Госпо́день, Єго́же Пра́вда возсія́ немерца́ємо;","ра́дуйся, соль землі́, я́же нікогда́же обуя́єть.","Ра́дуйся, до́брими ді́ли твої́ми Бо́га просла́вивий і челові́ки удиви́вий;","ра́дуйся, житіє́м твої́м А́нгели возвесели́вий і ду́хи тьми посрами́вий.","Ра́дуйся, Го́рняго Ми́ра украше́ніє;","ра́дуйся, до́льняго ми́ра защище́ніє.","Ра́дуйся, Ри́ма сла́во і похвало́;","ра́дуйся, христия́нськаго ро́да возвише́ніє.","Ра́дуйся, в чудесі́х просія́вий;","ра́дуйся, в ми́лостіх неістощи́мий.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє надгро́бноє со сла́вою тебі́ сотвори́ша, свя́те Алексі́є, цар, святи́тель і весь наро́д ри́мський, роди́телем твої́м і обру́чниці твоє́й, возсле́дующим честно́му твоєму́ гро́бу, несе́нному благолі́пно в собо́рную це́рков, от него́же чуде́с мно́жество істочи́л єси́: сліпі́ї прозира́ху, разсла́бленнії укріпля́хуся, неду́жнії здра́ві бива́ху прикоснове́нієм к моще́м твої́м святи́м, во є́же всім ви́дящим такова́я возглаша́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тло і ра́достно бисть погребе́ніє твоє́, челові́че Бо́жий, сві́тел бо лице́м возлежа́л єси́ во гро́бі і благоуха́ніє сла́достноє іспуща́л єси́ от нетлі́ннаго твоєго́ тілесе́, си́ми зна́менуя сві́тлость немерца́ющую святи́я твоєя́ душі́, во воню́ благоуха́нія Христо́ва прите́кшия і ми́ра Боже́ственнаго преіспо́лненния, от єя́же полноти́ і в на́ша ду́ші пода́ждь дая́ніє благода́тноє, да со утіше́нієм духо́вним тебі́ возопіє́м:","Ра́дуйся, свіще́ неугаси́мая, в моли́твах к Бо́гу го́ре возжже́нная;","ра́дуйся, лампа́до злата́я, єле́єм ми́лости до́лу живу́щих умаща́ющая.","Ра́дуйся, алава́стре драги́й, ми́ро целе́бноє боля́щим істоча́яй;","ра́дуйся, ріко́ многово́дная чуде́с.","Ра́дуйся, і́ночествующим наста́вниче до́браго по́двига;","ра́дуйся, в ми́рі живу́щим о́бразе богоугожде́нія.","Ра́дуйся, зерца́ло чи́стоє пра́веднаго житія́;","ра́дуйся, приста́нище благооти́шноє по Бо́зі упова́ніє на тя возложи́вших.","Ра́дуйся, враго́в неви́димих крі́пкий противобо́рче;","ра́дуйся, і́щущим спасе́нія душе́внаго благи́й споспі́шниче.","Ра́дуйся, от небе́сних висо́т к земноро́дним ми́лостивно приника́яй;","ра́дуйся, чту́щих тя проше́нія ско́ро ісполня́яй.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость іспроси́ нам у Христа́, Царя́ і Бо́га на́шего, Алексі́є достохва́льне; ві́ми бо, я́ко мно́го мо́жеть моли́тва твоя́ пред Лице́м Єго́, і благоуве́тливо преклоня́ється Он к моле́нію твоєму́. Ті́мже усе́рдно к тебі́ прибіга́єм і смире́нно про́сим: окорми́ нас предста́тельством твої́м в ти́хоє приста́нище Христо́во і сподо́би наслажда́тися нетлі́нния ра́дості святи́х, немо́лчно вопію́щих славосло́вія піснь Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиги многострада́льнаго і преди́внаго житія́ твоєго́, челові́че Бо́жий, хва́лим, сла́вим і ублажа́єм тя усе́рдною любо́вію, я́ко небе́снаго многомо́щнаго предста́теля на́шего; ти же, свя́те, да́нною ті сви́ше благода́тію нас, грі́шних і мра́чних, освяти́, просвіти́ і наста́ви вопи́ти тебі́ неосужде́нно:","Ра́дуйся, восто́ка незаходи́маго присносія́ющая заре́;","ра́дуйся, вселе́нную твої́ми чудеси́ іспо́лнивий.","Ра́дуйся, моща́ми твої́ми пресла́вно чудотворя́й;","ра́дуйся, образми́ подо́бія твоєго́ преди́вная соверша́яй.","Ра́дуйся, боля́щих безме́здний врачу́;","ра́дуйся, скорб'я́щих благи́й уті́шителю.","Ра́дуйся, унива́ющих благода́тноє ободре́ніє;","ра́дуйся, ізнемога́ющих внеза́пноє укріпле́ніє.","Ра́дуйся, бе́дствующим на по́мощ ускоря́яй;","ра́дуйся, от житія́ отходя́щим заступле́ніє твоє́ многомо́щноє явля́яй.","Ра́дуйся, ра́дости духо́вния боголюби́вим душа́м пода́телю;","ра́дуйся, благ вре́менних і ві́чних усе́рдний нам у Го́спода проси́телю.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 13","ps":["О святи́й і богопросла́вленний челові́че Бо́жий Алексі́є! Тебі́, го́ре за ни моля́щемуся пред Престо́лом Го́спода Сла́ви, ми грі́шнії, до́лу живу́щії, сіє́ ма́лоє принося́ще пі́ніє, мо́лимся от всея́ душі́ і от всего́ помишле́нія: моли́твами твої́ми іспроси́ нам у Христа́ Бо́га проще́ніє согріше́ній і по кончи́ні на́шея жи́зні прия́тіє в блаже́нния оби́телі Небе́снаго Ца́рствія, да с тобо́ю во ві́ки поє́м Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний бил єси́, Алексі́є блаже́нне, от млади́х бо літ житія́ твоєго́ чистоту́ душі́ і ті́ла соблю́л єси́ і Христу́ любо́вію усе́рдною послі́довал єси́, Єго́же взиску́я, вся кра́сная ми́ра сего́ оста́вил єси́ і дости́гл єси́ соверше́нства духо́внаго. Сего́ ра́ди сли́шиши от нас сія́ достодо́лжния тебі́ похвали́:","Ра́дуйся, ве́тхаго Ри́ма рожде́ніє;","ра́дуйся, безча́дних роди́телей непло́дія разріше́ніє.","Ра́дуйся, моли́тв усе́рдних плод богодарова́нний;","ра́дуйся, от младе́нчества на богоугожде́ніє сви́ше предизбра́нний.","Ра́дуйся, в стра́сі Бо́жиєм до́брі воспита́нний;","ра́дуйся, Зако́ну Госпо́дню ві́рно науче́нний.","Ра́дуйся, о небе́сних па́че, не́же о земни́х, помишля́вий;","ра́дуйся, самоотверже́ніє чу́дноє показа́вий.","Ра́дуйся, чистоту́ ді́вственную Христа́ ра́ди непоро́чно сохрани́вий;","ра́дуйся, обру́чницю, красото́ю цвіту́щую, Ісу́са ра́ди оста́вивий.","Ра́дуйся, му́дрий стра́нниче, оте́чества го́рняго взиска́вий;","ра́дуйся, Бо́жий ізбра́нниче, вся прило́ги ми́ра, пло́ті і дия́вола побіди́вий.","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в, сви́ше нарече́нний челові́че Бо́жий, свя́те Алексі́є, похва́льноє пі́ніє прино́сим ті, любо́вію чту́щії твоя́ по́двиги, терпі́ніє і многострада́ніє, і́миже Бо́гу угоди́л єси́ і яви́лся єси́ равноа́нгелен на землі́; ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свобожда́й, да зове́м ті:","Ра́дуйся, челові́че Бо́жий Алексі́є, моли́твенниче о душа́х на́ших."]},{"h":"Молитва","ps":["О вели́кий Христо́в уго́дниче, святи́й челові́че Бо́жий Алексі́є, душе́ю на небесі́ Престо́лу Госпо́дню предстоя́й, на землі́ же да́нною ті сви́ше благода́тію разли́чная соверша́яй чудеса́! При́зри ми́лостивно на предстоя́щия святі́й іко́ні твоє́й лю́ди, умиле́нно моля́щіяся і прося́щия от тебе́ по́мощі і заступле́нія. Простри́ моли́твенно ко Го́споду Бо́гу честні́ї ру́ці твої́ і іспроси́ нам от Него́ оставле́ніє согріше́ній на́ших во́льних і нево́льних, в неду́зіх стра́ждущим ісціле́ніє, напа́ствуємим заступле́ніє, скорб'я́щим утіше́ніє, бе́дствующим ско́рую по́мощ, всім же чту́щим тя ми́рную і христия́нськую живота́ кончи́ну і до́брий отві́т на Стра́шнім Суді́ Христо́ві. Єй, свя́тче Бо́жий, не посрами́ упова́нія на́шего, є́же на тя по Бо́зі і Богоро́дице возлага́єм, но бу́ди нам помо́щник і покрови́тель во спасе́ніє, да твої́ми моли́твами получи́вше благода́ть і ми́лость от Го́спода, просла́вим человіколю́біє Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці сла́вимаго і покланя́ємаго Бо́га, і твоє́ свято́є заступле́ніє ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Возви́сився на доброді́тель і ум очи́стив, / к жела́нному і кра́йнему дости́гл єси́, / безстра́стієм же украси́в житіє́ твоє́ / і поще́ніє ізря́дноє восприї́м со́вістію чи́стою, / в моли́твах, я́ко безпло́тен, пребива́я, / возсія́л єси́, я́ко со́лнце, в ми́рі, // преблаже́нне Алексі́є."]},{"h":"Інший тропар, глас 4","ps":["Я́ко чистоти́ світи́льник пресві́тел показа́ся, / ди́вний Алексі́є, / і́бо тлі́нний черто́г / на нетлі́нноє Бо́жиє Ца́рствіє преміни́в, / я́ко цілому́дрія ді́латель преізря́ден. / Сего́ ра́ди предстої́ши Го́сподеві, всіх Царю́. // Єго́же моли́, дарова́ти нам мир і ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Дом роди́телей твої́х я́ко чужд імі́в, / водвори́лся єси́ в нем нищеобра́зно / і, по преставле́нії віне́ць приє́м сла́ви, / ди́вен на землі́ яви́лся єси́, Алексі́є, челові́че Бо́жий, // А́нгелом і челові́ком ра́дованіє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Алексі́є, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святим мученицям Євдокії, Дарії, Дарії і Марії","e":"Akathist to the Holy Martyrs Eudocia, Daria, Daria and Maria","secs":[{"h":"Кондак 1","ps":["Ізбранниє уго́дниці і стратотерпиці Христо́ви, ми́ра сего́ безу́міє обличившиє і благодатниє да́ри істоча́ющії, восхваля́єм вас любо́вію: ви же імі́ющії на врага́ побі́ду, от бід і напа́стей свободи́те нас, да зове́м вам:","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Ікос 1","ps":["А́нгелов сонм удиви́ся єстеству́ ва́шему, му́ченици, я́ко на землі́ небе́сному жи́тельству уподобля́яся, вся бла́га вре́менная отри́нувши і Єди́ному Христу́ апо́стольськи послі́довавши, я́ко лучи́ солнечниє ми́ру возсія́ли єсте́: та́ко і Госпо́дь чудеса́ми прославля́я по́двиги ва́ша, научи́ воспіва́ти вам такова́я:","Ра́дуйся, Євдокі́є, ча́шу страда́ній Христо́вих до конця́ іспившая;","Ра́дуйся, юро́дством глубину́ му́дрости от челові́к сокрившая.","Ра́дуйся, я́ко го́рлиця о єди́ном Женихе взивающая;","Ра́дуйся, моли́твою своє́ю жизнь на́шу огражда́ющая.","Ра́дуйтеся, му́ченици, по́двигам блаже́нния Євдокі́ї подража́ющії;","Ра́дуйтеся, си́лу Креста́ Госпо́дня, я́ко тверди́ню необори́мую прославля́ющії.","Ра́дуйтеся, пропові́дници Сві́та Христо́ва:","Ра́дуйся, тихії моли́твенниці во времена́ тяжкії.","Ра́дуйтеся, му́ченици, я́ко мудриє ді́ви єле́єм світи́льники наполнившії:","Ра́дуйтеся, я́ко а́гнці непорочниє на закла́ніє ведомиє.","Ра́дуйтеся, зе́млю Ніжегородськую освящающії;","Ра́дуйся, ми́ра конці́ облиста́ющії.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 2","ps":["Ви́дяще земна́го существа́ не́мощ, сиротство без ма́тері от младе́нства і во отро́честві мно́гі ско́рбі претерпі́вши, му́ченице Євдокі́є, печа́ль свою́ на Бо́га возложи́вши, те́плою моли́твою к Засту́пниці Усердной взива́ла єси́: Аллилуя."]},{"h":"Ікос 2","ps":["Ра́зум го́рних чино́в Боже́ственною Прему́дростію открива́яся вам, му́ченици, єгда́ бре́ннаго ті́ла отверго́шася, в непреста́нном служе́нії Бо́гу пребивали єсте́; пі́нієм, бді́нієм і поще́нієм о́браз подая́ любо́вію воспіва́ющим вам:","Ра́дуйся, му́ченице Євдокі́є, от ю́ности Христа́ всім се́рдцем возлюби́вшая;","Ра́дуйся, благослове́ніє от Преподо́бнаго Серафи́ма во отро́честві своє́м прия́вшая.","Ра́дуйся, ізмла́да псало́мськи і́скренняго своєго́ не отмета́яся;","Ра́дуйся, за то біє́нія і мета́нія камней от осуждающих теб'я́ претерпі́вшая.","Ра́дуйся, по́двигу блаже́нния Пелагеї Дивеєвськой возревновавшая;","Ра́дуйся, я́ко незло́бієм свої́м Бо́гу угоди́вшая.","Ра́дуйся, стяжа́ніє земна́го удаля́яся, к стяжа́нію благода́ті Ду́ха Свята́го ум і се́рдце приблизившая;","Ра́дуйся, я́ко непоколеби́мо во́лі Бо́жієй предалася єси́.","Ра́дуйся, Да́ріє, споспі́шнице в по́двизіх досточу́дная;","Ра́дуйся, я́ко послуша́ніє затво́рнику Анатолію Саро́вському іспо́лнившая.","Ра́дуйся, пі́нію псалмо́в і стихи́р безкнижно науче́нная;","Ра́дуйся, я́ко смире́нієм свої́м просія́ла єси́.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго, ско́рби і болі́зні претерпіва́я, в по́двизіх не оскудевали єси́, но доброді́телі умножа́я, воспіва́ли Бо́гу: Аллилуя."]},{"h":"Ікос 3","ps":["Імі́яй благодатниє да́ри в се́рдці своє́м, блаже́нная Євдокі́є. Безмо́лвнаго житія́ возжелі́в і от сла́ви под покро́вом юро́дства от ми́ра укрива́яся, за наро́д в бе́здну безбо́жия влеко́мий, к Бо́гу со слеза́ми взива́ла єси́; ми же ві́дуще сіє́, поє́м такова́я:","Ра́дуйся, Євдокі́є, нищету́ Христо́ву возлюби́вшая;","Ра́дуйся, лице́ своє́ от ми́ра сокрившая.","Ра́дуйся, я́ко пі́ніє моли́тв, єди́ноє бисть тебі́ утіше́ніє;","Ра́дуйся, я́ко терпі́ла на ті́лі своє́м оде́жди тлі́ніє.","Ра́дуйся, суєту́ земну́ю отлагающая;","Ра́дуйся, в моли́тві і по́сте день і ноч пребива́ющая.","Ра́дуйся, нелицемерной любо́вію се́рдця приходя́щих к тебі́ ум'ягча́ющая;","Ра́дуйся, заботою о жи́зні бли́жніх і да́льних люде́й моли́твенно усердствующая.","Ра́дуйся, Марі́є, ві́рность Бо́гу в служе́нії ста́риці своє́й засвидетельствавшая;","Ра́дуйся, простото́ю се́рдця своєго́ єй последовавшая.","Ра́дуйся, послуша́нієм і смире́нієм пло́ті Ду́ха Свята́го стяжа́вшая;","Ра́дуйся, повелі́нієм Святи́теля Никола́я с ві́рою іспо́лнившая.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 4","ps":["Бу́рю помишле́ній сумни́тельних от умноже́нія беззако́ній імі́яй лю́діє землі́ на́шея, к тебі́, блаже́нная Євдокі́є. Я́ко к ти́хому приста́нищу прибегали, ско́рби свої́ на тя возлага́я; ти же научала всіх пі́ти Бо́гу: Аллилуя."]},{"h":"Ікос 4","ps":["Сли́шаша па́стиріє о мно́гих по́двизіх твої́х, блаже́нная Євдокі́є, і о́браз житія́ твоєго́, я́ко уго́дний Бо́гу ви́дя, напраляли лю́ди к твоєму́ пред Бо́гом о них хода́тайству, восхваля́я любо́в твою́ ко Го́споду, воспіва́ющи такова́я:","Ра́дуйся, Євдокі́є, не челові́чеськоє, но Бо́жиє разуміва́ющая;","Ра́дуйся, вві́ренних тебі́ от Бо́га путе́м у́зьким к Ца́рству Небе́сному ві́дущая.","Ра́дуйся, подо́бно І́ову многострада́льному в болі́зні Бо́га прославля́ющая;","Ра́дуйся, временноть і тлі́нность житія́ сего́ я́вно всім показу́ющая.","Ра́дуйся, Да́ріє, моли́твой непреста́нной і́м'я Бо́жиє призива́ющая;","Ра́дуйся, сло́ва блаже́нной Євдокі́ї в се́рдці своє́м вмещающая.","Ра́дуйся, тве́рдостію ду́ха сла́вная;","Ра́дуйся, Божественного орга́на сладкозвучная струно.","Ра́дуйтеся, му́ченици, Бо́жия Ма́тері всегдашніє моли́твенниці;","Ра́дуйтеся, Цари́ці Небе́сній хвале́бную піснь вознося́щії.","Ра́дуйтеся, і́ночеськаго житія́ добриє ревни́тели;","Ра́дуйтеся, общего житія́ ізбранниє сосу́ди.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ чети́рми концями не́бо облиста́ющую, зрим вас чети́ре му́ченици Росси́йстії єгда́ небоя́зненно ві́ру во Христа́ ісповедовали єси́, в ра́дості взива́я Єму́: Аллилуя."]},{"h":"Ікос 5","ps":["Ви́дя враг ро́да христия́нськаго богоуго́дноє житіє́ ва́ше, не винося терпі́ти огня́ пла́менних моли́тв ва́ших, святі́ї, подосла лука́ваго челові́ка, Бо́жиє на земно́є променявшаго, на вас же всю не́нависть богоотступной вла́сті наве́дшаго, я́ко тать біжа́; ви же, святі́ї му́ченици, не осудили сего́, но безро́потно в руци Бо́жий жизнь свою́ пре́дали єсте́. Та́ко, ви́дя кро́тость ва́шу, умиле́нно глаго́лем вам сицева́я:","Ра́дуйся, Євдокі́є, Крестним зна́менієм бісо́в прогоня́ющая;","Ра́дуйся, от рассвета до полу́дні моли́тву та́йную творившая.","Ра́дуйся, ви́дя грядушії іспита́нія, му́жеству бли́жніх свої́х науча́ющая;","Ра́дуйся, в ті́лі немощно́м крі́пость ду́ха вели́кую стяжа́вшая.","Ра́дуйся, Да́ріє, кро́тости іспо́лненная;","Ра́дуйся, в любві́ ко Христу́ земна́го жениха́ удали́лася єси́.","Ра́дуйся, сла́дость вре́менную презревшая;","Ра́дуйся, от сро́дник свої́х поноше́ніє претерпі́вшая;","Ра́дуйтеся, му́ченици. Мно́гими по́двигами просія́вший;","Ра́дуйтеся, в простоті́ голубиней се́рдця своя́ соблю́дший.","Ра́дуйтеся, странности ста́риці ва́шея терпіли́во сносивший;","Ра́дуйтеся, от собла́зна і неві́рія устоявшії.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 6","ps":["Про́повідь і́стини бисть житіє́ ва́ше святі́ї, я́ко путе́м ско́рбним і тру́дним вни́дем в Ца́рство Небе́сноє: та́ко ви са́мі себеї малого лишили в сем вре́менном ві́ці, купу́я драгоці́нний би́сер - Христа́ в жи́зні нескончаємой, непреста́нно поя́ Єму́: Аллилуя."]},{"h":"Ікос 6","ps":["Возсія́ла я́ко пресві́тлая заря́, блаже́нная Євдокі́є, мрак гріхо́вний разгоня́ющая і приходя́щих к тебі́ от сіте́й вра́жиїх ізима́ющая. Ми же, усердной о нас Бо́гу хода́тайце, любо́вію воспіва́єм та́ко:","Ра́дуйся, Євдокі́є, сві́та Єва́нгельськаго свечо;","Ра́дуйся, цілому́дрія сто́лпе.","Ра́дуйся, гріхо́в тя́жких му́драя обличи́тельнице;","Ра́дуйся, я́ко ні єди́ноє сло́во твоє́ бессмисленно бисть.","Ра́дуйся, се́рдця нераскаянния покая́нієм врачу́ющая;","Ра́дуйся, о грі́шних лю́діх сле́зи пролива́ющая.","Ра́дуйся, колокола́ звон, я́ко глас Госпо́день провещавающая;","Ра́дуйся, моли́твою своє́ю усо́пших не оставля́ющая.","Ра́дуйтеся, му́ченици дре́вніх пустинножи́телей послі́дователі;","Ра́дуйтеся, стужу́ і глад доброво́льно претерпі́вшії.","Ра́дуйтеся, от уни́нія і тревоги свобожда́ющії;","Ра́дуйтеся, безбо́жия і зло́би о́крест живу́щих не убоявшіїся.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 7","ps":["Хотя́ боголюби́вий Архимандри́т Софро́ній оповестити тя о ско́рой му́ченичеськой кончи́ні твоє́й, написа́ О́браз Христа́ в терновом вінці́ і я́ко дар в день А́нгела твоєго́ посла́ тебі́: ти же, блаже́нная, не приє́мше іко́ну сію́, віне́ць же Христо́в на главу́ свою́ восприя́ла єси́, воспіва́я Єму́: Аллилуя."]},{"h":"Ікос 7","ps":["Но́вих му́чеников собо́р украша́єте ви, святи́є жени́, за Христа́ пострадавшиє, єгда́ Бо́га в Тро́йці, я́ко Єди́наго Созда́теля душ і тіле́с на́ших, безбоя́зненно пред мучи́телі іспові́дасте, та́ко пе́рвим му́ченикам христия́нським воі́стину сро́дниці яви́лися; ми же, взира́я на таково́є му́жество ва́ше, хвале́бноє воспіва́єм вам пі́ніє:","Ра́дуйся, Євдокі́є, стопа́м созда́вшаго вся, Бо́жия Сло́ва, последовавшая;","Ра́дуйся, сопричастницями бли́жніх свої́х сему́ соделовавшая.","Ра́дуйся, Христо́вою любо́вію распаляємая, і́щуще я́же Бо́гу уго́дная;","Ра́дуйся, прия́телище Ду́ха Всесвята́го яви́лася єси́.","Ра́дуйся, Марі́є, воздержа́нієм ті́ло ду́ху поработившая;","Ра́дуйся, путь стра́нничества возлюби́вшая.","Ра́дуйся, благослове́ніє на служе́ніє блаже́нной Євдокі́ї с ві́рою прия́вшая;","Ра́дуйся, я́ко ві́рний во́їн при наше́ствії враго́в не малодушествующая.","Ра́дуйтеся, му́ченици, духо́вною благода́тію неду́ги от'ємлющії;","Ра́дуйтеся, ду́хи лука́вия отгоняющії.","Ра́дуйтеся, стра́сті неісці́льния ісціля́ющії;","Ра́дуйтеся, неві́рних к ві́рі приводящії.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ви́дим на тебі́, му́ченице Євдокі́є, єгда́ три дні і три нощі́ ізбиваєма плетьми і нога́ми затаптиваєма отрядом неі́стовствующих богобо́рцев; я́ко безгласная а́гниця вся претерпіва́ла єси́, взива́ла єди́ному Бо́гу: Аллилуя."]},{"h":"Ікос 8","ps":["Всім Хода́тайця Неізмі́нная, Сама́ Цари́ця Небе́сная незри́мо простирала Покро́в свой над ва́ми, му́ченици Госпо́дні, єгда́ узрі́в і́нок - іконописець чу́дноє виді́ніє Оранськой Бо́жієй Ма́тері на возду́сі моля́щуюся над ти́хой келієй ва́шей, со слеза́ми проще́нія у теб'я́ іспроси́, блаже́нная Євдокі́є, я́ко написа́ тебі́ о́браз сей; ми же сли́ша о чу́дном явле́нії, воспіва́єм ва́шу па́м'ять пресві́тлую:","Ра́дуйся, Євдокі́є, благ ві́чних, как єдиного счастья лю́дем жела́ющая;","Ра́дуйся, приходя́щих к тебі́ к моли́тві серде́чной призива́ющая.","Ра́дуйся, о Го́рнем помишля́ти науча́ющая;","Ра́дуйся, от огненного запале́нія до́ми ві́рних огражда́ющая.","Ра́дуйся, Да́ріє, а́гнице незло́бивая;","Ра́дуйся, открове́нієм помисло́в се́рдце чи́сто до конця́ сохранившая.","Ра́дуйся, в келії блаже́нной Євдокі́ї до́лгий затво́р на себ'я́ прия́вшая;","Ра́дуйся, все ско́рби духо́вною ра́достію претерпевающая.","Ра́дуйтеся, му́ченици я́ко мног труд і ті́сен путь в житії́ своє́м прешли́ єсте́;","Ра́дуйтеся, мона́шествующих столпи́ крепції.","Ра́дуйтеся, вся я́же в житії́ сем кра́сная презрі́ли єсте́;","Ра́дуйтеся, взявшії на ра́мена своя́ Крест Христо́в.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 9","ps":["Все єстество́ А́нгельськоє удиви́ся, єгда́ ви́діша Ду́ха Свята́го, я́ко го́луб'я, крила́ми свої́ми от плетей вас огражда́ющаго і благода́тію своє́ю покрива́ющаго вас, му́ченици, ведо́мих на казнь, в ра́дості взива́ющих Єму́: Аллилуя."]},{"h":"Ікос 9","ps":["Виті́я красноглаголивії не возмо́гуть ізрещи́ благолі́піє лико́во ва́ших, святі́ї, єгда́ стоя́ли пред убива́ющими ті́ла ва́ша, душі́ же не могу́щими косну́тися; ми же воспіва́єм вам такова́я:","Ра́дуйся, Євдокі́є, му́дрости Бо́жия вмісти́лище;","Ра́дуйся, о себі́ ні єди́ния жа́лости не приє́млющая.","Ра́дуйся, терпі́ніє бли́жніх свої́х, я́ко зла́то в горни́лі закаляющая;","Ра́дуйся, причудами свої́ми от всего́ земного отстраняющая.","Ра́дуйся, Да́ріє, под Бо́гом ходи́вшая;","Ра́дуйся, с любо́вію блаже́нной Євдокі́є послужи́вшая.","Ра́дуйся, я́ко Псалми́ Дави́дови от нача́ла до конця́ каждодневно воспіва́ющая;","Ра́дуйся, благ нрав і послуша́ніє к наста́вниці твоє́й імі́ла єси́.","Ра́дуйтеся, му́ченици, светлиє голуби́ці;","Ра́дуйтеся, неув'ядаємиє цві́ти ра́йстії.","Ра́дуйтеся, в печа́ліх утіше́ніє;","Ра́дуйтеся, в ско́рбіх помо́щници.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́чеський, Госпо́дь Вседержи́тель, подає́ть о́браз спасе́нія во святи́х Свої́х, правосла́вную ві́ру утверди́вших і доброді́тельми просія́вших, нас же научающих пі́ти Бо́гу: Аллилуя."]},{"h":"Ікос 10","ps":["Стіна́ неруши́мая Пресвята́я Влади́чице Богоро́дице в о́бразі іко́ни Своєя́ І́верськия ізнесена бисть нечести́вими із келії блаже́нной Євдокі́ї, вслід вам, му́ченици; тогда́ ви́діша лю́діє всі, сія́ніє от Нея́ ісходя́щеє; ми же научи́шася пі́ти вам похва́льная:","Ра́дуйся, Євдокі́є, к двенадцяти лампа́дам, я́ко к двенадцяти апо́столом во вре́м'я моли́тви лице́ своє́ обраща́ющая;","Ра́дуйся, апо́стольських пра́вил рачительнице.","Ра́дуйся, строгая обличи́тельнице непра́вди;","Ра́дуйся, со́вісти чи́стой от вся́каго неукло́нно требовавшая.","Ра́дуйся, Марі́є, со спокойной душе́ю на закла́ніє прише́дшая;","Ра́дуйся, смерть от штика претерпі́вшая.","Ра́дуйся, от ми́ра сокрившися, ми́ру возсія́вшая;","Ра́дуйся, во́лею за Христа́ пострада́вшая.","Ра́дуйтеся, му́ченици, моли́твами свої́ми от вся́кия скве́рни нас ограждающії;","Ра́дуйтеся, душі́ ві́рних веселящії.","Ра́дуйтеся, неугасимия світи́льници Россі́йськия землі́;","Ра́дуйтеся, Бо́жия благода́ті неіссякаємиє струї́.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 11","ps":["Пі́ніє непреста́нноє возноси́ли А́нгелов Чи́ни і Ви́шніх стоя́нія над многоскорбними тілеса́ми ва́шими, святі́ї му́ченици, єгда́ Воззва́вий вас к ві́чним Оби́телем, ви́ді я́рость люде́й, зло́бою врага́ ро́да челові́чеськаго одержи́мих, возбраня́ющих ві́рним пі́ти: Аллилуя."]},{"h":"Ікос 11","ps":["Світоза́рним сія́нієм, озаряющим зе́млю на́шу, яви́стеся святі́ї му́ченици, єгда́ і по сме́рті ва́шей подаєте́ ісціле́нія і от бід спасе́ніє; та́ко притека́яй к вам, я́ко к ти́хому приста́нищу, со умиле́нієм поє́м:","Ра́дуйся, Євдокі́є, с одра́ болі́зні на ло́но Авраа́мово возше́дшая;","Ра́дуйся, мзду за труди́ строїтелям келії Небе́сним Черто́гом уплатившая.","Ра́дуйся, у оскорбля́ющих теб'я́ проще́ніє іспросившая;","Ра́дуйся, молча́нієм свої́м пред судившими теб'я́ Христу́ последовавшая.","Ра́дуйся, Да́ріє, о́гненний сто́лпе, непреста́нно горевший к Бо́гу;","Ра́дуйся, дух ра́дости апо́стольськи возогревающая.","Ра́дуйся, блаже́нной Євдокі́ї ті́ло немощно́є, я́ко сосу́д драгоці́нний поне́сшая:","Ра́дуйся, я́ко ста́риця твоя́ от мучи́телей смерть прия́в, ду́шу свою́ святу́ю на рука́х твої́х Бо́гу предала́ єси́.","Ра́дуйтеся, му́ченици, ко крестам, я́ко на Голго́фу приведенния;","Ра́дуйтеся, я́ко дости́гли єсте́ ти́хаго приста́нища і ра́дости неізрече́нния.","Ра́дуйтеся, я́ко ко́сті ва́ша істоча́ють чудеса́ і ісціле́нія;","Ра́дуйтеся, мно́гих спасе́ніє.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 12","ps":["Благода́тную жизнь во Христі́ показа́ша святі́ї пра́ведници та́ко светолитними вінця́ми увінча́ вас Госпо́дь, Єму́ же всі поє́м: Аллилуя."]},{"h":"Ікос 12","ps":["Пою́ще піснь хвале́бную, премно́гими глаго́ли не возмо́жем ізрещи́ крі́пость любве́ ва́шей ко Го́споду, я́ко до конця́ возлюби́ли і до конця́ претерпі́ли; сего́ ра́ди велича́єм вас:","Ра́дуйся, Євдокі́є, цві́те ра́йський ди́вно процві́тшій;","Ра́дуйся, страда́нія Христо́ви поне́сшая.","Ра́дуйся, прозрі́нієм гряду́щая возвіща́ющая;","Ра́дуйся, прибегающим к твоєму́ заступле́нію, по́мощ ско́ро подаю́щая.","Ра́дуйся, по́лчища бісо́в посрами́вшая;","Ра́дуйся, от плі́на вражего ка́ющихся свобожда́ющая.","Ра́дуйся, ізбавле́ніє от печа́лі;","Ра́дуйся, устране́ніє собла́знов.","Ра́дуйтеся, му́ченици, неіссякаємий кла́дезь Бо́жия благода́ті;","Ра́дуйтеся, тишину́ і мир утвержда́ющий.","Ра́дуйтеся, ієре́єв хвале́бная піснь;","Ра́дуйтеся, мона́шествующих ра́досте.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 13","ps":["О, святі́ї му́ченици, Євдокі́є, Да́ріє, Да́ріє і Марі́є, приймі́те піснь сію́, прославляющую досточу́дноє житіє́ і я́же за Христа́ страда́нія ва́ша; ни́ні же Лицю́ Бо́жию предстоя́ і Пречи́стій Єго́ Ма́тері, молі́те о нас, пою́щих Бо́гу: Аллилуя, Аллилуя, Аллилуя.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов сонм удиви́ся єстеству́ ва́шему, му́ченици, я́ко на землі́ небе́сному жи́тельству уподобля́яся, вся бла́га вре́менная отри́нувши і Єди́ному Христу́ апо́стольськи послі́довавши, я́ко лучи́ солнечниє ми́ру возсія́ли єсте́: та́ко і Госпо́дь чудеса́ми прославля́я по́двиги ва́ша, научи́ воспіва́ти вам такова́я:","Ра́дуйся, Євдокі́є, ча́шу страда́ній Христо́вих до конця́ іспившая;","Ра́дуйся, юро́дством глубину́ му́дрости от челові́к сокрившая.","Ра́дуйся, я́ко го́рлиця о єди́ном Женихе взивающая;","Ра́дуйся, моли́твою своє́ю жизнь на́шу огражда́ющая.","Ра́дуйтеся, му́ченици, по́двигам блаже́нния Євдокі́ї подража́ющії;","Ра́дуйтеся, си́лу Креста́ Госпо́дня, я́ко тверди́ню необори́мую прославля́ющії.","Ра́дуйтеся, пропові́дници Сві́та Христо́ва:","Ра́дуйся, тихії моли́твенниці во времена́ тяжкії.","Ра́дуйтеся, му́ченици, я́ко мудриє ді́ви єле́єм світи́льники наполнившії:","Ра́дуйтеся, я́ко а́гнці непорочниє на закла́ніє ведомиє.","Ра́дуйтеся, зе́млю Ніжегородськую освящающії;","Ра́дуйся, ми́ра конці́ облиста́ющії.","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Кондак 1","ps":["Ізбранниє уго́дниці і стратотерпиці Христо́ви, ми́ра сего́ безу́міє обличившиє і благодатниє да́ри істоча́ющії, восхваля́єм вас любо́вію: ви же імі́ющії на врага́ побі́ду, от бід і напа́стей свободи́те нас, да зове́м вам:","Ра́дуйтеся, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, моли́твенниці к Бо́гу усе́рдния."]},{"h":"Молитва","ps":["О ди́вния подви́жници і засту́пниці на́ша, му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, дре́вніх му́ченик подража́тельници і́стинния, в тісноті́ послуша́нія без разсужде́нія, бді́ніїх многотру́дних і по́сте ізнури́тельнем пожи́вшия! Ни́ні к вам прибіга́єм і, к моще́м ва́шим припа́дающе, мо́лимся: о страстоте́рпиці святи́я, незло́бивия а́гници, своє́ю кро́вію Христа́ ра́ди обагре́нния і жесто́кими преда́телі ві́ри тридне́вно му́чимия і закла́нния! О прозорли́виці, мно́гія ду́ші от поги́белі ві́чния ісхи́тившия і о страда́ніїх пре́жде кончи́ни от Го́спода ізвіще́нния! О цели́тельници і чудотво́риці не то́кмо в землі́ Ніжегоро́дстей, но і по всей землі́ Ру́сстій прославля́ємия! Не оста́віте нас во грісі́х і беззако́ніїх поги́бнути, но помозі́те в покая́нії і́стиннім житіє́ на́ше сконча́ти і досто́йними яви́тися сла́вити Святу́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Ца́рствія ра́ди Небе́снаго мир і вся я́же в ми́рі оста́вили єсте́, тісноту́ соверше́ннаго послуша́нія возлюби́вши, ди́вния подви́жници і Христа́ ра́ди му́ченици в годи́ну лю́тих іспита́ній в землі́ Новгоро́дстей процве́тшия, блаже́нния ма́тері на́ша Євдокі́є, Да́ріє, Да́ріє і Марі́є, пом'яні́те нас у Престо́ла Пресвяти́я Тро́йці."]},{"h":"Кондак, глас 8","ps":["Житіє́м пра́ведним к досто́йному прия́тію му́ченичества себі́ угото́вившия без боя́зні тридне́вная ізбіє́нія і смерть претерпі́ли єсте́ Неві́сти Христо́ви преди́вния блаже́нния Євдокі́є, Да́ріє, Да́ріє і Марі́є, ни́ні мно́гими чудеси́ і ісціле́нії просія́вшия, не оста́віте зе́млю Ру́ськую без покая́нія поги́бнути."]},{"h":"Величання","ps":["Велича́єм вас, / страстоте́рпиці святи́я му́ченици Євдокі́є, Да́ріє, Да́ріє і Марі́є, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]}],"notes":[]},{"u":"Акафіст праведній Софії, княжні Слуцькій","e":"Akathist to the Righteous Sophia, Princess of Slutsk","secs":[{"h":"Кондак 1","ps":["Ізбра́нная о́трасле благочести́ваго і дре́вняго кня́жеськаго ро́да, свята́я пра́ведная ма́ти на́ша Софі́є, похва́льная пі́нія со умиле́нієм воспіва́єм ті, ти же, я́ко іму́щая ве́ліє дерзнове́ніє ко Го́споду, потщи́ся, да ізба́вить от бід і скорбе́й ни, зову́щия:","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгельською любо́вію горя́щи ко Го́споду от младе́нчества твоєго́, Софі́є пра́ведная, а́ще і роди́тельськаго воспита́нія не імі́вшая, во ві́рі і благоче́стії возраста́ла єси́ под покро́вом Ма́тере Бо́жия. Ми же таково́є о тебі́ Бо́жиє смотре́ніє прославля́юще, взива́єм ті:","Ра́дуйся, роди́телей благоро́дних ча́до боголюбе́зноє;","ра́дуйся, не челові́чеським, но Боже́ственним смотре́нієм опека́ємая.","Ра́дуйся, в младе́нстві осироте́вшая, Го́сподом же не оста́вленная;","ра́дуйся, под покро́вом Пресвяти́я Богоро́диці всегда́ храни́мая.","Ра́дуйся, пра́ведная жено́, Прему́дрости соіме́нная;","ра́дуйся, я́ко по і́мені твоє́м і житіє́ твоє́ просла́вися.","Ра́дуйся, Христо́вой му́дрости нас науча́ющая;","ра́дуйся, о́браз і́стинния му́дрости нам показу́ющая.","Ра́дуйся, в за́повідіх Госпо́дніх усе́рдно ходи́вшая;","ра́дуйся, в ско́рбіх вре́менних утіше́ніє благо́є получа́вшая.","Ра́дуйся, Христа́ Бо́га ча́до возлю́бленноє;","ра́дуйся, пла́мень любве́ ко Го́споду в се́рдці своє́м возже́гшая.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дящи, свята́я Софі́є, по кончи́ні роди́телей себі́ оста́вленну, ко оби́телі Супра́льськой устреми́лася єси́ і та́мо ти́хоє приста́нище обрі́тши, не то́кмо усти́, но і се́рдцем вопія́ла єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Богопросвіще́нний дарова́ся тебе́, свята́я пра́ведная Софі́є, і́мже проразуме́ла єси́ душепа́губную тще́тность і тлі́нность земна́го бога́тства. І сія́ ві́дящи, Христа́ взиска́ти вседу́шно потща́лася єси́, ті́мже велича́єм тя і взива́єм тебі́ та́ко:","Ра́дуйся, с кня́жеською дияди́мою віне́ць Христо́в соєдини́вшая;","ра́дуйся, всім се́рдцем к жи́зні ві́чній устремле́нная.","Ра́дуйся, земни́я сла́сти в житії́ своє́м презре́вшая;","ра́дуйся, жи́тельство безконе́чноє на небесі́х предизбра́вшая.","Ра́дуйся, в Ца́рствіє Небе́сноє путе́м у́зьким і терни́стим ше́дшая;","ра́дуйся, чи́стая і непоро́чная голуби́це, ко Го́рнему Ми́ру возлете́вшая.","Ра́дуйся, все упова́ніє своє́ на Бо́га возложи́вшая;","ра́дуйся, любо́вію ко Го́споду при́сно пламені́ющая.","Ра́дуйся, вся кра́сная ми́ра ні во что же вміни́вшая;","ра́дуйся, і́стинную жизнь во Христі́ обрі́тшая.","Ра́дуйся, ум свой го́ре устреми́вшая;","ра́дуйся, се́рдце твоє́ жили́ще Ду́ха Свята́го соді́лавшая.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственния благода́ті і до́брим проізволе́нієм хотя́щи отврати́ти сму́ту і братоуби́йство от землі́ своєя́, свята́я Софі́є, по́двиг служе́нія і́стині в бра́ці с іносла́вним му́жем прия́ла єси́, сего́ ра́ди благода́рно о тебі́ поє́м Го́сподеві: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи в се́рдці смире́ніє ве́ліє, в свя́тости і че́сти вінча́лася єси́ с му́жем свої́м в правосла́внім хра́мі гра́да Бре́ста, пра́ведная Софіє́. Сего́ ра́ди с любо́вію вопіє́м ті:","Ра́дуйся, ра́ди ми́ра крестоноше́ніє во бра́чном житії́ приє́мшая;","ра́дуйся, блаже́нная миротво́рице, ча́до Бо́жиє наре́кшаяся.","Ра́дуйся, в супру́жестві благоче́стно пожи́вшая;","ра́дуйся, дома́шнюю це́рков свою́ со стра́хом Бо́жиїм созида́вшая.","Ра́дуйся, зако́на Христо́ва ре́вностная ісполни́тельнице;","ра́дуйся, ни́ву се́рдця своєго́ от те́рній душевре́дних очи́стившая.","Ра́дуйся, ду́шу слеза́ми покая́нія при́сно ороша́вшая;","ра́дуйся, моли́твенним по́двигом Бо́гу угоди́вшая.","Ра́дуйся, землі́ на́шея духо́вноє сокро́вище;","ра́дуйся, Це́ркве Правосла́вния многоці́нноє украше́ніє.","Ра́дуйся, десни́цею Бо́жиєю превознесе́нная;","ра́дуйся, я́ко во смире́нії і кро́тости пом'яну́ тя Госпо́дь.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рю ви́дящи, воздвиза́ємую на ві́ру Правосла́вную, со дерзнове́нієм запові́дала єси́ сохрани́ти ю неврежде́нну во владе́ніїх кня́жества Слу́цькаго, да ча́да твоя́ і весь наро́д, пра́ведная ма́ти на́ша Софі́є, правосла́вно возглаго́лють Христу́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє правосла́внії о вели́цім благоче́стії твоє́м, пресла́вная Софі́є, я́ко Бо́жиїм хра́мом і оби́телем ще́дро благотвори́ла єси́, і та́ко те́плоє благодаре́ніє Го́сподеві возноша́ху, тебі́ же ра́достноє хвале́ніє приноша́ху, вопію́ще си́це:","Ра́дуйся, хра́мов правосла́вних ще́драя покрови́тельнице;","ра́дуйся, ри́зи свяще́нничеськия істка́вшая і зла́том пребога́то украси́вшая.","Ра́дуйся, за́повіді Христо́ви пра́ведно іспо́лнившая;","ра́дуйся, благолі́піє церко́вноє преі́скренні возлюби́вшая.","Ра́дуйся, земно́є бога́тство ні во что же вміни́вшая;","ра́дуйся, всемогу́щую си́лу благода́ті Бо́жия позна́вшая.","Ра́дуйся, градо́в Слу́цька і Ми́нська ізря́дноє украше́ніє;","ра́дуйся, землі́ на́шея цві́те благоуха́нний.","Ра́дуйся, я́ко тобо́ю і́м'я Бо́жиє просла́вися;","ра́дуйся, благода́ті Христо́ви пресла́вноє вмісти́лище.","Ра́дуйся, ві́ри і́стинния побо́рнице;","ра́дуйся, я́ко тобо́ю благ ві́чних сподобля́ємся.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лася єси́, свята́я княги́не Софі́є, во дні пра́зднеств престо́льних а́ки пало́мниця богомо́льная посіща́ющи хра́ми Бо́жия землі́ Слу́цькия і та́мо в моли́тві взива́ющи ко Го́споду: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дящи, свята́я Софі́є, я́ко чистота́ ві́ри Правосла́вния от разли́чних ко́зней і напа́стей попира́ється, устро́їла єси́ во гра́ді Слу́цке бра́тство в честь Преображе́нія Госпо́дня, да всі тісни́мії і гони́мії тве́рдаго ра́ди стоя́нія во ві́рі Правосла́вній по́мощ і защище́ніє та́мо обріта́ють. Ті́мже вопіє́м ті:","Ра́дуйся, ра́ди утвержде́нія ві́ри Правосла́вния по́двиги духо́вния под'є́мшая;","ра́дуйся, в зе́млях свої́х Правосла́віє на ві́ки сохрани́вшая.","Ра́дуйся, да́же до забве́нія себі́ Христо́ві ві́рная;","ра́дуйся, ві́ри на́шея іспове́днице дерзнове́нная.","Ра́дуйся, о́браз тве́рдаго стоя́нія за ві́ру Христо́ву нам показа́вшая;","ра́дуйся, я́ко за сіє́ угото́вася ті сокро́вище благ ві́чних.","Ра́дуйся, мно́гія ско́рби за ві́ру Правосла́вную приі́мшая;","ра́дуйся, вінце́м іспові́дничества от Го́спода украше́нная.","Ра́дуйся, пе́рвая от землі́ Слу́цькия к ли́ку святи́х причте́нная;","ра́дуйся, ско́рая помо́щнице всім, с моли́твой притека́ющим к тебі́.","Ра́дуйся, му́дрими твої́ми глаго́ли ві́ру Правосла́вную утвержда́ющая;","ра́дуйся, во і́стиннім благоче́стії всіх наставля́ющая.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропові́дниця ве́лія показа́лася єси́, сла́вная Софі́є, труда́ми і болі́зньми твої́ми ві́ру Правосла́вную во гра́ді Слуцке утвержда́ющи, зе́млі же і ве́сі, близ лежа́щия, сле́зними моли́твами ороша́ющи і облагоуха́ющи. Ми же, па́м'ять твою́ почита́юще, благода́рні взива́єм ко Го́споду: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ па́че со́лнця доброді́тель твоя́ во гра́ді Слу́цке, ма́ти на́ша Софі́є, я́ко всім в ну́ждах і печа́ліх прибега́ющим к тебі́ засту́пниця яви́лася єси́. Прийми́ і нас, недосто́йних, с любо́вію вопію́щих ті си́це:","Ра́дуйся, всім правосла́вним крі́пкоє прибі́жище;","ра́дуйся, си́льних ми́ра сего́ превозмо́гшая.","Ра́дуйся, от всіх враг ви́димих і неви́димих ізря́дная засту́пнице;","ра́дуйся, в разріше́нії мирськи́х нестроє́ній ско́рая помо́щнице.","Ра́дуйся, дре́вняго гра́да Слу́цька похвало́;","ра́дуйся, сла́внаго гра́да Ми́нська утвержде́ніє.","Ра́дуйся, Правосла́вія му́жественная ревни́тельнице;","ра́дуйся, гони́телей ві́ри на́шея неустраши́мая обличи́тельнице.","Ра́дуйся, о́браз любве́ і кро́тости яви́вшая;","ра́дуйся, друг дру́га тяготи́ носи́ти нас науча́ющая.","Ра́дуйся, на путі́ спасе́нія на́ше утвержде́ніє;","ра́дуйся, в Ца́рствіє Бо́жиє благонаде́жноє приведе́ніє.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хотя́й Госпо́дь во смире́нії і терпі́нії укріпи́ти тя, пра́ведная Софі́є, мно́гія ско́рби і смерть во младе́нстві чад твої́х попусти́, да просвіти́шися, я́ко зла́то в горни́лі, і поє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ла єси́ доброді́тель, свята́я Софі́є, воздви́гши храм в честь Пресвяти́я Богоро́диці, Єя́же Ма́тернему попече́нію і уме́ршая ча́да своя́ вві́рила єси́, ті́мже тя ублажа́єм та́ко:","Ра́дуйся, не от челові́к, но от Бо́га утіше́ніє в ско́рбіх получи́вшая;","ра́дуйся, Человіколю́бцю Бо́гу всю себе́ преда́вшая.","Ра́дуйся, лише́нія земна́я благоче́стно поне́сшая;","ра́дуйся, кончи́ну чад свої́х я́ко во́лю Бо́жию приє́мшая.","Ра́дуйся, до́брими твої́ми ді́ли просла́вленная;","ра́дуйся, пра́вим ізволе́нієм се́рдця і ума́ в жили́ще Боже́ственния благода́ті предугото́вленная.","Ра́дуйся, терпі́ніє крі́пкоє і неуста́нноє нам подаю́щая;","ра́дуйся, в ско́рбіх су́щих луча́ми наде́жди осіява́ющая.","Ра́дуйся, на Го́спода упова́ніє неізмі́нно возложи́вшая;","ра́дуйся, віне́ць блага́го воздая́нія от Христа́ приі́мшая.","Ра́дуйся, крі́посте і утіше́ніє в біда́х і ну́ждах на́ших;","ра́дуйся, ди́вная ма́ти, благи́я па́м'яті досто́йная.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є соверши́вши, свята́я пра́ведная Софі́є, пло́тію преста́вилася єси́ от нас, ду́хом же с на́ми всегда́ пребива́єши, да і ми с тобо́ю єди́німи усти́ і єди́нім се́рдцем уми́льно воспоє́м Го́сподеві: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі лю́діє правосла́внії воспіва́ють тя по достоя́нію, достохва́льная Софі́є, Це́рков же Христо́ва сві́тло пра́зднуєть па́м'ять твою́ і піснь хвале́бную прино́сить ті си́це:","Ра́дуйся, ві́рность Христу́ до конця́ соблю́дшая;","ра́дуйся, Го́сподем не́ба і землі́ по преставле́нії ми́лостивно прия́тая.","Ра́дуйся, милосе́рдіє Христо́во на небесі́ обрі́тшая;","ра́дуйся, блаже́нства ві́чнаго дости́гшая.","Ра́дуйся, от злих волко́в ко Христу́, до́брому па́стирю. Прибі́гшая;","ра́дуйся, во двор слове́сних ове́ць Єго́ вше́дшая.","Ра́дуйся, в небе́сних оби́теліх водворе́нная;","ра́дуйся, вінце́м сла́ви от Бо́га увінча́нная.","Ра́дуйся, у Престо́ла Царя́ царе́й предстоя́щая;","ра́дуйся, со А́нгели і всі́ми святи́ми за ни моля́щаяся.","Ра́дуйся, у Престо́ла Святи́я Тро́йці на́ша предста́тельнице;","ра́дуйся, земни́х і небе́сних благ пред Го́сподем нам усе́рдная хода́тайце.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 9","ps":["Во всіх конці́х землі́ на́шея сла́виться і́м'я твоє́, богому́драя Софі́є, я́ко спаса́єши вся ни моли́твами твої́ми от смертоно́сния я́зви, тлітво́рних вітр і о́гненнаго запале́нія, предстоя́щи ни́ні Престо́лу Всеви́шняго Бо́га с ли́ки А́нгелов і святи́х, воспіва́ющих Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йствующий язи́к не мо́жеть ізрещи́ вели́чіє благодія́ній твої́х, свята́я Софі́є, мно́жицею явле́нних благочести́вим супру́гом, непра́здним жена́м і новорожде́нним младе́нцем. Ті́мже всі со благодаре́нієм благоче́стно пою́ть ті:","Ра́дуйся, всіх скорб'я́щих нело́жноє утіше́ніє;","ра́дуйся, непреста́нноє на́ше ра́дованіє.","Ра́дуйся, му́дрих жен добро́то і похвале́ніє;","ра́дуйся, цілому́дренних дів красото́ і удобре́ніє.","Ра́дуйся, те́плая о нас пред Го́сподем моли́твеннице;","ра́дуйся, ізря́дная землі́ на́шея покрови́тельнице.","Ра́дуйся, сіте́й вра́жиїх сокруше́ніє;","ра́дуйся, правосла́вним лю́дем ві́рноє поможе́ніє.","Ра́дуйся, душа́м і тілесе́м на́шим вся, я́же к по́льзі подава́ющая;","ра́дуйся, на вся́коє ді́ло благо́є прему́дро нас наставля́ющая.","Ра́дуйся, во вся́ких злоключе́ніїх і біда́х нам ско́ро помога́ющая;","ра́дуйся, моли́твенно тя призива́ющих от внеза́пния сме́рті ізбавля́ющая.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасені́я душе́внаго і тіле́снаго жела́ющим і о сих усе́рдно подвиза́ющимся помо́щниця блага́я, пра́ведная Софі́є, яви́лася єси́. Ти бо єси́ засту́пниця тружда́ющихся, обремене́нних, в неду́зіх і обстоя́ніїх су́щих, да всі благода́рственно взива́ють просла́вльшему тя Царю́ сла́ви Христу́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ несокруши́мая і огражде́ніє крі́пкоє явля́ються нам моли́тви твоя́, уго́днице Бо́жия, пра́ведная Софі́є, нетлі́нния же і многоціле́бния мо́щі твоя́ ісціле́нія і утіше́нія нам неоску́дно істоча́ють. Ми же благода́рно велича́єм тя:","Ра́дуйся, жизнь земну́ю благоче́стно сконча́вшая;","ра́дуйся, віне́ць Ца́рствія Небе́снаго получи́вшая.","Ра́дуйся, в ра́дості небе́сній ни́ні пребива́ющая;","ра́дуйся, сні́ди ра́йськия при́сно наслажда́ющаяся.","Ра́дуйся, со свіще́ю сві́тлою діл благи́х в черто́г Христо́во возше́дшая;","ра́дуйся, нетлі́нієм і чудеси́ по кончи́ні просла́вленная.","Ра́дуйся, явле́нієм чудото́чних моще́й твої́х Це́рков Христо́ву возвесели́вшая;","ра́дуйся, я́ко тім с ві́рою і любо́вію поклоня́ємся.","Ра́дуйся, притека́ющим к ра́ці святи́х моще́й твої́х цільби́ подаю́щая;","ра́дуйся, почита́ющим тя благослове́ніє і ми́лости Бо́жия неоску́дно істоча́ющая.","Ра́дуйся, лико́в А́нгельських ві́рная соприча́стнице;","ра́дуйся, оби́телей небе́сних сла́вная жи́тельнице.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше хвале́бноє, а́ще і от усе́рдія приноси́моє, не дово́льно єсть ко із'явле́нію серде́чнаго благодаре́нія за вся блага́я, я́же твори́ши нам да́же до дне і часа́ сего́, всечестна́я Софі́є. Ми же в напа́стіх і ско́рбіх к тебі́ прибіга́єм, і на твоє́ предста́тельство упова́юще, немо́лчно ко Го́споду взива́єм: Аллилу́я."]},{"h":"Ікос 11","ps":["Свіща́ многосві́тлая яви́лася єси́, преблаже́нная Софі́є, всім пребива́ющим во мра́ці ві́ка сего́, ті́мже і нас, омраче́нних і уни́лих, просвіти́, во є́же із глубини́ серде́чния зва́ти ті:","Ра́дуйся, ве́ліє дерзнове́ніє ко Го́споду обрі́тшая;","ра́дуйся, Спа́са на́шего умилостиви́тельнице пресла́вная.","Ра́дуйся, мрак душ на́ших благода́тно я́ко світи́льник озаря́ющая;","ра́дуйся, любо́в і ві́ру к тебі́ іму́щих от вся́ких бід спаса́ющая.","Ра́дуйся, в житії́ своє́м пра́вий путь земна́го тече́нія нам показу́ющая;","ра́дуйся, всіх ко Христу́ Бо́гу путеводя́щая.","Ра́дуйся, житіє́м свої́м Го́сподеві угоди́вшая;","ра́дуйся, сві́том Христо́вим на небесі́ осія́нная.","Ра́дуйся, я́ко ізи́де по всей землі́ на́шей віща́ніє о чудесі́х твої́х;","ра́дуйся, я́ко с ві́рою і благогові́нієм почита́ється па́м'ять твоя́.","Ра́дуйся, Бо́жия снисхожде́нія к не́мощем на́шим всеізря́дная хода́тайце;","ра́дуйся, за ни пред Го́сподем неуси́пная моли́твеннице.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жию, проще́ніє гріхо́в і ісправле́ніє житія́ іспроси́ нам у Го́спода Вседержи́теля, ма́ти Софі́є, да ми́лостив бу́деть к нам, немощни́м, смире́нно пою́щим Єму́, Спа́су на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще многомо́щноє предста́тельство твоє́ к Бо́гу, ма́ти на́ша Софі́є, усе́рдно мо́лим тя: помина́й нас непреста́нно у Престо́ла Сла́ви Царя́ Небе́снаго, ублажа́ющих тя си́це:","Ра́дуйся, в со́нмі святи́х просія́вшая;","ра́дуйся, і́стинная уго́днице Бо́жия.","Ра́дуйся, по́чести досто́йния восприї́мшая;","ра́дуйся, проше́нієм на́шим вне́млющая.","Ра́дуйся, блаже́нство ра́йськоє со всі́ми святи́ми унасле́дившая;","ра́дуйся, на тве́рди небе́сній звіздо́ присногоря́щая.","Ра́дуйся, украше́ніє Це́ркве, на небесі́ торжеству́ющия;","ра́дуйся, заступле́ніє Це́ркве, на землі́ во́їнствующия.","Ра́дуйся, ві́ри на́шея преди́вная побо́рнице;","ра́дуйся, чуде́с Христо́вих сокро́вище.","Ра́дуйся, от на́рода на́шего правосла́внаго велича́ємая;","ра́дуйся, пі́сньми хвале́бними прославля́ємая.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 13","ps":["О, свята́я пра́ведная ма́ти на́ша Софі́є! Усли́ши ни́нішнєє усе́рдноє моле́ніє на́ше і іспроси́ нам у Го́спода і Спаси́теля на́шего ізбавле́ніє от бід і скорбе́й, от враг ви́димих і невиди́мих, от поги́белі ві́чния, грі́шником угото́ванния, да милосе́рдієм Христа́ Бо́га на́шего спаса́ємі і твої́м предста́тельством поспешеству́ємі, благоче́стно на землі́ поживе́м, і сподо́бимся вни́ти во Ца́рствіє Єго́ Небе́сноє, іді́же благода́рственно со всі́ми святи́ми воспоє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельською любо́вію горя́щи ко Го́споду от младе́нчества твоєго́, Софі́є пра́ведная, а́ще і роди́тельськаго воспита́нія не імі́вшая, во ві́рі і благоче́стії возраста́ла єси́ под покро́вом Ма́тере Бо́жия. Ми же таково́є о тебі́ Бо́жиє смотре́ніє прославля́юще, взива́єм ті:","Ра́дуйся, роди́телей благоро́дних ча́до боголюбе́зноє;","ра́дуйся, не челові́чеським, но Боже́ственним смотре́нієм опека́ємая.","Ра́дуйся, в младе́нстві осироте́вшая, Го́сподом же не оста́вленная;","ра́дуйся, под покро́вом Пресвяти́я Богоро́диці всегда́ храни́мая.","Ра́дуйся, пра́ведная жено́, Прему́дрости соіме́нная;","ра́дуйся, я́ко по і́мені твоє́м і житіє́ твоє́ просла́вися.","Ра́дуйся, Христо́вой му́дрости нас науча́ющая;","ра́дуйся, о́браз і́стинния му́дрости нам показу́ющая.","Ра́дуйся, в за́повідіх Госпо́дніх усе́рдно ходи́вшая;","ра́дуйся, в ско́рбіх вре́менних утіше́ніє благо́є получа́вшая.","Ра́дуйся, Христа́ Бо́га ча́до возлю́бленноє;","ра́дуйся, пла́мень любве́ ко Го́споду в се́рдці своє́м возже́гшая.","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нная о́трасле благочести́ваго і дре́вняго кня́жеськаго ро́да, свята́я пра́ведная ма́ти на́ша Софі́є, похва́льная пі́нія со умиле́нієм воспіва́єм ті, ти же, я́ко іму́щая ве́ліє дерзнове́ніє ко Го́споду, потщи́ся, да ізба́вить от бід і скорбе́й ни, зову́щия:","Ра́дуйся, пра́ведная Софі́є, свята́я моли́твеннице о душа́х на́ших."]},{"h":"Молитва","ps":["О, свята́я пра́ведная ма́ти на́ша, блаже́нная княги́не Софі́є, прийми́ ми́лостивно приноше́ніє ві́ри, наде́жди і любве́ на́шея і вознеси́ є ко Го́споду, і я́коже в земні́м житії́ твоє́м била́ єси́ помо́щниця і засту́пниця всім Правосла́вним христия́ном землі́ твоєя́, та́ко і ни́ні укріпи́ нас тве́рдо і непоколеби́мо до сме́рти стоя́ти за ві́ру Правосла́вную, согрі́й сердця́ на́ша любо́вію ко Го́споду і Пречи́стій Єго́ Ма́тері. Умоли́ Христа́ Бо́га на́шего, да сохрани́ть Це́рков Свою́ Святу́ю от раско́лов і єресе́й, да утверди́ть в ней дух пра́вия ві́ри і благоче́стія, дух ві́дінія і любве́, дух ми́ра і ра́дости ві́чния, да вся ча́да єя́ ду́хом і і́стиною покланя́ються Єму́, да укріпи́ть ві́рних в благоче́стії і свя́тості жи́зні, да обрати́ть отпа́дших от Правосла́вния Це́ркве во святи́я ні́дра Єя́. О, свята́я ма́ти, гра́да Слу́цька похвало́ і ра́досте, умоли́ Го́спода, да ізба́вить град твой і всю страну́ на́шу от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних, междоусо́бния бра́ні і от смертоно́сния я́зви, да низпо́слеть прави́телем на́шим усе́рдіє, му́дрость і ві́рность, да управля́ють і су́дять по во́лі Єго́, да храня́ть установле́ния Святи́я Це́ркве. Іспроси́ всім с ві́рою моля́щимся тебі́ [іли́: притека́ющим к ра́ці святи́х моще́й твої́х] ми́рноє житіє́, тишину́, просвіще́ніє умо́в і серде́ць, соблюди́ їх от ко́зней вра́жиїх, от собла́знов ми́ра, во злі лежа́щаго, і от вся́кия ско́рби і ну́жди, обрати́ нас к покая́нію і ісправле́нію, да́руй заблу́дшим і́стини позна́ніє, неду́гующим ісціле́ніє. Сохрани́ нас благода́тними твої́ми моли́твами от всіх враго́во ви́димих і неви́димих і ізба́ви от вся́каго зла, да просла́вим во вся дні жи́зні на́шея Отця́ і Си́на і Свята́го Ду́ха і твоє́ заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Блаже́нная ма́ти Софі́є, / нетлі́нієм моще́й і чуде́с сія́нієм почти́ тя Бог; / помина́юще твоє́ пра́ведноє житіє́, / тя мо́лим іспроси́ти // тілесе́м на́шим здра́віє і душа́м спасе́ніє."]},{"h":"Кондак, глас 4","ps":["Прийді́те, вся ру́ськия жени́, / святу́ю Софі́ю восхва́лим, / уподо́бившуюся му́дрим ді́вам, / єле́й благода́ті Ду́ха Свята́го стяжа́вшим; / ті́мже умудри́ ю Госпо́дь / подвиза́тися во утвержде́ніє святи́я правосла́вния ві́ри / і соблюда́ти Це́рков Єго́ / нези́блему от єресе́й і раско́лов, / сего́ ра́ди благода́рні воспої́м єй: / ра́дуйся, гра́да Слу́цька і всея́ землі́ на́шея // ра́досте і утвержде́ніє."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я пра́ведная княги́не Софі́є, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святим мученикам Гурію, Самону і Авіву","e":"Akathist to the Holy Martyrs Gurias, Samonas and Abibus","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці Христо́ви і святи́я ві́ри іспові́дниці, Гу́ріє, Само́не і Ави́ве добронра́внії, па́м'ять ва́шу чту́ще пі́сньми похва́льними, воспіва́єм я́ко христия́н засту́пников, стра́ждущих покрови́телей. Ви же, іму́ще дерзнове́ніє ко Го́споду, от вся́ких бід і напа́стей свободи́те нас, ві́рою і любо́вію зову́щих:","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Ікос 1","ps":["А́нгели во пло́ті Тро́йці Святі́й равночи́сленнії, любо́вію к Бо́гу горя́ще і́доли попра́сте, ві́ру Христо́ву укріпи́сте, Тро́йцю Святу́ю просла́висте, ті́мже у́бо, похваля́юще по́двиги ва́ша, глаго́лем вам си́це:","Ра́дуйтеся, світи́льники благоче́стія;","ра́дуйтеся, обличи́телі нече́стія.","Ра́дуйтеся, утвержде́нія ві́ри Христо́вой;","ра́дуйтеся, столпи́ Це́ркві Бо́жия.","Ра́дуйтеся, ві́рних наде́ждо і заступле́ніє;","ра́дуйтеся, неві́рних страх і посрамле́ніє.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 2","ps":["Ви́дя нече́стіє люде́й гра́да Єде́са, святі́ї Гу́рій і Само́н в пусти́ню удали́шася, бі́гая кня́зя ми́ра сего́ і собла́знов і усе́рдно служа́ще Бо́гу, день і ноч воспіва́ху: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум прему́др імі́я, святі́ї му́ченици, ви́ну труди́шася во сла́ву Бо́жию, язи́чеськоє нече́стіє облича́я, і́щущия і́стини на путь пра́вий наставля́я і мно́зі неві́рния к Бо́гу І́стинному привлеко́ша, сего́ ра́ди глаго́лем вам си́це:","Ра́дуйтеся, насади́телі і́стиннаго Богопочита́нія;","ра́дуйтеся, іскорени́тели де́монськаго служе́нія.","Ра́дуйтеся, тьми нече́стія обличи́телі;","ра́дуйтеся, і́дольськия пре́лести низложи́тели.","Ра́дуйтеся, іспові́дниці Христо́ви ізря́днії;","ра́дуйтеся, світи́ла ві́ри правосла́вній.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 3","ps":["Си́лою сви́ше осене́ннії святі́ї му́ченици, гони́телей свято́й ві́ри не устраши́шася, велі́нія нечести́ваго Антонія́на небрего́ша і ві́ру Христо́ву велегла́сно просла́виша, ті́мже і в темни́цю вве́ржені поя́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ві́ру во Христа́ адама́нта тверді́йшую і си́лою тоя́ вооружи́вшіїся, му́жественно претерпі́ли єсте́, святі́ї му́ченици, темни́чниє у́зи і са́мую смерть, сего́ ра́ди похваля́юще таково́є му́жество, ублажа́єм вас си́це:","Ра́дуйтеся, і́стинния ві́ри іспові́дниці;","ра́дуйтеся, Ца́рствія Бо́жия наслі́дници.","Ра́дуйтеся, му́чеников похвало́;","ра́дуйтеся, страстоте́рпцев сла́во.","Ра́дуйтеся, Святи́я Це́ркви утвержде́ніє;","ра́дуйтеся, всего́ ро́да христия́нськаго украше́ніє.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 4","ps":["Бу́рею помишле́ній сумни́тельних одержи́мий, нечести́вий цар Лики́ній воздви́же жесто́коє гоне́ніє на христия́ни, ти же, страстоте́рпче Ави́ве, того́ не убоя́ся, с тве́рдою ві́рою взива́л єси́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав цар Лики́ній твої́ по́двиги, досточу́дний Ави́ве, і твоє́ тве́рдоє ві́ри іспові́даніє, раз'яри́ся на тя зло́бою, повелі́ преда́ти тя сме́рті лю́тій я́ко проти́вника царе́ва, ти же, уві́дів о сем, доброво́льно поте́кл єси́ на муче́ніє, і с ра́достію претерпі́л єси́ о́гненноє сожже́ніє, сего́ ра́ди, див'я́щеся вели́кому му́жеству твоєму́, велича́єм тя си́це:","Ра́дуйся, побо́рниче ві́ри во Христа́ неустраши́мий;","ра́дуйся, во́їне Христо́в непобіди́мий.","Ра́дуйся, пове́шенний на дре́ві за Распросте́ршаго ру́ці Свої́ на дре́ві кре́стнім;","ра́дуйся, строга́нний когтьми́ желі́зними.","Ра́дуйся, утіше́ніє подава́яй скорб'я́щим;","ра́дуйся, ско́рий помо́щниче всім за і́стину терп'я́щим.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 5","ps":["Боготе́чним зві́здам на тве́рди небе́сній подо́бнії би́ли єсте́, святі́ї му́ченици, луча́ми житія́ своєго́ тьму язи́чеськаго нече́стія просвіща́ющії і мно́гих на путь і́стини наставля́ющії. Ті́мже благогові́йно чту́ще па́м'ять ва́шу, благода́рно поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша лю́діє гра́да Єде́са мно́гіє чудеса́, бива́ємия от ра́ки святи́х му́чеников Гу́рія, Само́на і Ави́ва, зіло́ ра́довахуся і Го́спода всім се́рдцем прославля́ху, ми же чту́ще святу́ю па́м'ять ва́шу, святі́ї му́ченици, уми́льно взива́єм:","Ра́дуйтеся, непра́ведно гони́мих засту́пниці;","ра́дуйтеся, ві́рних рабо́в Христо́вих дру́зі.","Ра́дуйтеся, су́щих во у́зах і темни́цях храни́теліє;","ра́дуйтеся, гони́телей і оби́дящих вразуми́тели.","Ра́дуйтеся, пла́чущих уті́шители;","ра́дуйтеся, от на́глия і лю́тия сме́рті ізба́вители.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 6","ps":["С висоти́ му́дрії благода́ть приє́мше, за су́щих во іскуше́нії предстої́те, всехва́льнії, ті́мже отрокови́цю, святі́ї, от сме́рти го́ркия ізба́висте. Ви бо воі́стину єсте́ гра́ду Єде́су сла́ва і ми́ру ра́дость, сего́ ра́ди воспіва́єм ко Го́споду: Аллилу́я."]},{"h":"Ікос 6","ps":["Вра́жия рабо́ти ізба́ви нас, Ісу́се Жизнода́вче, Твої́х страда́лець мольба́ми умоля́єм, я́ко да не порабоще́нну стяжа́в от страсте́й ду́шу і ті́ло, восхваля́єм тіх скорі́йшую по́мощ, я́коже во гро́бі затворе́нную му́жем і сію́ ско́ро предвари́вше от сме́рти ізба́виша, ті́мже взива́єм вам си́це:","Ра́дуйтеся, неви́нную жену́ от лю́тия сме́рті спа́сшії;","ра́дуйтеся, ди́вним спасе́нієм єя́ зве́рства мучи́теля побіди́вшії.","Ра́дуйтеся, зла́го му́жа жесто́коє дія́ніє обличи́вшії;","ра́дуйтеся, і того́ ві́ровати в си́лу Бо́га христия́нськаго научи́вшії.","Ра́дуйтеся, пода́телі ми́лости тоя́ тре́бующим;","ра́дуйтеся, стра́жи неуси́пнії почита́ющих па́м'ять ва́шу.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 7","ps":["Хотя́й Человіколю́бець Госпо́дь яви́ти ми́лость Свою́ лю́дям Свої́м, сохрани́ тілеса́ ва́ші нетлі́нни, чудеса́ точа́щії, от них же всі ві́рнії то́ки ісціле́ній получа́ють, зову́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вих засту́пников і ди́вних чудотво́рцев ві́дуще, лю́діє із гра́да Єде́са свято́й храм в па́м'ять ва́шу созда́ша, в нем же і мо́щі ва́ша положи́ша, да всі стра́ждущії по́мощ в них почерпа́ють, ми же та́кожде тве́рду наде́жду на вас іму́ще, взива́єм вам си́це:","Ра́дуйтеся, душе́вних і тіле́сних неду́гов на́ших ціли́телі;","ра́дуйтеся, бісо́в о і́мені Госпо́дні ізгони́тели.","Ра́дуйтеся, Єва́нгельськия і́стини благода́ті благовести́телі;","ра́дуйтеся, Боже́ственния благода́ті носи́тели.","Ра́дуйтеся, ско́рбі мно́гі за і́м'я Госпо́днє прия́вшії;","ра́дуйтеся, ди́вно во святи́х Єго́ просія́вшії.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 8","ps":["Стра́нно і стра́шно неві́рним сли́шати, какови́ ди́вниє ді́ла от святи́х моще́й ва́ших соверша́ються: неду́зі врачу́ються, стра́сті ісціля́ються, ми же, тве́рду наде́жду на вас іму́ще, Бо́гу о вас та́ко благоді́ющему с ві́рою взива́єм: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі́ми доброді́тельми іспо́лненнії, за ни́хже і сла́вою Бо́жиєю почте́ннії, внима́йте, святі́ї му́ченици, моли́твам ві́рних, чту́щих святу́ю па́м'ять ва́шу, от ни́хже сли́шіте сицева́я:","Ра́дуйтеся, ни́щії ду́хом, я́ко ва́ше єсть Ца́рствіє Небе́сноє;","ра́дуйтеся, пла́чущії, я́ко уте́шистеся.","Ра́дуйтеся, кро́тції, я́ко наслі́довасте зе́млю;","ра́дуйтеся, алка́вшії і жа́ждавшії пра́вди, я́ко наси́тишася.","Ра́дуйтеся, ми́лостивії, я́ко стяжа́ли єсте́ поми́лованіє;","ра́дуйтеся, чи́стії се́рдцем, я́ко уже́ Бо́га узре́сте.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 9","ps":["Вся́кия напа́сти, находя́щия на град Єде́с, разоря́ли єсте́, святі́ї му́ченици, ті́мже і ни́ні не оста́віте нас смире́нних і грі́шних, но вся лю́ди страни́ на́шія в правосла́вії і єдиноми́слії утверді́те, да всі єди́ними усти́ і єди́ним се́рдцем воскли́кнем просла́вившему вас Го́споду: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії, я́ко ри́би безгла́снії, зрим о вас, святі́ї му́ченици: недоумі́ють бо, ка́ко в пусти́ні ду́хом вита́ли єсте́ і посреді́ челові́к неуси́пними по́двиги подвиза́стеся. Ми же ра́дующися, я́ко такови́ і́мами учи́тели і моли́твенники, прославля́єм вас, глаго́люще:","Ра́дуйтеся, кимва́ли Сло́ва Бо́жия;","ра́дуйтеся, те́плії о нас пред Бо́гом хода́таї.","Ра́дуйтеся, іуде́єв і е́ллинов просвіти́телі;","ра́дуйтеся, тридне́внаго Божества́ благовести́телі.","Ра́дуйтеся, кро́тости і воздержа́нія учи́тели;","ра́дуйтеся, лжі і татьби́ обличи́теліє.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ лю́ди гра́да Єде́са от ми́сленнаго во́лка, тве́рдо увеща́ли єсте́ тіх стоя́ти во і́стинній ві́рі ніже́ ко́зней вра́жиїх устраша́тися, но і в ско́рбіх і напа́стіх за вся благодари́ти Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда і наде́жноє прибі́жище єсте́, святі́ї му́ченици, всім к вам прибега́ющим і ско́рия по́мощі тре́бующим, сего́ ра́ди во умиле́нії сердця́ на́шего взива́єм:","Ра́дуйтеся, всіх скорб'я́щих ра́дованіє;","ра́дуйтеся, всіх угнете́нних і порабоще́нних прибі́жище і освобожде́ніє.","Ра́дуйтеся, вдов і сиро́т заступле́ніє;","ра́дуйтеся, от єресе́й і раско́лов огражде́ніє.","Ра́дуйтеся, я́ко всі нечести́вії житію́ ва́шему удивля́ються;","ра́дуйтеся, я́ко всі благочести́вії о і́мені ва́шем веселя́ться.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє принося́ще ко Го́споду і о нас, те́плії засту́пници на́ші, мо́лим вас при́сно не отступа́ти от нас, гріх на́ших ра́ди, но милосе́рдіє от Го́спода всім іспросі́те, вопію́щим Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную тро́йцю святи́х му́чеников восхваля́юще, ві́рнії, устрані́мся ра́спрей і раздо́ров в жи́зні сей, убіжи́м несогла́сій і разделе́ній в Правосла́вній ві́рі і храня́ще єдине́ніє ду́ха в сою́зі ми́ра, із глубини́ душі́ воскли́кнем та́ко:","Ра́дуйтеся, громогла́сния труби́ Єва́нгельськаго благові́стія;","ра́дуйтеся, сладкозву́чния гу́сли про́повіді спасе́нія.","Ра́дуйтеся, кре́пції пра́вди рачи́теліє;","ра́дуйтеся, непоколеби́мії непра́вди істреби́телі.","Ра́дуйтеся, благочести́вим семе́йствам ми́ра і бла́га пода́телі;","ра́дуйтеся, жесто́ким і неві́рним супру́гом стро́гіє наказа́телі.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную вам от Бо́га, ві́дуще, па́м'ять ва́шу пра́зднуєм, святи́є му́ченици, с усе́рдним моле́нієм к ва́шему честно́му о́бразу притека́юще, ва́шею тве́рдою по́мощію, я́ко необори́мою стіно́ю огражда́ємся, сего́ ра́ди восхваля́єм вас, страстоте́рпці Христо́ви, і усе́рдно зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ва́ше ди́вноє житіє́ і му́ченичеськую кончи́ну, мо́лим вас, страстоте́рпці Христо́ви Гу́ріє, Само́не і Ави́ве, бу́дете нам во всем благі́є помо́щници, благослові́те нас ми́ром і любо́вію, пода́йте нам тве́рдую ві́ру, чистоту́ жи́зні і страх Бо́жий, да всі душе́вний поко́й іму́ще, в ра́дості восклиця́єм:","Ра́дуйтеся, я́ко імена́ ва́ша і между́ неві́рними прославля́ються.","Ра́дуйтеся, поко́й і отра́до скорб'я́щим;","ра́дуйтеся, страх і удивле́ніє оби́дящим.","Ра́дуйтеся, неви́нную жену́ от лю́тия сме́рті спа́сшії;","ра́дуйтеся, зла́го му́жа єя́ досто́йно покара́вшії.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 13","ps":["О святі́ї страстоте́рпці Христо́ви Гу́ріє, Само́не і Ави́ве, приймі́те сіє́ на́ше хвале́бноє пі́ніє і, усли́шав усе́рдно жела́ніє на́ше, ізба́віте нас те́плим свої́м к Бо́гу предста́тельством, от вся́каго зла, от вражди́ і несогла́сій і вся́ких лю́тих бід і болі́зней, да с любо́вію вас чту́ще, ви́ну зове́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели во пло́ті Тро́йці Святі́й равночи́сленнії, любо́вію к Бо́гу горя́ще і́доли попра́сте, ві́ру Христо́ву укріпи́сте, Тро́йцю Святу́ю просла́висте, ті́мже у́бо, похваля́юще по́двиги ва́ша, глаго́лем вам си́це:","Ра́дуйтеся, світи́льники благоче́стія;","ра́дуйтеся, обличи́телі нече́стія.","Ра́дуйтеся, утвержде́нія ві́ри Христо́вой;","ра́дуйтеся, столпи́ Це́ркві Бо́жия.","Ра́дуйтеся, ві́рних наде́ждо і заступле́ніє;","ра́дуйтеся, неві́рних страх і посрамле́ніє.","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці Христо́ви і святи́я ві́ри іспові́дниці, Гу́ріє, Само́не і Ави́ве добронра́внії, па́м'ять ва́шу чту́ще пі́сньми похва́льними, воспіва́єм я́ко христия́н засту́пников, стра́ждущих покрови́телей. Ви же, іму́ще дерзнове́ніє ко Го́споду, от вся́ких бід і напа́стей свободи́те нас, ві́рою і любо́вію зову́щих:","Ра́дуйтеся, Гу́ріє, Само́не і Ави́ве, страстоте́рпці Христо́ви і оби́димих покрови́теліє."]},{"h":"Молитва","ps":["О святі́ї му́ченици і іспові́дниці Христо́ви Гу́ріє, Само́не і Ави́ве! Те́плії о нас хода́таї і моли́твенниці пред Бо́гом, во умиле́нії серде́ць на́ших, взира́я на пречи́стий ваш о́браз, смире́нно мо́лим вас: усли́шіте нас, грі́шних і недосто́йних рабо́в свої́х, су́щих в біда́х, ско́рбіх і напа́стіх, і призрі́в на́ша тя́жкая і безчи́сленная прегріше́нія, яві́те нам свою́ вели́кую ми́лость, воздви́гніте нас із глубини́ гріхо́вния, просвіті́те наш ум, см'ягчі́те зло́є і окая́нноє се́рдце, прекраті́те за́висть, вражду́ і раздо́ри, в нас живу́щиє. Осіні́те нас ми́ром, любо́вію і стра́хом Бо́жиїм, умолі́те милосе́рднаго Го́спода, да покри́єть мно́жество гріхо́в на́ших Свої́м неізрече́нним милосе́рдієм. Да соблюде́ть Це́рков Свою́ Святу́ю от неві́рія, єресе́й і раско́лов. Да пода́сть страні́ на́шей мир, благоде́нствіє, землі́ плодоро́діє; супру́гом любо́в і согла́сіє; ча́дам послуша́ніє; оби́димим терпі́ніє; оби́дящим страх Бо́жий; скорб'я́щим благоду́шіє; ра́дующимся воздержа́ніє. Всіх же нас да покри́єть Своє́ю всеси́льною десни́цею, і да ізба́вить от гла́да, губи́тельства, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, і напра́сния сме́рті. Да огради́ть нас ополче́нієм святи́х Свої́х а́нгелов, во є́же ізба́витися нам по ісхо́ді на́шем із житія́ сего́ от ко́зней лука́ваго і та́йних возду́шних мита́рств єго́, і неосужде́нними предста́ти Престо́лу Го́спода Сла́ви, іді́же ли́ци святи́х А́нгел со всі́ми святи́ми ви́ну сла́в'ять пресвято́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Чудеса́ святи́х Твої́х му́ченик / сті́ну необори́мую нам дарова́вий, Христе́ Бо́же, / тіх моли́твами сові́ти язи́ков разори́, / Це́рков святу́ю укріпи́, // я́ко Єди́н Благ і Человіколю́бець."]},{"h":"Кондак, глас 2","ps":["С висоти́ му́дрії благода́ть приє́мше, / су́щим во іскуше́ніїх предстої́те, всехва́льнії. / Ті́мже отрокови́цю святі́ї от сме́рти го́ркия ізба́висте: // ви бо воі́стину єсте́ Єде́су сла́ва і ми́ру ра́дость."]},{"h":"Величання","ps":["Велича́єм вас, страстоте́рпці святі́ї Гу́ріє, Само́не і Ави́ве, і чтим честна́я страда́нія ва́ша, я́же за Христа́ претерпі́ли єсте́."]}],"notes":[]},{"u":"Акафіст святому преподобному Амфілохію Почаївському","e":"Akathist to our Venerable Father Amphilochius of Pochaiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нниче Христо́в і оби́телі Поча́євския но́вий чудотво́рче, скорб'я́щих ско́рий уті́шителю і неду́жних благода́тний ціли́телю, преподо́бне о́тче Амфіло́хіє, любо́вію восхваля́юще богоуго́дноє житіє́ твоє́, піснь благодаре́нія о тебі́ Бо́гу прино́сим. Ти же я́ко дерзнове́нний к Нему́ моли́твенник і те́плий о нас хода́тай, іспроси́ всім с ві́рою к тебі́ приходящим, от душе́вних і тіле́сних зол свобожде́ніє, да ви́ну зове́м ті:","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Ікос 1","ps":["Арха́нгелу Рафаї́лу, моли́тви стра́ждущих Бо́гу принося́щему і здра́віє благода́тію Єго́ с небесе́ подаю́щему, уподоб'яся преподо́бне, я́ко врач ізря́дний яви́лся єси́, ісціля́ющий на́ша неду́ги многоразли́чния. Ми же, помина́юще пресла́вноє твоє́ житіє́, та́ко вопіє́м ті:","Ра́дуйся, землі́ Воли́нськия свято́є прозябе́ніє;","ра́дуйся, роди́телей благочести́вих ча́до благослове́нноє.","Ра́дуйся, ізмла́да во ві́рі і́стинній воспита́нний;","ра́дуйся моли́твенноє ді́ланіє і тіле́сноє воздержа́ніє ізді́тська возлюби́вий.","Ра́дуйся, от ю́ности своєя́ во благоче́стії просія́вий;","ра́дуйся, доброді́телі роди́телей свої́х унаслі́дивий.","Ра́дуйся, іску́сному врачеванію, отце́м свої́м, обученний;","ра́дуйся, благоговенію і кро́тости ма́тері своєя́ подража́ти тщавийся.","Ра́дуйся, супроти́в по́хоті пло́ті, хране́нієм ді́вства і чистоти́ подвиза́вийся;","ра́дуйся, на по́хоть оче́с цілому́дрієм вооружи́вийся.","Ра́дуйся, го́рдості жите́йськой смиренному́дрієм противуставий;","ра́дуйся, Христо́ви за́повіді боголю́бія і братолю́бія іспо́лнивий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 2","ps":["Ви́дів на себі́ десни́цю Бо́жию, ви́ну тебі́ покрива́ющую, і скоротечность житія́ сего́ разумі́в, вся пре́лести ми́ра лука́ваго отве́ргл єси́ і на святу́ю го́ру Поча́євськую прише́л єси́, да всего́ себе́ в же́ртву Творцю́ своєму́ в чи́ні і́ночестім принесе́ши, непреста́нно поя́ Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зума соверше́нна взиска́ху в тебі́ правосла́внії лю́діє, ви́дящії богоуго́дноє твоє́ житіє́. Ти же от оби́лія в се́рдці любве́ Христо́ви возимел єси́ о них о́тчеє попече́ніє. С висоти́ же небе́сния дар духо́внаго разсужде́нія восприї́м, сей досто́йно употреби́л єси́ в науче́ніє духо́вно младенствующим, сего́ ра́ди похваля́єм тя, глаго́лющи:","Ра́дуйся, смотре́нія Зижди́телева ісполни́телю;","ра́дуйся, о спасе́нії бли́жніх попечи́телю.","Ра́дуйся, Ду́ха Свята́го стяжа́телю;","ра́дуйся, во тьмі неві́рія блужда́ющих просвіти́телю.","Ра́дуйся, скорб'я́щих і обремене́нних уті́шителю;","ра́дуйся, ре́вностний христия́н окорми́телю.","Ра́дуйся, Це́ркве земни́я воі́телю;","ра́дуйся, полко́в де́монських прогони́телю.","Ра́дуйся, святи́х оте́ць послі́дователю;","ра́дуйся, єретико́в льсти́вих обличи́телю.","Ра́дуйся, покая́нія учи́телю;","ра́дуйся, от ра́бства гріхо́внаго свободи́телю.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укріпля́ємий, на висоту́ безстра́стія му́жественно возше́л єси́, блаже́нне, та́же от Го́спода мно́гія благода́тния да́ри прия́в, спасе́нію бли́жніх і́ми послужи́л єси́, смиренному́дренно воспіва́я Щедродателю Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я врачева́ній дарова́ніє, воі́стину, я́ко но́вий істо́чник благода́ті, на горі́ Поча́євстій яви́лся єси́, о́тче Амфіло́хіє, к тебі́ бо во мно́жестві разли́чними неду́ги стра́ждущії, с ві́рою і упова́нієм усе́рдно притека́ху, і си́лою благода́тних моли́тв твої́х, безме́здно здра́віє приє́мше, в ра́дості благодаре́нія взива́ху:","Ра́дуйся, си́лою Ви́шняго препоя́санний неісці́льния неду́ги врачева́ти;","ра́дуйся, Того́ же вла́стію оболче́нний і ме́ртвия воскреша́ти.","Ра́дуйся, сліпи́я зрячія сотворяющий;","ра́дуйся, глухи́м слух і німи́м язи́к отверза́ющий.","Ра́дуйся, ко́сті сокруше́нния ісправляющий;","ра́дуйся, хребти́ сляче́нния укріпля́ющий.","Ра́дуйся, сухи́я ру́ці і но́зі то́ков жи́зні ісполня́ющий;","ра́дуйся, огне́м опаленная тілеса́ обновляющий.","Ра́дуйся, я́зви і смра́дния стру́пи тіле́сния очища́ющий;","ра́дуйся, у́ди пло́ті растлевшия, і отсеченни би́ти іму́щия, чуде́сне врачу́ющий.","Ра́дуйся, ра́зума лишившимся, моли́твами к Богоро́диці, ум здра́вий подаю́щий;","ра́дуйся, стра́ждущих от дух нечи́стих, і́менем Ісу́совим свобожда́ющий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 4","ps":["Да́ром прозрі́нія, внеза́пу от Го́спода дарова́нним, бу́ря наше́ствія іноплеме́нних тебі́ ізвісти́ся, с сего́ же часа́ іздале́ча зрел єси́ душі́ і судьби́ к тебі́ приходя́щих. І я́ко ре́вности о благоче́стії іспо́лненний, гріхи́ нераска́янних да́ром сим кро́тко облича́л єси́, да прине́сше досто́йний плод покая́нія, чи́стим се́рдцем воззову́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Єва́нгельських слове́с благоразу́мнаго сли́шателя і сих му́драго ісполни́теля, зрим в тебі́ преподо́бне. Ї́хже ра́ди на путь самоотверже́нія, лише́ній і скорбе́й ре́вностно возше́л єси́ і за Христо́м неуклоно ше́ствовал єси́. Ми же, нерадя́щії о таково́м восследованії своєму́ Спаси́телю, во умиле́нії і сокруше́нії серде́ць зове́м ті:","Ра́дуйся, жела́ніє би́ти со Христо́м ви́ну імі́вий;","ра́дуйся, Того́ Єди́наго взиска́ти непреста́нно тщавийся.","Ра́дуйся, мона́шеськаго послуша́нія стро́гий ісполни́телю;","ра́дуйся, на ни́ві Христо́вой ре́вностний ді́лателю.","Ра́дуйся, світоза́рноє світи́ло, руководя́щеє нас ко спасе́нію;","ра́дуйся, гра́де, стоя́щий верху́ гори́, к нему́ же ві́рнії притека́ють.","Ра́дуйся, со́лію благоче́стія, мир от растлі́нія душе́внаго сохраня́яй;","ра́дуйся, мно́гих ре́вности по Бо́зі ісполня́яй.","Ра́дуйся, кро́тость і смире́ніє Христо́во возлюби́вий;","ра́дуйся, небе́сний поко́й єще́ в земні́м житії́ обріти́й.","Ра́дуйся, ріко́ благода́ті Бо́жия;","ра́дуйся, із нея́же і ни́ні ві́рою напоя́ємся.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 5","ps":["Боготечний защи́тник хра́ма Святи́я Живонача́льния Тро́йці в Ла́врі святі́й показа́лся єси́, єго́же от оскверне́нія і запусті́нія защити́в, безбо́жния гони́телі от до́му моли́тви дерзнове́нно отгна́л єси́ і ві́рния лю́ди до кро́ве стоя́ти за ві́ру Христо́ву призва́л єси́, безбоязнено пою́ще Трийпоста́сному Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше в тебі́ хули́телі злочести́вії ре́вностнаго защи́тника оби́телі Поча́євския, і спобо́рника крі́пкаго наро́ду Бо́жию разумі́вше, доса́ди су́ще ді́лателіє безу́мнії, потща́шася соді́лати тя не́мощна, стра́ждуща і безче́стна; ми же піснь хвали́ прино́сим ті глаго́люще:","Ра́дуйся, за безбоязненноє ві́ри іспові́даніє пострада́вий;","ра́дуйся, за Бо́га в Тро́йці Святі́й сла́вимаго, во узи́лищі влеко́мий.","Ра́дуйся, зауше́нія в подража́ніє Го́споду Ісу́су прия́вий;","ра́дуйся, с бесними і бу́їми затворе́нний.","Ра́дуйся, в же́стоких муче́ніях долготерпі́вий;","ра́дуйся, в лю́тих злострада́ніях не ропта́вий.","Ра́дуйся, на мучи́телі твоя́ не озло́бивийся;","ра́дуйся, любве́ боже́ственния преіспо́лненний.","Ра́дуйся, в долговре́менних злоключе́ніях духо́вно бдевий і моли́вийся","ра́дуйся, Богоро́дицю на по́мощ ви́ну призива́вий.","Ра́дуйся, все упова́ніє своє́ на Го́спода возложи́вий;","ра́дуйся, во ві́рі і наде́жде своє́й не посрами́вийся.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 6","ps":["Пропові́дник покая́нія і житія́ благоче́стнаго учи́тель показа́лся єси́, о́тче Амфіло́хіє. Пре́жде бо ісціле́ній тіле́сних, ісціля́л єси́ душі́ к тебі́ приходя́щих, от гріхо́в і беззако́ній. К сему́ же науча́л єси́, я́ко ско́рби і болі́зні постига́ють нас за презрі́ніє житія́ богоуго́днаго, єго́же покая́нієм взиска́ти призива́л єси́, да сих ізба́вльшеся, в ра́дості воспоє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ разсужде́нієм духо́вним, от Го́спода тебі́ дарова́нним, єго́же на душепопече́ніє направля́я, ра́бськаго плі́на рабо́ти страсте́м послу́шающих тя, благода́тно свобожда́л єси́. Ни́ні же достохва́льная словеса́ от нас прийми́:","Ра́дуйся, смире́нія і любве́ мечу́ обоюдоо́стрий, ко́зней вра́жиїх посіче́ніє;","ра́дуйся, Апо́столов подража́телю, ві́ри правосла́вния утвержде́ніє.","Ра́дуйся, му́жественний подви́жниче, обі́тов мона́шеських ревностноє ісполне́ніє;","ра́дуйся, А́нгелов собесі́дниче і а́нгельський о́браз нося́щих наста́вниче.","Ра́дуйся, ві́рний ра́бе Бо́жий, іспові́дников наслі́дниче;","ра́дуйся, о́тче милосе́рдий, преподо́бних соприча́стниче.","Ра́дуйся, свяще́нниче Бо́гом поста́вленний, Же́ртву Безкро́вную за лю́ди непоро́чно приноси́ти;","ра́дуйся, па́стирю до́брий, ду́шу свою́ за слове́сния о́вці Христо́ви гото́вий положи́ти.","Ра́дуйся, врачу́ благода́тний, водо́ю і бра́шном, моли́твою освяще́нними, боля́щия ісцелявий;","ра́дуйся досто́йний пресвитере, си́лою благода́ті Бо́жия ско́ро тім помогавий.","Ра́дуйся, Богодарова́нний істо́чниче, животво́рний і ціли́тельний;","ра́дуйся, любве́ Христо́ви преіспо́лненний, па́дшия возста́вивий і отчаявшіяся ободривий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 7","ps":["Хотя́ в се́рдці своє́м со Христо́м соєдини́тися, непреста́нно і́м'я Єго́ Сладча́йшеє усти́ призива́л єси́ і огне́м благода́ті Бо́жия ду́шу свою́ в досто́йний храм Сему́ предочи́стил єси́. Сего́ ра́ди і нас науча́єши, ум і се́рдце от ми́ра гріхо́внаго отвраща́ти і к Бо́гу устремля́ти, даби́ во ві́чном ра́дованії пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зерца́ло апо́стольськаго угото́ванія і жела́нія разріши́тися і со Христо́м би́ти яви́лся єси́, преподо́бне, єгда́ беззако́ннії і неблагода́рнії на монастирськом кладбище хотя́ху тя, непови́ннаго умертви́ти. Но по́двигом любве́ же́ртвенния, сокелейника твоєго́ Ірина́рха, от неумолимия сме́рті спасе́н бил єси́. Сим о́бразом і ми, в преданости Бо́гу утвержда́єми, глаго́лем ті си́це:","Ра́дуйся, Христа́ от ю́ности своєя́ возлюби́вий;","ра́дуйся, ду́шу і живо́т свой Єму́ всеці́ло преда́вий.","Ра́дуйся, во́лею своє́ю Го́споду поработивийся;","ра́дуйся, в непреста́ннім упова́нії на Него́ утвердивийся.","Ра́дуйся, пре́жде сме́рти для ми́ра гріхо́внаго уме́рий;","ра́дуйся, жизнь ві́чную єще́ в земні́м тілесі́ во Христі́ обріти́й.","Ра́дуйся, о́бразе соверше́нния ві́ри і любве́;","ра́дуйся, зерца́ло непости́днаго упова́нія.","Ра́дуйся, смире́нія Христо́ва наслі́дниче;","ра́дуйся, милосе́рдія Єго́ подража́телю.","Ра́дуйся, непреста́нную па́м'ять о сме́рті стяжа́вий;","ра́дуйся, сіте́й вра́жиїх се́ю ізбегнувий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до явля́ється, блаже́нне, і́м'я твоє́ вку́пі с Преблагословенной Богородицей і преподо́бним І́овом, моли́твенно призива́ющим: ма́лоє бо принося́ще вам проше́ніє, а́біє такови́м сугу́бим предста́тельством, от ве́ліїх скорбе́й і неду́гов приє́млем ско́роє ізбавле́ніє, да вопіє́м о вас Бо́гу ра́дующеся: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь любве́ Боже́ственния іспо́лнен, свя́то окормля́л єси́ люде́й мно́жества, я́ко к ста́рцю духоно́сному, во ізгна́ніє твоє́, в Ма́ло-Іловицькую весь, к тебі́ притека́ющих. Ти же ну́жди їх ми́лостивно удовля́я, к житію́ богоуго́дному мно́гих приобщил єси́. Та́ко і ми житіє́м твої́м, в і́стині і благоче́стії утвержда́єми, зове́м ті си́це:","Ра́дуйся, но́вий безсребренниче, болі́зні на́ша ісціля́ющий;","ра́дуйся, благові́стниче ізря́дний, ві́ру пра́вую в землі́ на́шей утвержда́ющий.","Ра́дуйся, служи́телю Бо́жий, всім себі́ поработи́вий і мно́гі ко Христу́ приведи́й;","ра́дуйся, подви́жниче кро́ткий, оби́дящих тя ми́лующий і лю́б'ящий.","Ра́дуйся, па́стирю богому́дрий, ра́зум спасе́нія лю́дем подаю́щий;","ра́дуйся, ста́рче благода́тний, душі́ нераска́янних обновляющий.","Ра́дуйся, о́тче святи́й, се́рдця чад ко отце́м обраща́ющий;","ра́дуйся, учи́телю покая́нія, кающимся со́вість омива́ющий.","Ра́дуйся, проро́че Бо́га жива́го, стра́ждущим ми́лость ізливающий;","ра́дуйся, гро́ме богогла́сний, враги́ ві́ри устраша́ющий.","Ра́дуйся, простоти́ стяжа́телю, прему́дрия ві́ка сего́ посрамляющий;","ра́дуйся, І́стини служи́телю, смире́нним ра́зум озаря́ющий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 9","ps":["Вся́ких зол і скорбе́й, житіє́ твоє́ бисть іспо́лнено, преподо́бне, і́миже де́мони і зли́я лю́ди уязви́ти тя тщашася, но нічто́же успі́ша, обрі́тше в тебі́ тве́рдий столп ві́ри і неіссякаємий істо́чник любве́, в ни́хже па́че возраста́я і сугу́бия благода́ті сподобля́яся, да́же до кончи́ни своєя́ блаже́нния, в благоду́шії піл єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вся́кий день і час мно́гія моли́тви возноси́л єси́, о́тче, ко Пречи́стой Влади́чиці на́шей Богоро́диці, Єя́ вели́чіє і ма́тернюю любо́в к нам грі́шним восхваля́юще. Ни́ні же тя о оби́телі твоє́й, ку́пно со І́овом преподо́бним, те́плаго засту́пника і неотступнаго моли́твенника к Ней разумі́юще, та́ко вопіє́м ті:","Ра́дуйся, ізбра́нниче Бо́жия Ма́тере;","ра́дуйся, святи́я оби́телі Єя́ пресла́вний во́їне.","Ра́дуйся, чудотво́рную іко́ну Пречи́стия свя́то почитавий;","ра́дуйся, і слі́ду стопи́ Єя́ десни́я, благогові́йно покланявийся.","Ра́дуйся, сла́ву Присноді́ви на всяк день воспевавий;","ра́дуйся, на ми́лость Єя́ упова́ніє своє́ полага́вий.","Ра́дуйся, в по́двизіх мона́шеських і труді́х ісповедничеських І́ову преподо́бному досто́йні подража́вий;","ра́дуйся, отця́ сего́ свята́го, чудотворе́нія дар восприя́вий.","Ра́дуйся, на жа́тву духо́вную Го́сподем по́сланний;","ра́дуйся, на ни́ві Христо́вій рачи́тельно потруди́вийся.","Ра́дуйся, Царя́ Небе́снаго благоволе́нія іска́вий;","ра́дуйся, мирськи́я сла́ви і хвале́нія, юро́дством бегавий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 10","ps":["Спасе́нія на́шего і ни́ні наста́вник бу́ди преподо́бне, да зря́ще нетлі́нноє ті́ло твоє́, от су́єтних і ло́жних ми́ра сего́ отбіга́ти науча́ємся; лі́ность і небреже́ніє о душе́ своє́й, трудо́м і моли́твою попира́я; о чистоті́ пло́ті і ду́ха тща́тися, всім се́рдцем поуча́ємся, в наде́жді спасе́нія, пою́ще Бо́гу: Алиллуїя."]},{"h":"Ікос 10","ps":["Стіна́ неруши́мая от находя́щих зол бил єси́, преблаже́нне: скорб'я́щих утіша́я, боля́щих ісціля́я, бі́си ізгоня́я, і от напа́стей сохраня́я. Да́же до днесь си́лу Бо́жию в тебі́ су́щую, всім с ві́рою і любо́вію к тебі́ приходящим явля́єши, подвиза́я в благодарности пі́ти тебі́:","Ра́дуйся, о́тче, я́ко єще́ живу́ ті су́щу лю́діє землі́ ру́ськия к тебі́ притека́ху;","ра́дуйся, я́ко і ни́ні, пото́ци наро́дов святи́я Русі́, і́щущих ісціле́ній у цільбоно́сних моще́й твої́х, не оскудіва́ють.","Ра́дуйся, богобо́рцев лука́вих обличи́телю;","ра́дуйся, богопроти́внаго нече́стія іскорени́телю.","Ра́дуйся, мир Бо́жий в себі́ стяжа́вий;","ра́дуйся, сла́дость сію́ неізрече́нную вкуси́ти, мно́гих сподо́бивий.","Ра́дуйся, в і́стинном смире́нії се́рдце своє́ утверди́вий;","ра́дуйся, сим ору́жієм, ку́пно с моли́твою, де́мони порази́вий.","Ра́дуйся, Отцю́ Небе́сному сино́вне послужи́вий;","ра́дуйся, і́стинний Христа́ Спаси́теля учениче́.","Ра́дуйся, благозвучний Ду́ха Свята́го орга́не;","ра́дуйся, чи́стоє Святи́я Тро́йці жили́ще.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 11","ps":["Піснь благодаре́нія во всіх обстоя́ніїх ско́рбнаго житія́ своєго́, Подвигополо́жнику Христу́, непреста́нно приноси́л єси́, уго́дниче Бо́жий, ми же, обрі́тше в тебі́ такова́го пред Бо́гом засту́пника, і в находя́щих напа́стіх защи́тника, по о́бразу твоєму́, в ско́рбіх і ра́достіх свої́х, прилежи́м ви́ну воспіва́ти Го́сподеві: Алиллуїя."]},{"h":"Ікос 11","ps":["Світи́льник многосві́тлий яви́лся єси́, богоно́се, заря́ми чуде́с і о́бразом благоче́стія ві́рния просвіща́я. Но і по успе́нії твоє́м не оскуді́ в тебі́ сія́ благода́ть, ю́же приходящим с ві́рою ко гро́бу твоєму́ ще́дро подає́ши, да нави́кнуть сла́вити Бо́га, всіх чуде́с Істо́чника, тебі́ же глаго́лати си́це:","Ра́дуйся, безсре́бренников і чудотво́рцев приє́мниче;","ра́дуйся, тіле́с на́ших здра́віє і душ спасе́ніє.","Ра́дуйся, я́ко тобо́ю от страсте́й тіле́сних ізбавля́ємся;","ра́дуйся, я́ко тобо́ю сла́достей духо́вних ісполня́ємся.","Ра́дуйся, оби́телі твоєя́ і ве́сі оте́чеськия сла́вная похвало́;","ра́дуйся, всіх богому́дрих прему́драя добро́то.","Ра́дуйся, мно́гих от поги́белі ісхи́тивий;","ра́дуйся, безчи́сленних неврежде́нно сохрани́вий.","Ра́дуйся, бісо́в многоплачевноє пораже́ніє;","ра́дуйся, землі́ Воли́нськия освяще́ніє.","Ра́дуйся, сія́ніє, ско́рбний мрак разгоня́ющеє;","ра́дуйся, світи́ло, тьму безбо́жия просвіща́ющеє.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 12","ps":["Благода́тію в горни́лі скорбе́й, я́ко зла́то очище́нний, вінце́м іспові́дничества і преподо́бія блиста́ющий, по сконча́нії своє́м возврати́лся єси́ в оби́тель Поча́євськую. Во́лею же Бо́жиєю во обрі́тенії нетлі́нних моще́й твої́х в послі́дняя лі́та нам яви́лся єси́, духо́вно всіх утіша́я і пі́ти Бо́гу, ди́вному во святи́х Свої́х, воздвиза́я: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще житіє́ твоє́ богоуго́дноє і чуде́с мно́жества, о́тче Амфіло́хіє, восхвали́ти тя по достоя́нію недоумі́єм, но ві́дяще благоутро́біє твоє́ к немощствующим, моли́мтися і ни́ні воспіва́ющим тя ниспосла́ти свою́ благости́ню, да под моли́твенним кро́вом твої́м сохраня́ємі, в ре́вности о спасе́нії, ви́ну велича́єм тя зва́нії си́ми:","Ра́дуйся, Бо́гом Отце́м предизбранний;","ра́дуйся, страда́льчеським житіє́м предочище́нний.","Ра́дуйся, ду́шу свою́ за бли́жнія полага́вий;","ра́дуйся, ни́ні же ю в раї́ обріти́й.","Ра́дуйся, Ду́ха Свята́го добро́тами блиста́ющий;","ра́дуйся, Того́ же благода́тію благоуха́ющий.","Ра́дуйся, мно́гими ісціле́ньми от гро́ба твоєго́ істочаємими, сви́ше свиді́тельствуємий;","ра́дуйся, крестами облачними, в день земна́го прославле́нія твоєго́ явле́нними, от Небе́снаго Отця́ просла́вленний.","Ра́дуйся, от Подвигополо́жника Христа́ увінча́нний;","ра́дуйся, с пра́ведними сопричтенний.","Ра́дуйся, во оби́телі небе́сній блаженствующий;","ра́дуйся, у престо́ла Святи́я Тро́йці о нас хода́тайствующий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 13","ps":["О преблаже́нне о́тче Амфіло́хіє, ди́вний ціле́бниче і притекающим к тебі́ ско́рий помо́щниче, не лиши́ і нас, смире́нно к тебі́ припа́дающих, своєго́ благода́тнаго посіще́нія: болі́зні на́ша ісціли́, ско́рби утоли́, жизнь умири́; да предста́тельством твої́м ко Всеви́шнему Влади́ці, от вся́каго зла і лука́ваго ді́йства ізба́вльшеся, во ві́ки віко́в поє́м Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгелу Рафаї́лу, моли́тви стра́ждущих Бо́гу принося́щему і здра́віє благода́тію Єго́ с небесе́ подаю́щему, уподоб'яся преподо́бне, я́ко врач ізря́дний яви́лся єси́, ісціля́ющий на́ша неду́ги многоразли́чния. Ми же, помина́юще пресла́вноє твоє́ житіє́, та́ко вопіє́м ті:","Ра́дуйся, землі́ Воли́нськия свято́є прозябе́ніє;","ра́дуйся, роди́телей благочести́вих ча́до благослове́нноє.","Ра́дуйся, ізмла́да во ві́рі і́стинній воспита́нний;","ра́дуйся моли́твенноє ді́ланіє і тіле́сноє воздержа́ніє ізді́тська возлюби́вий.","Ра́дуйся, от ю́ности своєя́ во благоче́стії просія́вий;","ра́дуйся, доброді́телі роди́телей свої́х унаслі́дивий.","Ра́дуйся, іску́сному врачеванію, отце́м свої́м, обученний;","ра́дуйся, благоговенію і кро́тости ма́тері своєя́ подража́ти тщавийся.","Ра́дуйся, супроти́в по́хоті пло́ті, хране́нієм ді́вства і чистоти́ подвиза́вийся;","ра́дуйся, на по́хоть оче́с цілому́дрієм вооружи́вийся.","Ра́дуйся, го́рдості жите́йськой смиренному́дрієм противуставий;","ра́дуйся, Христо́ви за́повіді боголю́бія і братолю́бія іспо́лнивий.","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Кондак 1","ps":["Ізбра́нниче Христо́в і оби́телі Поча́євския но́вий чудотво́рче, скорб'я́щих ско́рий уті́шителю і неду́жних благода́тний ціли́телю, преподо́бне о́тче Амфіло́хіє, любо́вію восхваля́юще богоуго́дноє житіє́ твоє́, піснь благодаре́нія о тебі́ Бо́гу прино́сим. Ти же я́ко дерзнове́нний к Нему́ моли́твенник і те́плий о нас хода́тай, іспроси́ всім с ві́рою к тебі́ приходящим, от душе́вних і тіле́сних зол свобожде́ніє, да ви́ну зове́м ті:","Ра́дуйся, преподо́бне о́тче Амфіло́хіє, те́плий наш засту́пниче і преди́вний ціле́бниче."]},{"h":"Молитва","ps":["О, всеблаже́нне о́тче наш Амфіло́хіє, земни́й А́нгеле і небе́сний челові́че! Припа́даєм к тебі́ с ві́рою і любо́вію і мо́лим ті ся прилі́жно: яви́ нам смире́нним і грі́шним свято́є своє́ заступле́ніє; се бо гріх ра́ди на́ших не і́мами дерзнове́нія проси́ти о потре́бах на́ших Го́спода і Влади́ку на́шего, но тебі́, моли́твенника благоприя́тнаго, к Нему́ предлага́єм і про́сим тя со усе́рдієм мно́гим: іспроси́ нам от бла́гости Єго́ благопотре́бная да́ри душа́м і тілесе́м на́шим, ві́ру пра́ву, любо́в ко всім нелицемі́рну, в злострада́ніїх терпі́ніє, тя́жкими болі́знями одержи́мим - от неду́гов ісціле́ніє, под бре́менем скорбе́й і напа́стей неудобоносимих па́дающих і житія́ своєго́ отча́явшихся твої́ми моли́твами получи́ти ско́роє облегче́ніє і ізбавле́ніє.","Не забу́ди, блаже́нне о́тче, і оби́тель сію́ святу́ю, в ней же подвиза́лся єси́, при́сно тя чту́щую, но соблюди́ ю і всіх живу́щих і подвиза́ющихся в ней і на поклоне́ніє в ню приходя́щих невреди́мими от іскуше́ній дия́вольських і вся́каго зла. Єгда́ же приспі́єть на́ше от вре́меннаго сего́ житія́ отше́ствіє, і к ві́чності преселе́ніє, не лиши́ нас по́мощі твоєя́ небе́сния, но моли́твами твої́ми всіх нас приведи́ в приста́нище спасе́нія і наслі́дники яви́ нас би́ти всесві́тлаго Ца́рствія Христо́ва, да поє́м і сла́вим неізрече́нния щедро́ти Человіколю́бця Бо́га Отця́ і Си́на і Свята́го Ду́ха і твоє́ вку́пі с преподо́бним І́овом оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Землі́ Воли́нськия пресла́вна подви́жника / і оби́телі Поча́євския досто́йна насе́льника / люде́й правосла́вних ізря́дна ціли́теля / яви́ тя Це́ркві Своє́й Христо́с Бог наш, / преподо́бне о́тче Амфіло́хіє, / Єму́ же усе́рдно моли́ся / от наві́т вра́жиїх свободи́тися // і спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Я́ко ві́ри Правосла́вния ревни́тель і благоче́стнаго житія́ учи́тель, в болі́зніх і ско́рбіх ізря́дний помо́щник і защи́титель, пред Го́сподом предстої́ши преподо́бне Амфіло́хіє, сего́ ра́ди вопіє́м ті: сохрани́ оби́тель, в ней же подвиза́лся єси́, і спаса́й нас моли́твами твої́ми, о́тче блаже́нне."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Амфіло́хіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст священномученику Володимиру, митрополиту Київському і Галицькому","e":"Akathist to the Hieromartyr Volodymyr, Metropolitan of Kyiv and Halych","secs":[{"h":"Кондак 1","ps":["Ізбра́нний па́стирю Христо́ва стада́ і сосу́де досто́йний Бо́жия благода́ті, ві́ри Правосла́вния побо́рниче, от безбожников да́же до сме́рти пострада́вий, пі́сньми велегла́сно восхваля́єм тя, світоза́рний о́тче наш Влади́мире, ти же, дерзнове́ніє ко Го́споду іми́й, на стезю́ спасе́нія наста́ви нас, благоче́стною любо́вію пою́щих ті:","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Ікос 1","ps":["А́нгельською любо́вію ко Го́споду горевий і ізмла́да нрав твой долготерпіли́в і кро́ток показа́вий, ми́ру Правосла́вному христия́нин всесоверше́н яви́лся єси́, іспові́дниче Христо́во Влади́мире. Ни́ні же Трисвяту́ю піснь на небесі́х со А́нгельськими чи́ньми воспіва́яй, недосто́йних нас усли́ши, на землі́ со слеза́ми умиле́нія взива́ющих:","Ра́дуйся, благочести́вих роди́телей пресла́вноє рожде́ніє.","Ра́дуйся, благо́є і богодухове́нноє тіх воспита́ніє.","Ра́дуйся, от ю́ности Христу́ служи́ти возжела́вий.","Ра́дуйся, нелицемі́рную по Бо́зі ре́вность показа́вий.","Ра́дуйся, благоутро́бія Христо́ва подража́телю.","Ра́дуйся, Єва́нгельськаго сло́ва благовествователю.","Ра́дуйся, блиста́ніє Боже́ственнаго сві́та.","Ра́дуйся, сія́ніє небе́сния благода́ті.","Ра́дуйся, душі́ ві́рних просвіща́яй.","Ра́дуйся, се́рдця і́щущих пра́вди Бо́жієй озаря́яй.","Ра́дуйся, челові́че небе́сний.","Ра́дуйся, а́нгеле земни́й.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 2","ps":["Ви́дя і разуміва́я во вся́цій ско́рби і напа́сти ко спасе́нію душ на́ших наставле́ніє, не уни́ і не отча́яся, святи́й Влади́мире, єгда́ лиши́лся єси́ си́на о́трока і любе́зния твоєя́ супру́ги. Но терпіли́вно скорб сію́ под'ял єси́ і утіше́ніє в мона́шестві обрі́л єси́, стопи́ своя́ ко служе́нію Єди́ному Христу́ направля́яй. Сподо́би же і нас во всіх біда́х Благоподателя святу́ю во́лю разумі́ти, не противля́тися спаси́тельному Про́мислу Єго́, но при́сно сла́вити за вся Творця́ і Бо́га: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Всеви́шній приосени тя, па́стирю всехва́льний наш Влади́мире, єгда́ ізбра́ тебі́ Госпо́дь во єпи́скопа святи́я Це́ркве Правосла́вния, во є́же день і нощ пещи́ся ті о агнціх Бо́жиїх, да ні єди́н у́бо от них поги́бнеть. Ти же, я́ко послу́шник трудолю́бний, па́стирськоє ді́ланіє смиренному́дренно твори́л о́си. Та́ко і ни́ні, во оби́теліх небе́сних пребива́яй, наста́вник неуси́пний бу́ди нам, на тя надеющимся і глаго́лющим із глубини́ серде́чния:","Ра́дуйся, вся кра́сная і сла́дкая ми́ра сего́ презрі́вий.","Ра́дуйся, от тлі́нних на нетлі́нная о́чі духо́вния обрати́вий.","Ра́дуйся, єпи́скопство я́ко вели́кий дар Госпо́день восприя́вий.","Ра́дуйся, оби́льно в хиротонії благослове́ніє небе́сноє стяжа́вий.","Ра́дуйся, наде́жний ко спасе́нію путеводи́телю.","Ра́дуйся, заблу́ждших неуста́нний вразуми́телю.","Ра́дуйся, му́дрих ві́ка сего́ мудрі́йший.","Ра́дуйся, ра́бе Христо́в добрі́йший.","Ра́дуйся, ієра́рше сла́вний, со святи́ми почива́яй.","Ра́дуйся, моли́тв твої́х покро́вом па́ству при́сно соблюда́яй.","Ра́дуйся, неусипа́ємий в біда́х помо́щниче.","Ра́дуйся, благи́й о нас печа́льниче.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго незри́мо укріпля́єм, і́стинноє му́жество яви́л єси́, преблаже́нне архіпа́стирю Влади́мире, єгда́ спаса́ше от гла́да і от мо́ра твоя́ страдающая ча́да. Зрел єси́ о́крест, я́ко мно́зі мо́ром гибляху, оюаче не смутился єси́, но Кресто́м Животворя́щим і Честни́м вооружи́вся, прехожда́ше посреді́ люде́й поволжських, по́мощ подая́, печа́лі утоля́я. Та́кожде і нам, духо́вним гла́дом істощеваємим і неду́гом малові́рія одержи́мим, помози́ предста́тельством твої́м ко Го́споду, прославля́ємому при́сно: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй ви́ну попече́ніє о ча́діх Бо́жиїх, сих оте́чеськи к богоуго́дній жи́зні направля́л єси́, посто́м, моли́твою і пра́ведними ді́ли преди́вний по́двиг в подража́ніє святи́м Христо́вим показа́вий. Сего́ ра́ди твоя́ па́стирськия доброді́телі хва́ляще, тя, Боголю́бче, ублажа́єм си́це:","Ра́дуйся, благоутро́бія вели́каго сокро́вищ.","Ра́дуйся, Боже́ственнаго промишле́нія о нас прия́телище.","Ра́дуйся, Святи́я Це́ркве Правосла́вния украше́ніє.","Ра́дуйся, о ча́діх твої́х те́плоє моле́ніє.","Ра́дуйся, о ми́рі па́стви твоєя́ рачи́телю.","Ра́дуйся, от вся́ких бід усе́рдний наш храни́телю.","Ра́дуйся, покро́ве, на путі́ спасе́нія нас осіня́яй.","Ра́дуйся, сто́лпе огневи́дний, во тьмі неві́дінія нас просвіща́яй.","Ра́дуйся, я́ко коре́нія смуще́ній трудолю́бно історгал єси́.","Ра́дуйся, я́ко те́рніє неві́рія глаго́лом попаля́л єси́.","Ра́дуйся, архієре́ю Бо́жий, Пастиреначальником Христо́м просла́вленний.","Ра́дуйся, ієра́рше Христо́в, даро́в Ду́ха Свята́го преіспо́лненний.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 4","ps":["Бу́рю ве́лію преще́ній вра́жиїх отврати́ от нас моли́твами твої́ми, всеусе́рдний Го́спода служи́телю Влади́мире, і бу́ди нам і огражде́ніє необори́моє, я́ко в животі́ твоє́м защи́титель безме́здний бил єси́ всім, Царю́ Небе́сному пою́щим: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша і ви́дя мно́жество напа́стей ми́ра сего́, сам болі́зні і тяготи́ терп'я́, ніколи́же бли́жнія і дру́ги забивал єси́, милосе́рдні о́тче наш Влади́мире, но оте́чеськими попече́нії всім помога́я, ні єди́но же проше́ніє нужда́ющихся презрі́л єси́. Научи́ і нас друг дру́га тяготи́ носи́ти, воспіва́ющія і прославляющия тя си́це:","Ра́дуйся, любо́вію Боже́ственною горя́й.","Ра́дуйся, за дру́ги своя́ ду́шу не щадя́й.","Ра́дуйся, я́ко мно́гі ско́рби і труди́ под'ял єси́.","Ра́дуйся, я́ко вся ра́ди Возлю́бльшаго тя претерпі́л єси́.","Ра́дуйся, вдови́ць і си́рих щедрейший пита́телю.","Ра́дуйся, гони́мих і оби́димих предста́телю.","Ра́дуйся, скорб'я́щим сострадателю.","Ра́дуйся, просящим ми́лости пода́телю.","Ра́дуйся, ча́ше, єле́й ми́лости Бо́жия к нам содержа́щая.","Ра́дуйся, горо́, ту́чі гні́ва Госпо́дня от нас отводя́щая.","Ра́дуйся, і по преставле́нії твоє́м с на́ми пребива́єши.","Ра́дуйся, я́ко в селе́ніїх небе́сних почива́я, нас не оставля́єши.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́ ми́ру і світи́льник те́плий лю́дем правосла́вним, архіпа́стирю Влади́мире, пастиренача́льник в тріє́х стольних граді́х ру́ських би́вий, найпа́че же во обличе́нії раско́лов порадевий, во є́же нераздран хито́н Христо́в нешвенний сохрани́ти. Таково́му о тебі́ проізволе́нію Госпо́дню ра́дующеся, воспіва́єм Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя тя в селе́ніїх небе́сних, зіло́ ра́дується святи́й равноапостольний Влади́мир, і́мже возсія́ нам світ Христо́ви І́стини, зане́ і ти Боже́ственною во́лею в богохранимем гра́де Ки́єве просла́вился єси́, страдальчествуя за Христа́ во дні вели́ких іспита́ній. Та́ко і ми, блаже́нне, ликовству́єм о тебі́:","Ра́дуйся, крести́теля Русі́ досто́йний соіменниче.","Ра́дуйся, того́ нелі́ностний споспі́шниче.","Ра́дуйся, в страні́ Ру́ськой боголучно возсія́вий.","Ра́дуйся, па́ству твою́ духо́вно удобрявий.","Ра́дуйся, богоуго́дно на землі́ пожи́вий.","Ра́дуйся, любо́вію Боже́ственною страх сме́ртний побіди́вий.","Ра́дуйся, священному́чениче, за Христо́ву ві́ру пострада́вий.","Ра́дуйся, страда́льче, дух твой в ру́ці Го́споду преда́вий.","Ра́дуйся, смерть вкуси́вий, тлі́нія не зна́яй.","Ра́дуйся, с Печерськими отці́ во святи́х пеще́рах почива́яй.","Ра́дуйся, оби́телі пресла́вній украше́ніє.","Ра́дуйся, мона́шествующих в ней утіше́ніє.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 6","ps":["Пропові́дниче усе́рдний сло́ва Бо́жия, Влади́мире, многомудрими віща́нії твої́ми лжеученія безбо́жних облича́л єси́, от прельще́ній душепа́губних Христо́ва ча́да сохраня́я. Ті́мже удосто́їлся єси́ непреста́нних славословій на землі́, воспіва́яй во Ви́шніх Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в оте́честві своє́м, іспові́дниче Христо́во Влади́мире, я́ко но́воє світи́ло на небе́сній тве́рди, сія́нієм по́двигов твої́х тьму нече́стія разгоня́яй і мир правосла́вний ублажа́ти тя си́це подвиза́яй:","Ра́дуйся, крі́пкая ваїє дре́ва правові́рія.","Ра́дуйся, богоізбра́нний посрами́телю неві́рія.","Ра́дуйся, Єва́нгельськоє сло́во, я́ко меч духо́вний, возлюби́вий.","Ра́дуйся, от стріл лука́ваго щито́м ві́ри ся оградивий.","Ра́дуйся, усти́ многомудрими Боже́ственния і́стини віща́яй.","Ра́дуйся, пред Бо́гом заступле́ніє нам крі́пкоє явля́яй.","Ра́дуйся, свіще́, моли́твенним огне́м за нас горя́щая.","Ра́дуйся, драго́є ми́ро, в хра́мі Бо́жиєм благоуха́ющеє.","Ра́дуйся, даро́в небе́сних неоску́дноє вмісти́лище.","Ра́дуйся, Боже́ственния му́дрости храни́лище.","Ра́дуйся, крі́пкоє па́дающих возведе́ніє.","Ра́дуйся, стоя́щих пра́во утвержде́ніє.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 7","ps":["Хотя́й просла́вити тя ві́рою необоримою, даде́ узрі́ти ті Влади́ка наш Госпо́дь, ка́ко безбожници в оби́телі Пече́рстій, я́ко во а́ді бі́си, бесновашася, безсту́діє творя́ще і дре́внія святи́ні оскверня́юще. Но сих преще́ній вра́жиїх не убоя́вся, богоізбра́нний о́тче наш Влади́мире, Єди́ному Засту́пнику от вся́ких зол усе́рдная моле́нія возне́сл єси́, взива́я неосла́бне Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий о́браз милосе́рдія яви́л єси́ нам, му́чениче і святи́телю Влади́мире, єгда́ пред кончи́ною благослови́л єси́ мучи́телі твоя́. Таково́му твоєму́ незло́бію див'я́щеся і в тебі́ неізрече́нну сла́ву Человіколю́бця зря́ще, славосло́вим тя і восхваля́єм си́це:","Ра́дуйся, милосе́рдія небе́снаго зерца́ло.","Ра́дуйся, Христо́ви Це́ркве тве́рдоє забра́ло.","Ра́дуйся, прерадостноє на́ше утіше́ніє.","Ра́дуйся, лука́вим си́лам устраше́ніє.","Ра́дуйся, моли́тися за недруги учи́вий.","Ра́дуйся, і сам мучи́телі твоя́ прости́вий.","Ра́дуйся, я́ко тобо́ю безу́мнії глумителіє посрамля́ються.","Ра́дуйся, я́ко тобо́ю си́ла Бо́жия явля́ється.","Ра́дуйся, всече́стно почита́ємий на землі́.","Ра́дуйся, вінце́м нетлі́нним украше́нний на небесі́.","Ра́дуйся, я́ко с преподо́бними отці́ во ві́ки пребива́єши.","Ра́дуйся, я́ко оте́чество на́ше ку́пно с ті́ми защища́єши.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 8","ps":["Страннолепен і великоімени́ть, іспові́дниче Христо́во Влади́мире, я́ко радетель неуси́пний о Госпо́днем до́ме бил єси́, моли́тви і труди́ твоя́ на благоустроє́ніє хра́мов направля́я. О чиннем же богослуже́нії і доброгла́снім пі́нії ревну́я, награ́ду ве́лію у Го́спода сниска́л єси́, в небе́сних вертогра́діх А́нгели піт би́ти. Ми же, зря́ще ни́ні разоренних хра́мов восстановленіє і лі́поти церко́вния поновле́ніє, к тебі́ взива́єм: помози́ воздви́гнути святи́я хра́ми в душа́х на́ших і доброді́тельми їх украси́ти, с тобо́ю ку́пно воспіва́юще Благоподателю і Жизнода́вцю: Аллилу́я."]},{"h":"Ікос 8","ps":["Всея́ землі́ Ру́ськия архіпа́стирю, пе́рвий із новому́чеников во вре́м'я лю́тоє гоне́ній на правосла́вних христия́н пострада́вий, зове́м тя, благода́ть стяжа́вшаго моли́тися за мир: не премолчи́ о нас, к свяще́нній твоє́й ра́ці припа́дающих і во умиле́нії пою́щих піснь тебі́:","Ра́дуйся, крест свой на ра́мена, Христу́ послі́дуя, под'явий.","Ра́дуйся, стезю́ страда́ній за Него́ ізбра́вий.","Ра́дуйся, мудрі́йший стра́нниче, іски́й оте́чества небе́снаго.","Ра́дуйся, уго́дниче Христо́в, презрі́вий вся земна́я.","Ра́дуйся, до́му Бо́жию наде́жний стра́же і храни́телю.","Ра́дуйся, ієре́єв до́брий попечи́телю.","Ра́дуйся, ка́ющихся с Бо́гом примири́телю.","Ра́дуйся, Спаси́теля возлю́бльших покрови́телю.","Ра́дуйся, досто́йний А́нгелов собесі́дниче.","Ра́дуйся, Апо́столом Христо́вим сопресто́льниче.","Ра́дуйся, благоприя́тную ко Го́споду моли́тву возсилаяй.","Ра́дуйся, те́плою моли́твою твоє́ю держа́ву на́шу согреваяй.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 9","ps":["Всі чи́ни А́нгельстії і святи́телей лик удиви́шася, зря́ще тя, Влади́мире, но́ваго му́ченика, в пострадавшей і поруганней землі́ Ру́ськой просія́вшаго. Ми же ни́ні прославля́юще по́двиг твой, ко Го́споду і Спа́су на́шему взива́єм: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я богому́дрий Це́ркве Правосла́вния і до́блій во́їн Христо́в бил єси́, священному́чениче препросла́вленний Влади́мире. Імі́яй се́рдце м'ягко, а́ки воск, во́лю же тве́рду, а́ки адама́нт, не клонился єси́ сі́мо і ова́мо ні пред вла́стію людською, ніже́ пред обстоя́нії мирськи́ми, і сего́ ра́ди поноше́нія претерпі́л єси́. Ві́рность Го́споду Єди́ному храни́вий ви́ну, усли́ши ни́ні піснь побі́дную сію́:","Ра́дуйся, во́їне Христо́в непобіди́мий.","Ра́дуйся, в терпі́нії тверді́йший адама́нте невредимий.","Ра́дуйся, я́ко неблагомислящих наві́ти претерпі́л єси́.","Ра́дуйся, я́ко от яростних поноше́нія прия́л єси́.","Ра́дуйся, серде́ць см'яте́нних умири́телю.","Ра́дуйся, от озлобле́нія на нас вражду́ющих храни́телю.","Ра́дуйся, духо́вних соверше́нств висото́.","Ра́дуйся, смире́нія христия́нськаго глубино́.","Ра́дуйся, ру́ських му́чеников удобре́ніє.","Ра́дуйся, архієре́єв правосла́вних похвале́ніє.","Ра́дуйся, я́ко от неві́рія ізбавля́єши.","Ра́дуйся, я́ко от малоду́шія ісціля́єши.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 10","ps":["Спаси́тельнаго о нас про́мисла сія́ніє яви́ся нам, єгда́ страда́льчеськую смерть прия́л єси́, священнопропові́дниче Влади́мире, ти бо же́ртва непоро́чная і яви́лся єси́ хода́тай за люде́й правосла́вних, отступле́нієм от ві́ри согріши́вших. Ми же ни́ні сокруше́нним се́рдцем со слеза́ми о спасе́нії страни́ Ру́ськия моля́щеся, к Судії́ Благоутро́бному взива́єм: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ і огражде́ніє держа́ви на́шея, святи́телю Влади́мире, радетель неуста́нний о уста́віх правосла́вних бил єси́. Сохрани́ і ни́ні нас от па́губния є́ресі, огради́ от раздира́нія Церкве́й, упаси́ от соблазненія лжеученьми, да пребу́дем в ло́ні Це́ркве і́стинния. Твоєго́ же ра́ди заступле́нія неуста́нно вопіє́м ті си́це:","Ра́дуйся, Правосла́вія небла́зненний ревни́телю.","Ра́дуйся, шата́нія Церкве́й іскорени́телю.","Ра́дуйся, Церко́вних Та́їнств благоче́стний соверши́телю.","Ра́дуйся, в Небе́сний Ієрусали́м путеводи́телю.","Ра́дуйся, мечу́, раскол і є́ресь посіця́яй.","Ра́дуйся, небе́сний гро́ме, го́рдих устраша́яй.","Ра́дуйся, Єва́нгельськаго сві́та чу́дноє блиста́ніє.","Ра́дуйся, за пра́вду поносимих упова́ніє.","Ра́дуйся, Госпо́дню во́лю сотвори́вий.","Ра́дуйся, Христо́ви за́повіді сохрани́вий.","Ра́дуйся, я́ко честну́ю кров за ві́ру пролія́л єси́.","Ра́дуйся, я́ко блаже́нство неот'ємлемоє стяжа́л єси́.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 11","ps":["Пі́ніє похва́льноє, є́же прино́сим ті, богоблагода́тний па́стирю Влади́мире, ність дово́льно восхвали́ти я́ко подоба́єть тя, благоче́стноє вмісти́лище Свята́го Ду́ха, но всехва́льних ра́ди доброді́телей твої́х вопіє́м ті: моли́ Го́спода о нас, сту́дними гріхми́ окалявшихся, да низпосле́ть чудеса́ неізрече́нния Своєя́ ми́лості на нас, с тобо́ю вку́пі днесь пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світода́тельная свіща́ яви́лся єси́ нам, іспові́дниче Христо́в і па́стирю святи́й Влади́мире, разгоня́яй нощ нече́стія і освещаяй путь во тьмі ходя́щих. Ни́ні у́бо умоля́ти не преста́й Христа́ Спа́са і Влади́ку на́шего, да не дасть нам уклони́тися стезі́, ко спасе́нію нас, грі́шних, приводя́щия, но сподо́бит нас во Ца́рствії Своє́м тя со А́нгели святи́ми воспіва́ти:","Ра́дуйся, несокрушенний щиті́, защища́яй благоче́стіє.","Ра́дуйся, мечу́ побі́дний, посіця́яй злоче́стіє.","Ра́дуйся, блужда́ющих в духо́вном мра́ці окорми́телю.","Ра́дуйся, честні́йший преподо́бія храни́телю.","Ра́дуйся, світи́льниче Госпо́день, Це́рков озаря́яй.","Ра́дуйся, моля́щихся ті душі́ умиря́яй.","Ра́дуйся, я́ко неду́гующих ісціля́єши.","Ра́дуйся, я́ко окамененних се́рдцем оживля́єши.","Ра́дуйся, печа́льниче боля́щим і безпомо́щним.","Ра́дуйся, засту́пниче убо́гим і оби́димим.","Ра́дуйся, я́ко помраче́нних просвіща́єши.","Ра́дуйся, я́ко просвіще́нних утвержда́єши.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 12","ps":["Благода́ть даде́ся ті от Бо́га, о́тче присносла́вимий Влади́мире, во є́же би́ти нерушимим ка́менем Христо́ви Це́ркве. Твоєму́ же о́бразу жела́юще всім се́рдцем подража́ти, умоля́єм тя, блаже́нне, непреста́нно: заступи́, да не прельстя́ть нас чудеса́, си́лою лука́ваго твори́мая, ніже́ лжепроро́ци соблазнять. Но во єдиноми́слії і правові́рії вся христия́ни сохрани́, прославляющия Бо́га І́стиннаго: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м пра́ведноє житіє́ твоє́, восхваля́єм пречестно́є твоє́ і́м'я, почита́єм за Христа́ страда́нія твоя́, удивля́ємся духо́вній твоє́й крі́пости, ра́дуємся сла́вному обрі́тенію моще́й твої́х, новому́чениче святи́й Влади́мире, і любо́вію, воспомина́юще о по́двизіх твої́х, воспису́єм ті хвале́нія сія́:","Ра́дуйся, побідоно́сною сві́тлостію облече́нний.","Ра́дуйся, святи́тельському ли́ку сопричтенний.","Ра́дуйся, споспі́шниче усе́рдний а́да Разруши́теля.","Ра́дуйся, послі́дователю ві́рний расп'я́таго Учи́теля.","Ра́дуйся, за ві́ру і оте́чество живо́т свой положи́вий.","Ра́дуйся, архієре́ю до́брий, Бо́гу Человіколю́бцю угоди́вий.","Ра́дуйся, я́ко живо́т твой непоро́чен сохрани́вий.","Ра́дуйся, я́ко до сме́рти ві́рен Го́споду преби́вий.","Ра́дуйся, вінце́м побі́дним па́че звізд на небесі́ блиста́яй.","Ра́дуйся, тимпа́ні сладкозвучний, сла́ву Бо́жию бряцяяй.","Ра́дуйся, во оте́честві небе́снім ни́ні пребива́яй.","Ра́дуйся, і о земні́м оте́честві твоє́м не забива́яй.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 13","ps":["О страда́льче многосві́тлий і святи́телю Христо́во Влади́мире! Прийми́ ма́лоє хвале́ніє сіє́, в простоті́ серде́чній возноси́моє. Воньми́ гла́су недосто́йному моля́щихся тебі́ і твої́ми ско́рими ко Го́споду проше́нії умоли́ Єго́ проба́вити благоутро́біє Своє́ на ни, да сподо́бимся в блаже́нній ра́дости воспіва́ти Єму́ сла́ву: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельською любо́вію ко Го́споду горевий і ізмла́да нрав твой долготерпіли́в і кро́ток показа́вий, ми́ру Правосла́вному христия́нин всесоверше́н яви́лся єси́, іспові́дниче Христо́во Влади́мире. Ни́ні же Трисвяту́ю піснь на небесі́х со А́нгельськими чи́ньми воспіва́яй, недосто́йних нас усли́ши, на землі́ со слеза́ми умиле́нія взива́ющих:","Ра́дуйся, благочести́вих роди́телей пресла́вноє рожде́ніє.","Ра́дуйся, благо́є і богодухове́нноє тіх воспита́ніє.","Ра́дуйся, от ю́ности Христу́ служи́ти возжела́вий.","Ра́дуйся, нелицемі́рную по Бо́зі ре́вность показа́вий.","Ра́дуйся, благоутро́бія Христо́ва подража́телю.","Ра́дуйся, Єва́нгельськаго сло́ва благовествователю.","Ра́дуйся, блиста́ніє Боже́ственнаго сві́та.","Ра́дуйся, сія́ніє небе́сния благода́ті.","Ра́дуйся, душі́ ві́рних просвіща́яй.","Ра́дуйся, се́рдця і́щущих пра́вди Бо́жієй озаря́яй.","Ра́дуйся, челові́че небе́сний.","Ра́дуйся, а́нгеле земни́й.","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Кондак 1","ps":["Ізбра́нний па́стирю Христо́ва стада́ і сосу́де досто́йний Бо́жия благода́ті, ві́ри Правосла́вния побо́рниче, от безбожников да́же до сме́рти пострада́вий, пі́сньми велегла́сно восхваля́єм тя, світоза́рний о́тче наш Влади́мире, ти же, дерзнове́ніє ко Го́споду іми́й, на стезю́ спасе́нія наста́ви нас, благоче́стною любо́вію пою́щих ті:","Ра́дуйся, Влади́мире, негаси́мий Правосла́вія світи́льниче."]},{"h":"Молитва","ps":["О священному́чениче і іспові́дниче Христо́во Влади́мире! Усли́ши сле́зния моли́тви чад твої́х і воздиха́нія, се́рдцем сокруше́нним і смире́нним приноси́мая. Се бо беззако́нії омрачи́хомся і того́ ра́ди біда́ми, я́ко ту́чами, обложи́хомся. Но ти, свя́те Влади́мире, понеси́, я́ко си́льний, не́мощі на́ша, не отлуча́йся от нас ду́хом, да не разлучи́мся в коне́ць от любве́ Бо́жия. При́зри ми́лостивно на предстоящия і моля́щіяся пред свято́ю іко́ною твоє́ю і вся проше́нія їх во благо́є іспо́лни. Ві́руєм бо, я́ко твої́х страда́ній ра́ди за оте́чество і лю́ди россі́йськия ве́ліє дерзнове́ніє ко Го́споду і́маши. Єго́же умоли́, да укріпи́ть ни в Правосла́вії і єдиноми́слії, і непоколеби́мом да́же до сме́рти іспові́данії ві́ри Христо́ви, страну́ на́шу да спасе́ть от междоусо́бния бра́ні, па́стирем на́шим да пода́сть духо́вноє трезві́ніє і ре́вность о спасе́нії пасо́мих, прави́телем же суд і пра́вду, оби́димим заступле́ніє, недугующим душ і тіле́с ісціле́ніє. Ми же, грі́шнії, твої́м предста́тельством укріпля́ємі, восхва́лим Го́спода Ісу́са Христа́, Єму́же сла́ва подоба́єть, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Ві́ри правосла́вния непоро́чний блюсти́телю / і за́повідей Христо́вих усе́рдний ісполни́телю, / священному́чениче Влади́мире, / Христа́ всім се́рдцем возлюби́в, / па́ству твою́ до́брі упа́сл єси́, / незло́биво му́ченичеськую смерть прия́л єси́. / Сего́ ра́ди во ві́чной сла́ві пребива́я, // моли́ спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["По́двигом до́брим я́ко святи́тель Христо́в подвиза́лся єси́, / ві́ру правосла́вную непоро́чно соблю́д, / во дні гоне́нія лю́таго мучи́телей преще́нія не убоя́вся, / священному́чениче Влади́мире, / я́ко первому́ченик Стефа́н, убива́ющим тя рекл єси́: / Госпо́дь да прости́ть вас. / Сего́ ра́ди угото́вася ті віне́ць пра́вди, / єго́же да возда́сть Госпо́дь моли́твами твої́ми // всім почита́ющим тя."]},{"h":"Кондак, глас 4","ps":["О́браз Христо́ва милосе́рдія явля́я, / покро́в і защище́ніє па́стві твоє́й бил єси́, / святи́телю о́тче Влади́мире, / в кро́тості страда́нія приє́мля, / безбо́жних мучи́телей, благословля́я, прости́л єси́. / Ті́мже і нам іспроси́ у Христа́ Бо́га // дух ми́рен і ве́лію ми́лость."]},{"h":"Величання","ps":["Велича́єм тя, / священному́чениче Влади́мире, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому преподобному Никиті Стовпнику, Переяславському чудотворцю","e":"Akathist to our Venerable Father Nicetas the Stylite of Pereslavl, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Взбра́нний чудотво́рче і вели́кий Христо́в уго́дниче! Восхваля́єм тя с любо́вію, ча́да твоя́, те́пла предста́теля к Бо́гу тебі́ стяжа́вше. Ти же моли́ просла́вившаго тя Го́спода от вся́ких нам бід свободи́тися, зову́щим:","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов подо́бника і бісо́в противобо́рця, прови́дя тя всея́ тва́рі Зижди́тель, словеси́ проро́чеськими, — «ізми́йтеся і чи́сти бу́діте», — на покая́ніє огласи́в тя, я́ко втора́го Па́вла, человіколю́бно к Себі́ призва́, нас же научи́ ублажа́ти тебі́ си́це:","Ра́дуйся, сосу́де ізбра́нний, сви́ше Бо́гом предуве́данний;","ра́дуйся, в храм Ду́ха Всесвята́го предуста́вленний.","Ра́дуйся, сподо́бивийся Боже́ственнаго призва́нія;","ра́дуйся, удосто́ївийся от Го́спода оправда́нія.","Ра́дуйся, благода́ть Бо́жию, ум'ягча́ющую се́рдце твоє́, получи́вий;","ра́дуйся, очисти́тельнаго покая́нія то́ки слез істочи́вий.","Ра́дуйся, ві́ру в призва́вшаго тя Го́спода несумне́нну восприя́вий;","ра́дуйся, всего́ себе́ води́тельству Бо́жию преда́вий.","Ра́дуйся, супру́жницю і клевре́тов твої́х Го́спода ра́ди оста́вивий;","ра́дуйся, невозвра́тноє твоє́ ше́ствіє к сниска́нію спасе́нія напра́вивий.","Ра́дуйся, Ца́рствія небе́снаго стяжа́телю;","ра́дуйся, о всіх к тебі́ притека́ющих те́плий ко Го́споду предста́телю.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя супру́жницю твою́, див'я́щуюся преміне́нію сні́дних м'яс, я́коби в челові́чеськія чле́ни, і недоуміва́ющую о неісповіди́мих судьба́х Бо́жиїх, сви́ше озаре́н, іспові́дал єси́, я́ко Госпо́дь на покая́ніє тя призива́єть, і а́біє позна́л єси́ спаса́ющему тя Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий, в ди́вном призва́нії твоє́м проявле́нний разумі́ти іща́, преподо́бне о́тче Ники́то, помишля́л єси́, ка́ко о Го́споді возмощи́ мир і дия́вола посрами́ти, к ла́врі свята́го великому́ченика Ники́ти а́біє поте́кл єси́, іді́же і а́нгельський о́браз на ся восприї́м, добль во́їн Христо́в показа́лся єси́. Ми же, Го́спода спа́сшаго тя прославля́юще, ра́достно вопіє́м ті:","Ра́дуйся, я́ко мита́р, ко Го́споду о поми́лованії вопія́вий;","ра́дуйся, я́ко заблу́ждший син, Отця́ Небе́снаго взиска́вий.","Ра́дуйся, я́ко ханане́я, от Христа́ не отступа́вий;","ра́дуйся, я́ко блудни́ця, о грісі́х рида́вий.","Ра́дуйся, я́ко Єзекі́я, уми́льно моли́вийся;","ра́дуйся, я́ко Манассі́я, в покая́нії смири́вийся.","Ра́дуйся, я́ко І́ов, іскуше́нія крі́пко терпі́вий;","ра́дуйся, я́ко Данії́л, прему́дрость Бо́жию разумі́ти вожделі́вий.","Ра́дуйся, Дави́дово раска́яніє яви́вий;","ра́дуйся, Петро́ви сле́зи істочи́вий.","Ра́дуйся, путь і́стинний к животу́ ві́чному обріти́й;","ра́дуйся, я́ко крин, любо́вію Боже́ственною процвіти́й.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ тя, преподо́бне о́тче Ники́то, єгда́ в нача́лі не бил єси́ удосто́єн прия́тія в ла́вру великому́ченика Ники́ти, і тридне́вним твої́м пред врати́ о́ния присіді́нієм і всенаро́дним гріхо́в твої́х іспові́данієм, побіди́теля на дия́вола тя яви́, науча́я нас Даю́щему крі́пость лю́дем Свої́м Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй богоприя́тноє стремле́ніє во святі́й ла́вре великому́ченика Ники́ти водвори́тися, но от сея́ бив отрева́єм, в ти́нноє бла́то наг пове́рглся єси́ на терза́ніє мши́цем і гадо́м. Ми же, толи́ко крі́пкому твоєму́ терпі́нію див'я́щеся, вопіє́м ті:","Ра́дуйся, ми́ру єди́ножди навсегда́ уме́рий;","ра́дуйся, нераска́янно вся кра́сная ми́ра сего́ презрі́вий.","Ра́дуйся, тщесла́вния по́мисли смири́вий;","ра́дуйся, мисль в Бо́зі утверди́вий.","Ра́дуйся, сребролю́біє ізсуши́вий;","ра́дуйся, сластолю́біє умертви́вий.","Ра́дуйся, вся́кий гнів і ізби́ток зло́би отложи́вий;","ра́дуйся, смиренному́дріє возлюби́вий.","Ра́дуйся, ду́шу твою́ по сло́ву Христа́ возненави́дівий;","ра́дуйся, ді́ли благи́ми Велія́ра преоби́девий.","Ра́дуйся, плоть со страстьми́ і похотьми́ распни́й;","ра́дуйся, по обраще́нії твоє́м не себі́, но єди́ному Бо́гу живи́й.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній сумни́тельних, святи́я ла́ври ігу́мен см'яте́ся, зря тебе́, гріхолюби́ва би́вша, на по́двиги і́ночествующих толи́ко бо́дренно дерза́юща, в мі́сті ті́сні тя затвори́ во іспита́ніє блага́го твоєго́ проізволе́нія; ти же на дия́вола, я́ко Дави́д на Голія́фа, єдинобо́рствовати ра́достно с ка́менем ві́ри поте́кл єси́, поя́ Го́споду сил: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав сказа́нія житі́й дре́вніх подви́жников, преподо́бне, ка́ко от Го́спода наставля́ємі і укріпля́ємі, труди́ ко трудо́м прилага́ху, тім подража́ти возревнова́л єси́, і тя́жкия вери́ги, по благослове́нію ігу́мена, на ся возложи́в, день і нощ в моли́твах пребива́л єси́. Ми же, ди́вноє твоє́ подви́жничество прославля́я, зове́м ті такова́я:","Ра́дуйся, житіє́м отце́в пусти́нних пліне́нний;","ра́дуйся, любо́вію Боже́ственною распале́нний.","Ра́дуйся, проізво́льноє у́зничество возлюби́вий;","ра́дуйся, во умерщвле́ніє пло́ті желі́за на себі́ возложи́вий.","Ра́дуйся, в по́двизіх неутоми́мий;","ра́дуйся, во благоче́стії неохлади́мий.","Ра́дуйся, во пло́ті безпло́тних а́нгелов сожи́телю;","ра́дуйся, своєго́ проізволе́нія во́лі Бо́жієй покори́телю.","Ра́дуйся, ісправле́нії твої́ми безпло́тних удиви́вий;","ра́дуйся, равноа́нгельнаго житія́ о́браз і́стинний нам яви́вий.","Ра́дуйся, в собесі́дованіє с Бо́гом ви́ну углубле́нний;","ра́дуйся, благода́тію Бо́жиєю преобогаще́нний.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 5","ps":["Богопе́сненную псалти́р к достиже́нії небе́снаго оте́чества, я́ко світи́льник, во умі́ твоє́м ви́ну содержа́, то́ю прославля́л єси́ Небе́снаго Отця́, воспіва́я: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше бли́жнії і да́льнії, є́же по Бо́зі житіє́ твоє́, преподо́бне, чу́дному твої́х нра́вов ізміне́нію удивля́хуся, доброді́телі же і по́двиги твоя́ прославля́ху, с ни́ми же і ми си́це вопіє́м ті:","Ра́дуйся, я́ко в ста́рости крі́пость му́жеськую показа́л єси́;","ра́дуйся, я́ко обі́т і́ночества діла́ми оправда́л єси́.","Ра́дуйся, в многостра́стней пло́ті подвиза́вийся, я́ко безпло́тний;","ра́дуйся, благи́ми по́мисли і ді́ли многопло́дний.","Ра́дуйся, твої́ми по́двиги от облене́нія нас возставля́яй;","ра́дуйся, твоє́ю жи́знію путь ко спасе́нію всім із'явля́яй.","Ра́дуйся, любо́во ве́лію к Бо́гу показа́вий;","ра́дуйся, многообра́зні по́мощ Бо́жию іспита́вий.","Ра́дуйся, Бо́жієй любві́ ко ка́ющимся зерца́ло;","ра́дуйся, подвиза́ющимся на дия́вола крі́пкоє забра́ло.","Ра́дуйся, ви́ну о нас с моли́твою Бо́гу предстоя́щий;","ра́дуйся, і по днесь оби́тель твою́ неруши́му храня́щий.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дають тя́жкия твоя́ вери́ги, смиренному́дре Ники́то, труди́ і болі́зні, Бо́га ра́ди тобо́ю под'я́тия, ї́хже ра́ди ди́вно просла́ви тя Госпо́дь, оби́льния ісціле́ній струї́ тобо́ю істоча́я нам, да ви́ну поє́м Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшая в сокруше́ннім се́рдці твоє́м благода́ть Всесвята́го Ду́ха, прови́дця бу́дущих, і ско́раго наве́туємим от бісо́в свободи́теля показа́ тя, преподо́бне, науча́я всіх вопи́ти тебі́ си́це:","Ра́дуйся, пре́дняя, я́ко настоя́щая прорека́вий;","ра́дуйся, да́льная, я́ко близ су́щая прозира́вий.","Ра́дуйся, я́ко кня́зю Михаї́лу вину́ разслабле́нія єго́ тіле́снаго об'ясни́л єси́;","ра́дуйся, я́ко му́ченичеськую кончи́ну єму́ і боля́рину єго́ би́ти предвести́л єси́.","Ра́дуйся, со проро́ки просла́вленний;","ра́дуйся, чудотво́рцем сопричи́сленний.","Ра́дуйся, горди́ні дия́волей низложи́телю;","ра́дуйся, бісо́в прогони́телю.","Ра́дуйся, си́лу вра́жию попра́вий;","ра́дуйся, в си́лі Бо́жієй преспіва́вий.","Ра́дуйся, я́ко Ца́рствіє Бо́жиє внутр себі́ стяжа́л єси́;","ра́дуйся, я́ко Христа́ на ві́ки в тебі́ жи́ти восприя́л єси́.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́щу дия́волу явле́нієм свої́м во о́бразі драко́на устраши́ти тя, стоя́ща на моли́тві, ору́жієм креста́ пораже́ніє всеконе́чноє нане́сл єси́, побіди́телю Бо́гу воспіва́я: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую твар показа́ тя Зижди́тель, от миролю́бія к толи́кому боголю́бію се́рдце твоє́ обрати́в, преподо́бне о́тче, я́ко ти на столп, а́ки Ілия́ на о́гненную колесни́цю, возше́д, бді́ніє, пост і моли́тву, а́ки ко́ни бистроте́чния от землі́ к небесі́ стяжа́л єси́, і та́ко ко Христу́ предста́в, ви́ну хода́тайствуєши о нас, вопію́щих тебі́:","Ра́дуйся, я́ко є́же по Бо́зі і́стинноє житіє́ позна́л єси́;","ра́дуйся, я́ко то́є і́щущим діла́ми показа́л єси́.","Ра́дуйся, велему́дров ві́ка сего́ обуї́вий;","ра́дуйся, і́стинную му́дрость в смиренному́дрії би́ти яви́вий.","Ра́дуйся, і́го Христа́ восприя́вий;","ра́дуйся, бла́гость о́наго житіє́м оправда́вий.","Ра́дуйся, я́зви Го́спода Ісу́са любе́зні на ті́лі твоє́м поне́сший;","ра́дуйся, всего́ себе́ в же́ртву Го́сподеві прине́сший.","Ра́дуйся, земни́й стра́нниче;","ра́дуйся, Бо́жий ізбра́нниче.","Ра́дуйся, мона́хов наста́вниче;","ра́дуйся, богоприя́тний о нас моли́твенниче.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до ви́диться всім, притека́ющим к тебі́, о́тче Ники́то, я́ко і вода́ от ізри́тих тобо́ю кладенце́в, че́рплемая с ві́рою, тіле́сния і душе́вния неду́ги ісціля́єть, науча́я чудоді́ющему Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь от Всесвята́го Бо́га облагода́тствован єси́, преподо́бне о́тче, я́ко ду́хом престо́лу Бо́жию предстої́ши, ті́лом же в ні́дрі землі́ почива́я, от гро́ба твоєго́ подає́ши цільби́. Сего́ ра́ди і взива́єм ті такова́я:","Ра́дуйся, ві́рний ра́бе Влади́ки Всеблага́го;","ра́дуйся, хра́мі преукраше́нний Ду́ха Всесвята́го.","Ра́дуйся, Царя́ Небе́снаго предстоя́телю;","ра́дуйся, ско́рий проше́ній пода́телю.","Ра́дуйся, істо́чниче ісціле́ній;","ра́дуйся, сокро́вищнице чудотворе́ній.","Ра́дуйся, ви́димими чудеси́ неви́димую благода́ть, в тебі́ су́щую, явля́яй;","ра́дуйся, ві́рних ду́ші зна́меньми во ві́рі утвержда́я.","Ра́дуйся, ча́дам Це́ркві лучеза́рний світи́льниче;","ра́дуйся, ди́вний Христо́в уго́дниче.","Ра́дуйся, увінча́нний подви́жниче;","ра́дуйся, Бо́гу при́сний люби́миче.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся вели́кому сви́ше тебі́ дарова́нію, преподо́бне Ники́то, я́ко і древ'я́ний по́сох твой, стра́ждущему тіле́сним разслабле́нієм Черни́говському кня́зю Михаї́лу по́сланний от тебе́ і в ру́ку їм прия́тий, а́біє ісціле́ніє тому́ дарова́ і научи́ єго́ пі́ти чудоді́ющему тобо́ю Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоумі́ють по достоя́нію восхвали́ти тя, достосла́вне о́тче, я́ко па́че єстества́ си́лу вра́жию пресла́вно низлага́єши. Єще́ бо в тілесі́ пребива́я, бі́са, ше́ствовавшу к тебі́ кня́зю Михаї́лу я́вльшася во о́бразі і́нока і благо́є кня́же предприя́тіє восп'яща́вша, ви́димо к столпу́ твоєму́ і́менем Христа́ пригвозди́л єси́, і подне́сь ту́южде власть на бі́си явля́єши, разруша́я злоко́зненния ді́йства їх на челові́ков. Сего́ ра́ди і зове́м ті си́це:","Ра́дуйся, лжі дия́волей обличи́телю;","ра́дуйся, пре́лести бісо́вськия посрами́телю.","Ра́дуйся, власть на ду́хи нечи́стия прия́вий;","ра́дуйся, ту́южде і по сме́рті удержа́вий.","Ра́дуйся, я́ко де́мони і гро́ба твоєго́ трепе́щуть;","ра́дуйся, я́ко на них і вери́ги твоя́ стрі́ли паля́щия ме́щуть.","Ра́дуйся, я́ко бі́сния во оби́тель твою́ то́чію ну́ждею привлача́ємі бива́ють;","ра́дуйся, я́ко о́нії здра́ві і сми́слящії ту́ю оставля́ють.","Ра́дуйся, я́ко де́мони зді і не хотя́ще себі́ открива́ють;","ра́дуйся, я́ко тобо́ю гони́ми, із одержи́мих і́ми ско́ро убіга́ють.","Ра́дуйся, ріка́ ісціле́ній бистроте́чная;","ра́дуйся, стра́жа оби́телі ві́чная.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, богому́дре о́тче, в кро́тости і смиренному́дрії Христо́ві ви́ну поуча́лся і ди́вно преуспі́л єси́. Ті́мже і рабо́м твої́м, хотя́щим ну́ждно із'я́ти ду́шу твою́, нічто́же прере́кл, ніже́ возопи́л єси́, но, я́ко а́гнець незло́бивий, главу́ подклони́в, смерть от тіх прия́л єси́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ всім, воспіва́ющим тя і притека́ющим с ві́рою к заступле́нію твоєму́, Ники́то сто́лпниче. Ті́мже і нам, к тебі́ прибега́ющим, бу́ди столп непоколеби́м, от вся́ких нас бід і напа́стей ви́ну застіня́я і огражда́я, за є́же і поє́м тебі́ такова́я:","Ра́дуйся, приста́нище обурева́ємих;","ра́дуйся, по́моще озлобля́ємих.","Ра́дуйся, ско́рбних уті́шителю;","ра́дуйся, немощни́х укріпи́телю.","Ра́дуйся, грі́шним Бо́га умилостивля́яй;","ра́дуйся, благи́х в добрі́ утвержда́яй.","Ра́дуйся, ка́ющихся свої́м приме́ром ободря́яй;","ра́дуйся, о спасе́нії подвиза́ющимся спобора́яй.","Ра́дуйся, м'яту́щихся по́мислами умири́телю;","ра́дуйся, вра́жиїх наві́тов отрази́телю.","Ра́дуйся, на́ших царе́й держа́во і похвало́;","ра́дуйся, гра́да Переясла́вля утвержде́ніє і красото́.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє Го́споду прино́сять всі, приє́млющії, ви́дящії і сли́шащії многочи́сленная чудеса́, от тя́жких вери́г і гро́ба твоєго́ бива́ющая си́лою Бо́жиєю, ю́же ти ви́ну на небесі́х прославля́єши, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє світи́ло, на тве́рди церко́вній возсія́вшеє, преподо́бне о́тче Ники́то, показа́ша тя три огневи́дния столпи́, я́вльшіяся над пове́рженними от уби́йць твої́х і я́ко дре́во во вода́х Во́лжських пла́вавшими твої́ми вери́гами, я́же і положи́ти зді на гро́бі твоє́м, я́ко по́честь трудо́в твої́х, в нощні́м виді́нії повелі́л єси́. Чесо́ ра́ди твоє́ водворе́ніє во сві́тлостіх святи́х би́ти уразумі́вше, тя воспіва́єм:","Ра́дуйся, жи́телю Боже́ственнаго селе́нія;","ра́дуйся, дости́гшій ві́чнаго упокоє́нія.","Ра́дуйся, благ неізрече́нних наслажда́ющийся;","ра́дуйся, лицезрі́нія Бо́жия насища́ющийся.","Ра́дуйся, со а́нгели при́сно лику́ющий;","ра́дуйся, трисвяту́ю піснь немо́лчно пою́щий.","Ра́дуйся, с преподо́бними ублажа́ємий;","ра́дуйся, с му́чениками увенчава́ємий.","Ра́дуйся, ра́достію ві́чною преісполня́ємий;","ра́дуйся, любо́вію Боже́ственною преуслажда́ємий.","Ра́дуйся, я́ко тобо́ю Ви́шній на небесі́ і на землі́ сла́виться;","ра́дуйся, я́ко і ти сего́ ра́ди Ви́шнім на небесі́ і на землі́ просла́вися.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть чуде́с твої́х, преподо́бне о́тче Ники́то, в се́рдці первосвяти́теля Фо́тія ве́ліє ко отиска́нію многоціле́бних моще́й твої́х жела́ніє возжже́. Ти же, богому́дре, а́ще і попусти́л єси́ откопа́ти і ви́діти нетлі́нноє і чудеси́ благоуха́ющеє ті́ло твоє́; оба́че я́коже і пре́жде челові́чеськія сла́ви убега́вший, всіх із хра́ма, а́ки бу́рею, ізри́нув, па́ки себі́ в зе́млю скрил єси́. Чесо́ ра́ди ди́вному во святи́х Свої́х Бо́гу Іа́ковлю воспіва́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пресла́вно ді́йствующаго тобо́ю чудеса́ Царя́ Небе́снаго, тя, о́тче достосла́вне, восхваля́єм, а́ще і недосто́йними уста́ми, оба́че усе́рдно ублажа́я тя си́це:","Ра́дуйся, честно́є Пресвяти́я Тро́йці носи́ло і похвале́ніє;","ра́дуйся, святи́ні Ду́ха чи́стоє і непоро́чноє селе́ніє.","Ра́дуйся, чуде́с пучи́но, Бо́гом ізлія́нная;","ра́дуйся, мирова́рнице, на вся неду́ги врачева́ніями преізоби́льная.","Ра́дуйся, о́бразе а́гнцем і па́стирем;","ра́дуйся, преукраше́нний вся́ким Боже́ственним дарова́нієм.","Ра́дуйся, пра́вило ві́ри і о́бразе кро́тости духо́вния;","ра́дуйся, зри́телю красоти́ Боже́ственния неізрече́нния.","Ра́дуйся, ми́ра Христо́ва благоуха́ніє;","ра́дуйся, многоцве́тний кри́не ра́йськаго прозябе́нія.","Ра́дуйся, я́ко а́нгели о твої́х ісправле́ніїх ра́дуються;","ра́дуйся, я́ко мно́зі челові́ци по твоєму́ примі́ру і предста́тельству спаса́ються.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 13","ps":["О, пресла́вний чудотво́рче і вели́кий Христо́в уго́дниче, а́вво Ники́то преподобному́чениче! Ни́нішнєє на́ше хвале́бноє приноше́ніє приє́мши, не оста́ви при́сно хода́тайствовати о нас у Отця́ Небе́снаго, да в житії́ сем сіте́й вра́жиїх і пре́лести бісо́вськия ізби́вше, возду́шних мита́рств і геє́нни всі ізбі́гнем, і все́льшеся в го́рній Ієрусали́м, сподо́бимся с тобо́ю пі́ти Всеблаго́му Бо́гу на́шему ві́чно немо́лчноє: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов подо́бника і бісо́в противобо́рця, прови́дя тя всея́ тва́рі Зижди́тель, словеси́ проро́чеськими, — «ізми́йтеся і чи́сти бу́діте», — на покая́ніє огласи́в тя, я́ко втора́го Па́вла, человіколю́бно к Себі́ призва́, нас же научи́ ублажа́ти тебі́ си́це:","Ра́дуйся, сосу́де ізбра́нний, сви́ше Бо́гом предуве́данний;","ра́дуйся, в храм Ду́ха Всесвята́го предуста́вленний.","Ра́дуйся, сподо́бивийся Боже́ственнаго призва́нія;","ра́дуйся, удосто́ївийся от Го́спода оправда́нія.","Ра́дуйся, благода́ть Бо́жию, ум'ягча́ющую се́рдце твоє́, получи́вий;","ра́дуйся, очисти́тельнаго покая́нія то́ки слез істочи́вий.","Ра́дуйся, ві́ру в призва́вшаго тя Го́спода несумне́нну восприя́вий;","ра́дуйся, всего́ себе́ води́тельству Бо́жию преда́вий.","Ра́дуйся, супру́жницю і клевре́тов твої́х Го́спода ра́ди оста́вивий;","ра́дуйся, невозвра́тноє твоє́ ше́ствіє к сниска́нію спасе́нія напра́вивий.","Ра́дуйся, Ца́рствія небе́снаго стяжа́телю;","ра́дуйся, о всіх к тебі́ притека́ющих те́плий ко Го́споду предста́телю.","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Кондак 1","ps":["Взбра́нний чудотво́рче і вели́кий Христо́в уго́дниче! Восхваля́єм тя с любо́вію, ча́да твоя́, те́пла предста́теля к Бо́гу тебі́ стяжа́вше. Ти же моли́ просла́вившаго тя Го́спода от вся́ких нам бід свободи́тися, зову́щим:","Ра́дуйся, Ники́то преподо́бне, сто́лпниче і чудотво́рче."]},{"h":"Молитва","ps":["О, всечестна́я главо́, преподо́бне о́тче преблаже́нне, вели́кий а́вво Ники́то преподобному́чениче! Не забу́ди ни́щих твої́х до конця́, но помина́й нас всегда́ во святи́х свої́х і благоприя́тних моли́твах к Бо́гу, і не забу́ди присіща́ти чад свої́х. Моли́ за ни, о́тче благи́й і ізбра́нниче Христо́в, я́ко імі́яй дерзнове́ніє к небе́сному Царю́, і не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних, у престо́ла Вседержи́телева і не преста́й моля́ся за нас ко Христу́ Бо́гу, тебі́ бо дана́ бисть благода́ть моли́тися за ни. Не мним бо тя ме́ртва су́ща, а́ще бо і ті́лом преста́вился єси́ от нас, но і по сме́рті у́бо жив пребива́єши. Не отступа́й от нас ду́хом, сохраня́я і соблюда́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия, засту́пниче і моли́твенниче наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с небе́сними си́лами у престо́ла Вседержи́теля Бо́га в лі́поту досто́йно весели́ться. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм, і тебі́ мо́лимся, і ми́лі ся ді́єм, є́же моли́тися о нас Всеси́льному Бо́гу о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє і невозбра́нно прейти́ от землі́ на не́бо, і го́рких мита́рств, і возду́шних князе́й, і ві́чния му́ки ізба́витися нам, і небе́сному Ца́рствію наслі́дником би́ти со всі́ми пра́ведними, от ві́ка угоди́вшими Єму́, Го́споду на́шему Ісу́су Христу́. Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Правосла́вним сми́слом ю́ношськая возжелі́нія возненави́дів / і до́блественния нра́ви восприї́м, врага́ побіди́л єси́, / і во благоразу́мії Бо́гу угоди́л єси́, / і сви́ше от Него́ приє́м дар чуде́с, / бі́си прогоня́ти, неду́ги ісціля́ти, / Ники́то пресла́вне, // моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Інший тропар, глас 4","ps":["Христо́ву му́ченику тезоімени́ть бил єси́, преподо́бне, / мно́гі по́двиги і труди́ претерпі́л єси́ Христа́ ра́ди, / Єго́же ра́ди вери́ги носи́л єси́, блаже́нне, / Того́ ни́ні о нас моли́, Ники́то преподо́бне, / душе́вния на́ша і тіле́сния стра́сті уврачева́ти, / і́же ві́рою і любо́вію // почита́ющих при́сно па́м'ять твою́."]},{"h":"Кондак, глас 8","ps":["Христа́ ра́ди от твої́х рабо́в ну́ждную смерть претерпі́л єси́ / і віне́ць нетлі́нія от Него́ восприя́л єси́, / приходя́щим же с ві́рою от честна́го твоєго́ гро́ба подає́ши цільби́, / о Ники́то преподо́бне, // моли́твенниче о душа́х на́ших."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Ники́то, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святому пророку Божому Іллі","e":"Akathist to the Holy Prophet of God Elijah","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом на обраще́ніє Ізра́їля от пре́лести Вая́лови, гро́зний обличи́телю царе́й законопресту́пних, просія́вий пла́менною ре́вностію по Бо́зі Вседержи́тели, свя́тостію жи́зні і чудеси́, восхище́нний с пло́тію твоє́ю на Небеса́ і предити́ імі́яй Второ́му прише́ствію Христо́ву, похва́льная воспису́єм ті, проро́че Бо́жий Іліє́; ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас зол і обстоя́ній моли́твами твої́ми свобожда́й, благоче́стно тебі́ вопію́щих:","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Ікос 1","ps":["А́нгел ре́вностію по Бо́зі і чи́стим житіє́м твої́м, сий во пло́ті, проро́че, бил єси́: єще́ бо младе́нцю ті би́вшу оте́ць твой Сова́х ви́ді сві́тлия А́нгели, бесе́дующия с тобо́ю, огне́м тя повива́ющия і пла́менем пита́ющия, є́же прознаменова́ше пла́менную ре́вность твою́ по Бо́зі, си́лу слове́с твої́х і житіє́, я́ко світ, непоро́чноє. Сего́ ра́ди со удивле́нієм зове́м ті такова́я:","Ра́дуйся, от ві́чності предизбра́нний в служе́ніє спасе́нію сино́в Ізра́їлевих;","ра́дуйся, от чре́ва ма́терня предугото́ванний в провозві́стника Боже́ственния і́стини і благоче́стія.","Ра́дуйся, пресла́вним, би́вшим на тебі́, виді́нієм роди́теля твоєго́ удиви́вий;","ра́дуйся, ді́вственную чистоту́ і безмо́лвіє от ю́ности возлюби́вий.","Ра́дуйся, суєту́ ми́ра сего́ і вся бла́га єго́ презрі́вий, ду́шу же твою́ всеці́ло Го́споду посвяти́вий;","ра́дуйся, сві́том прему́дрости от Бо́га озаре́нний і уче́нієм благоче́стія ізді́тства напоє́нний.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 2","ps":["Ви́дя нече́стіє і развраще́ніє во Ізра́їлі, пресла́вний проро́че, зіло́ ду́хом твої́м скорбі́л єси́ і ре́вностію по сла́ві Бо́жієй воспламеня́лся єси́; я́ко си́нове Ізра́їлеви ме́рзьким і́долом поклони́шася, от Бо́га же І́стиннаго отступи́ша, Єму́же вся небе́сная во́їнства со стра́хом вопію́ть: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум свой зло́ю во́лею омрачи́в, беззако́нний цар ізра́їльський Аха́в, оста́ви І́стиннаго Бо́га Вседержи́теля і покланя́шеся ме́рзькому і́долу Ваа́лу, ку́пно же і в ца́рстві своє́м умно́жи ідолопоклоне́ніє і нече́стіє. Ти же, проро́че, іспо́лнен сий ве́лія ре́вности по Бо́зі, дерзнове́нно обличи́л єси́ царя́, возвісти́в єму́, я́ко в наказа́ніє єму́ і ца́рства єго́ три лі́та і мі́сяць шесть не бу́деть дождь, ні роса́, і глад ве́лій бу́деть по всей землі́. Див'я́шеся у́бо толи́цій ре́вности твоє́й по Бо́зі і ве́лію дерзнове́нію, с любо́вію зове́м ті:","Ра́дуйся, небоя́зненний пропові́дниче і́стини і крі́пкий побо́рниче благоче́стія;","ра́дуйся, ре́вностний нече́стія обличи́телю.","Ра́дуйся, к наказа́нію нека́ющихся грі́шников долготерпіли́ваго Бо́га преклони́вий;","ра́дуйся, сло́вом твої́м не́бо заключи́вий і плодоно́сную зе́млю непло́дну сотвори́вий.","Ра́дуйся, трилі́тний глад за нече́стіє люді́й от Го́спода іспроси́вий;","ра́дуйся, я́ко Всеви́шній Госпо́дь дарова́ тебі́ в Бо́га Аха́ву, я́коже дре́вле Моїсе́я фарао́ну.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 3","ps":["Си́лою моли́тви твоєя́, преди́вний проро́че, воі́стину заключи́ся не́бо і не одожди́ три лі́та і мі́сяць шесть, і бисть глад ве́лій по всей землі́: да поне́ зно́єм і гла́дом томи́ми, нечести́вії лю́діє пока́ються і обратя́ться ко Го́споду, со умиле́нієм зову́ще Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ве́ліє благоволе́ніє к тебі́, проро́че, Госпо́дь восхоті́ отлучи́ти тя от беззако́нних сино́в Ізра́їля, да не с ни́ми те́рпиши глад і жа́жду, і повелі́ тебі́ іти́ к пото́ку Хора́фову, іді́же вра́нове пита́ху тя, принося́ще хліб і м'я́со. Ті́мже прино́сим тебі́ похва́льная сія́:","Ра́дуйся, посто́м і бді́нієм вся земна́я і су́єтная помишле́нія істреби́вий;","ра́дуйся, моли́твою і богоми́слієм ум твой в го́рняя впери́вий.","Ра́дуйся, патріа́рхов велича́ніє і проро́ков красото́;","ра́дуйся, ді́вственников похвало́ і преподо́бних сла́во.","Ра́дуйся, святи́телей наста́вниче і му́чеников крі́посте;","ра́дуйся, я́ко нече́стієм і неві́рієм осліпле́нних сино́в Ізра́їлевих на путь і́стини обрати́л єси́.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 4","ps":["Бу́ря ве́лія, разруша́ющая го́ри, предидя́ше, єгда́ прибли́жашеся к тебі́, проро́че, в Хори́ві Госпо́дь, та́же яви́ся трус, і не в тру́сі Госпо́дь, і по тру́сі огнь, і не во огні́ Госпо́дь, а по огні́ бисть глас хла́да то́нка, і ту яви́ся тебі́ Госпо́дь, Єго́же прису́тствіє ощути́в, покри́л єси́ лице́ твоє́ ми́лотію, со стра́хом і ра́достію зови́й Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав нечести́вий цар Аха́в повелі́ніє твоє́, о є́же собра́ти вся колі́на Ізра́їлева на го́ру Карми́льськую, і привести́ на ту сту́дния проро́ки Ваа́лови, а́біє посла́в, собра́ вся, і сам приї́де та́мо. Ти же, ревни́телю сла́ви Бо́жия, хотя́ коне́чні посрами́ти ме́рзькия і́доли і просла́вити І́стиннаго Бо́га, повелі́л єси́ угото́вати дві же́ртві, огня́ же на ти́я не возгнеща́ти, рек: «І бу́деть Бог, І́же послу́шаєть огне́м, Той єсть Бог». То сли́шавше всі лю́діє, рі́ша: «Добр глаго́л Ілії́н, да бу́деть та́ко». Ми же, велича́юще тя, зове́м:","Ра́дуйся, вели́кий посла́нниче Царя́ Небе́снаго і провозві́стниче святи́х велі́ній Єго́;","ра́дуйся, адама́нте, неодоли́мий в ре́вности і непоколеби́мий сто́лпе благоче́стія.","Ра́дуйся, си́льний защи́тниче і́стини і тве́рдий противобо́рниче враго́в Бо́жиїх;","ра́дуйся, нече́стія іскорени́телю і насади́телю благоче́стія.","Ра́дуйся, пла́менний ревни́телю Боже́ственния сла́ви;","ра́дуйся, я́ко і в послі́днія дні ми́ра і́маши пропове́довати І́стиннаго Бо́га і облича́ти окая́ннаго анти́христа.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 5","ps":["Боготе́чную тя звізду́ погаси́ти мня́ше беззако́нная цари́ця Ієзаве́ль: іспо́лнившися бо на тя я́рости за погубле́ніє сту́дних єя́ проро́ков, хотя́ше уби́ти тя. Ожесточи́ся бо се́рдце єя́ і не хотя́ше ві́ровати чудесе́м твої́м, проро́че, і позна́ти І́стиннаго Бо́га, пою́щи Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше всі лю́діє Ізра́їлеви, по моли́тві твоє́й, огнь от Го́спода с Небесе́ сше́дий на же́ртву твою́, всехва́льне проро́че, і всю ю поже́гший, дрова́ же, і ка́мень, і персть, і во́ду потреби́вий, падо́ша на ли́ця своя́, взива́юще: «Воі́стину Госпо́дь Бог, Той єсть Бог». І ві́роваша лю́діє Бо́гові, сту́дния же проро́ки ти закла́л єси́. Сла́в'яще у́бо Всеси́льнаго чудоде́ющаго Бо́га, тебе́, уго́днику Єго́, глаго́лем си́це:","Ра́дуйся, преве́ліє дерзнове́ніє ко Влади́ці вся́чеських стяжа́вий;","ра́дуйся, зна́менії і чудеси́ Боже́ственную І́стину утверди́вий.","Ра́дуйся, пре́лесть де́монськую посрами́вий, і́стинную же ві́ру просла́вивий;","ра́дуйся, неві́рния і́стинним богові́дінієм просвіти́вий.","Ра́дуйся, трикра́тним лія́нієм на же́ртвенник води́ та́йну Пресвяти́я Тро́йці яви́вий;","ра́дуйся, я́ко все єстество́ су́щих тебі́ повинова́ся, огнь же і вода́ тебі́ служа́ху.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 6","ps":["Пропові́дник і́стиннаго богові́дінія і благоче́стія яви́лся єси́, проро́че, не то́кмо во Ізра́їлі, но і в страні́ язи́честій, по́слан бив от Го́спода в Саре́пту Сидо́нськую к жені́ вдови́ці препита́тися, па́че же да саму́ ту препита́єши в гла́ді: імі́я бо ве́лію чудотворе́нія благода́ть, умно́жил єси́ муку́ і єле́й в дому́ єя́ неоску́дно, до́ндеже пре́йде гла́дноє вре́м'я, і трикра́тним дунове́нієм, по моли́тві твоє́й, воскреси́л єси́ уме́ршаго си́на єя́, поя́ чудоді́ющему Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́во ве́лією ре́вностію по Бо́зі Вседержи́тели, зіло́ скорбі́л єси́, проро́че, я́ко оста́виша заві́т Єго́ си́нове Ізра́їлеви, олтари́ Єго́ раскопа́ша і проро́ки ізби́ша. Госпо́дь же во утіше́ніє твоє́ возвісти́ тебі́, я́ко не весь Ізра́їль отступи́ от Него́, но і́мать седьм ти́сящ сокрове́нних рабо́в Свої́х, і́же не преклони́ша колі́на своя́ Ваа́лу. Ті́мже, воспомина́юще ре́вность твою́ по Бо́зі, поє́м ті с благогові́нієм сицева́я:","Ра́дуйся, ві́рний служи́телю і бли́жній дру́же Госпо́день;","ра́дуйся, о́бразе і похвало́ благочести́вих па́стирей.","Ра́дуйся, наста́вниче спасе́нія і просвіще́ніє во тьмі сідя́щих;","ра́дуйся, защи́тником і́стини му́жество внуша́яй, в по́двизіх же і страда́ніїх за пра́вду їх укріпля́яй.","Ра́дуйся, я́ко серафи́мською пла́менною любо́вію к Бо́гу горі́л єси́;","ра́дуйся, я́ко і Госпо́дь во всем послу́шаше тебі́ і по проше́нію твоєму́ вся творя́ше.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь яви́ти милосе́рдіє Своє́ ка́ющимся грі́шником, по преше́ствії прорече́ннаго гла́днаго вре́мене, низпосла́ по моли́тві твоє́й, проро́че, і глаго́лом уст твої́х, на жа́ждущую зе́млю оби́льний і ми́рний дождь: си́нове же Ізра́їлеви, сподо́бльшіїся толи́кия ми́лости, во умиле́нії се́рдця благода́рственно возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє нечести́вий цар Аха́в к беззако́нієм свої́м приложи́ злодія́ніє, єгда́ повелі́ уби́ти непови́ннаго Навуфе́я і восхи́ти виногра́д єго́. Сего́ ра́ди, облича́я законопресту́пнаго царя́, проре́кл єси́ єму́, проро́че, я́ко іді́же умерщвле́н бисть Навуфе́й, та́мо і єго́ кров свинії́ і пси поли́жуть, і жену́ єго́ Ієзаве́ль снідя́ть пси, і весь дом єго́ істреби́ться. Ві́дуще у́бо ми сби́вшеєся стра́шноє сіє́ прорече́ніє, ужаса́ємся, зову́ще:","Ра́дуйся, оби́дящих і жестокосе́рдних гро́зний отмсти́телю;","ра́дуйся, си́рих і напа́ствуємих крі́пкий засту́пниче.","Ра́дуйся, не почита́ющих святи́х пра́здников Правосла́вния Це́ркве кара́телю;","ра́дуйся, проде́рзих ху́льников І́мене Бо́жия низложи́телю.","Ра́дуйся, сло́вом обличе́нія, я́ко гро́мом, беззако́нния поража́яй;","ра́дуйся, бу́дущая, я́ко настоя́щая, ві́дий і да́льняя, я́ко близ су́щая, прориця́яй.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 8","ps":["Стра́нноє і преєсте́ственноє показа́ Госпо́дь о тебі́, проро́че, промишле́ніє, єгда́ повелі́ а́лчним і нечадолюби́вим вра́ном пита́ти тя в гла́ді при пото́ці Хора́фові, іді́же непреста́нно пребива́я в моли́тві і богоми́слії, воспіва́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ смире́нієм ве́ліїм укра́шен, проро́че Бо́жий, сего́ ра́ди с го́рдостію прише́дших к тебі́ двух п'ятдесятонача́льников с во́їни, да приведу́ть тебе́ к беззако́нному царю́ Охо́зії, огне́м попали́л єси́, со смире́нієм же прише́дшаго к тебі́ А́вдія, і́же пита́ше ученики́ проро́чеськия, поми́ловал єси́. Сего́ ра́ди прино́сим ті похва́льния пі́сні сія́:","Ра́дуйся, го́рдих смири́телю і кара́телю, смире́нних же покро́ве і засту́пниче;","ра́дуйся, мздої́мних суде́й наказа́телю, пра́во же судя́щим помо́щниче.","Ра́дуйся, правові́рному во́їнству во бра́ніх спобо́рниче, нечести́вих же супоста́ть низложи́телю;","ра́дуйся, прему́дростію, я́ко броне́ю, облече́нний і пра́вдою, я́ко щито́м, огражде́нний.","Ра́дуйся, ре́вностію по Бо́зі я́ко мече́м вооруже́нний і посто́м, я́ко крила́ми, окриле́нний;","ра́дуйся, ві́рою, я́ко шле́мом спасе́нія, покрове́нний і любо́вію, я́ко вінце́м пресві́тлим, вінча́нний.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 9","ps":["Вся́коє челові́чеськоє єстество́ зіло́ удивля́ється, ка́ко ти, пречу́дний проро́че, шел єси́ чети́редесять дній, ні яди́й, ні пія́й, до гори́ Хори́ва, іді́же сподо́бился єси́ пресла́внаго явле́нія і пресла́дкия бесі́ди Го́спода Вседержи́теля, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния недоумі́ють дово́льно разумі́ти і із'ясни́ти, ка́ко ти, великоімени́те Іліє́, во пло́ті сий челові́честій і подобостра́стен нам бив, восхи́щен єси́ с ті́лом твої́м на не́бо, я́вльшейся тебі́ колесни́це о́гненній с ко́ни о́гненними. Сла́в'яще у́бо просла́вльшаго тя Го́спода і див'я́щеся восхище́нію твоєму́, благогові́йно зове́м ті:","Ра́дуйся, пречу́дним воздержа́нієм ве́тхаго челові́ка в себі́ умертви́вий;","ра́дуйся, огне́м Боже́ственния ре́вности вся́коє веще́ственноє помишле́ніє в себі́ попали́вий.","Ра́дуйся, преложе́нієм твої́м на Не́бо род челові́чеський возвесели́вий і жизнь ві́чную уві́ривий;","ра́дуйся, че́стію і сла́вою преєсте́ственною от Бо́га почте́нний і па́че всіх дре́вніх проро́ков просла́вленний.","Ра́дуйся, от а́нгельських лико́во в селе́ніїх небе́сних ра́достно сре́тенний;","ра́дуйся, я́ко і́м'я твоє́ во всем ми́рі почита́ється, і ре́вность твоя́ по Бо́зі зіло́ прославля́ється.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ Всеблаги́й Бог лю́ди Ізра́їлеви от пре́лести Вая́лови, ізбра́ тя, вели́кий проро́че, во ору́діє во́лі Своєя́ і облече́ тя Боже́ственною вла́стію і си́лою, да обрати́ши неві́рния, іспра́виши беззако́нния, просвіти́ши омраче́нния і научи́ши всіх вопи́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і заступле́ніє бу́ди нам, пресвя́те проро́че, мо́щним твої́м хода́тайством утоля́я пра́ведний гнів Бо́жий, поража́ющий нас, грі́шних і непотре́бних, бездо́ждієм і гла́дом, єще́ же тлетво́рними ві́три і болі́зньми, да ізба́вльшеся от бід, благода́рственно поє́м тя:","Ра́дуйся, моли́твами твої́ми не́бо заключа́яй і отверза́яй, плодоно́сіє землі́ і непло́діє от Бо́га посила́яй;","ра́дуйся, предста́тельством твої́м пред Бо́гом дожді́ ми́рни і ро́су животво́рную на земна́я прозябе́нія низводя́й.","Ра́дуйся, свирі́пия во́лни морськи́я і стра́шния бу́ри утиша́яй і гро́мами і мо́лніями по во́лі Бо́жієй управля́яй;","ра́дуйся, тлетво́рния ві́три і смертоно́сния я́зви, поража́ющия челові́ки же і скоти́, укроща́яй.","Ра́дуйся, си́рих і вдови́ць пита́телю і щедрода́тельних люді́й покрови́телю;","ра́дуйся, я́ко нечести́вих ху́льников і гони́телей пра́вия ві́ри поража́єши і духо́в зло́би от рабо́в Бо́жиїх прогоня́єши.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прийми́ от нас, проро́че Бо́жий Іліє́, я́коже прия́л єси́ проше́ніє Єлисе́єво, єгда́ проси́ от тебе́, да бу́деть дух, і́же в тебі́, сугу́б в нем, і єгда́, восхища́яся на Не́бо, низпусти́л єси́ єму́ ми́лоть твою́, ю́же он взем, разділи́, я́коже і ти пре́жде, Іорда́нськия во́ди, і бисть наслі́дник де́йствовавшия в тебі́ Бо́жия благода́ті: си́це і нас покри́й ми́лотію твоєя́ ми́лости от вся́ких бід і обстоя́ній, да со благодаре́нієм зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє світи́ло во Ізра́їлі, всехва́льне проро́че, бил єси́, сія́я равноа́нгельним житіє́м твої́м і му́дростію, єще́ же необи́чною ре́вностію по Бо́зі і чудеси́ пресла́вними, просвіща́я лю́ди і́стинним богові́дінієм і разгоня́я мрак ідолослуже́нія. Ті́мже воспису́єм ті похва́льная, пою́ще:","Ра́дуйся, лучеза́рная звіздо́, сія́нієм свої́м озари́вшая всю вселе́нную;","ра́дуйся, світоно́сная свіще́, непреста́нно горя́щая і во тьмі сідя́щих просвіща́ющая.","Ра́дуйся, ду́хом прему́дрості і ра́зума озаре́нний, ду́хом сові́та і крі́пости іспо́лненний;","ра́дуйся, ду́хом ві́дінія і благоче́стія просвіще́нний і ду́хом стра́ха Бо́жия напоє́нний.","Ра́дуйся, висо́кими доброді́тельми і пресла́вними чудеси́ преукраше́нний;","ра́дуйся, я́ко суди́ Бо́жия на землі́ ісполня́л єси́, проро́ки же і цари́ пома́зивал єси́.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 12","ps":["Благода́ть ве́лія дана́ ті бисть от Бо́га, прехва́льне проро́че, я́ко в земні́й жи́зні твоє́й проро́чествовал і соверша́л єси́ ди́вная чудеса́, та́же преєсте́ственно восхи́щен бил єси́ с пло́тію твоє́ю на не́бо: по восхище́нії же твоє́м ди́вно предста́л єси́ на Фаво́рі Преобрази́вшемуся Го́споду і с ним бесі́довал єси́, і додне́сь не престає́ши чудоді́йствовати і істоча́ти ми́лості і ізціле́нія усе́рдно почита́ющим тя, Бо́гу же ві́рно вопію́щим: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твою́ пла́менную ре́вность по Бо́зі і равноа́нгельноє житіє́, ди́вная же твоя́ і пресла́вная чудеса́ і преве́ліє благоволе́ніє к тебі́ Го́спода, восхваля́єм тя, великоімени́те проро́че Іліє́; оба́че не могу́ще досто́йно ізобрази́ти вели́чіє і сла́ву твою́, со умиле́нієм зове́м ті сицева́я:","Ра́дуйся, ковче́же Боже́ственния сла́ви і всечестни́й хра́мі Пресвяти́я Тро́йці;","ра́дуйся, світи́льниче невече́рній церкве́й і благово́нний цві́те рая́ Боже́ственнаго.","Ра́дуйся, благочести́вих пусти́нников руководи́телю, ді́вственников же наста́вниче і укріпле́ніє;","ра́дуйся, я́ко грі́шников к покая́нію возбужда́єши і всему́ ро́ду христия́нському жизнь ві́чную хода́тайствуєши.","Ра́дуйся, я́ко во сві́тлостіх святи́х неізре́ченния сла́ви наслажда́єшися і непреста́нно Го́спода славосло́виши;","ра́дуйся, я́ко в конці́ време́н ве́лія зна́менія і чудеса́ і́маши соверши́ти на утвержде́ніє люді́й во і́стинній ві́рі і на обличе́ніє анти́христа.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 13","ps":["О преди́вний і пресла́вний проро́че Бо́жий Іліє́, преве́лій ревни́телю по Бо́зі, дожди́ і бездо́жіє, плодоно́сіє на зе́млю і непло́діє от Бо́га посила́яй! Усли́ши сіє́ ма́лоє, благогові́йно приноси́моє тебе́ на́ми моле́ніє і твої́м те́плим ко Го́споду предста́тельством сохрани́ нас от бездо́ждія, гла́да і смертоно́сних болі́зней, пода́ждь же нам благорастворе́ніє возду́ха і плодоно́сіє, і дух пра́вия ві́ри і благоче́стія, да ізба́вльшеся от ві́чних мук, сподо́бимся ра́йськаго блаже́нства, пою́ще Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел ре́вностію по Бо́зі і чи́стим житіє́м твої́м, сий во пло́ті, проро́че, бил єси́: єще́ бо младе́нцю ті би́вшу оте́ць твой Сова́х ви́ді сві́тлия А́нгели, бесе́дующия с тобо́ю, огне́м тя повива́ющия і пла́менем пита́ющия, є́же прознаменова́ше пла́менную ре́вность твою́ по Бо́зі, си́лу слове́с твої́х і житіє́, я́ко світ, непоро́чноє. Сего́ ра́ди со удивле́нієм зове́м ті такова́я:","Ра́дуйся, от ві́чності предизбра́нний в служе́ніє спасе́нію сино́в Ізра́їлевих;","ра́дуйся, от чре́ва ма́терня предугото́ванний в провозві́стника Боже́ственния і́стини і благоче́стія.","Ра́дуйся, пресла́вним, би́вшим на тебі́, виді́нієм роди́теля твоєго́ удиви́вий;","ра́дуйся, ді́вственную чистоту́ і безмо́лвіє от ю́ности возлюби́вий.","Ра́дуйся, суєту́ ми́ра сего́ і вся бла́га єго́ презрі́вий, ду́шу же твою́ всеці́ло Го́споду посвяти́вий;","ра́дуйся, сві́том прему́дрости от Бо́га озаре́нний і уче́нієм благоче́стія ізді́тства напоє́нний.","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом на обраще́ніє Ізра́їля от пре́лести Вая́лови, гро́зний обличи́телю царе́й законопресту́пних, просія́вий пла́менною ре́вностію по Бо́зі Вседержи́тели, свя́тостію жи́зні і чудеси́, восхище́нний с пло́тію твоє́ю на Небеса́ і предити́ імі́яй Второ́му прише́ствію Христо́ву, похва́льная воспису́єм ті, проро́че Бо́жий Іліє́; ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас зол і обстоя́ній моли́твами твої́ми свобожда́й, благоче́стно тебі́ вопію́щих:","Ра́дуйся, Іліє́, вели́кий проро́че, Втора́го прише́ствія Христо́ва сла́вний предте́че."]},{"h":"Молитва","ps":["О прехва́льний і пречу́дний проро́че Бо́жий Іліє́, просія́вий на землі́ равноа́нгельним житіє́м твої́м, пла́меннейшею ре́вностію по Го́споді Бо́зі Вседержи́теле, єще́ же зна́менії і чудеси́ пресла́вними, та́же, по кра́йнему благоволе́нію к тебі́ Бо́жию, преєсте́ственно восхище́нний на о́гненній колесни́це с пло́тію твоє́ю на Не́бо, сподо́бивийся бесі́довати с Преобрази́вшимся на Фаво́рі Спаси́телем ми́ра і ни́ні в ра́йських селе́ніїх ви́ну пребива́яй і предстоя́й Престо́лу Небе́снаго Царя́! Усли́ши нас, грі́шних і непотре́бних, в час сей предстоя́щих пред свято́ю твоє́ю іко́ною і усе́рдно прибіга́ющих ко хода́тайству твоєму́. Моли́ о нас Человіколю́бця Бо́га, да пода́сть нам дух покая́нія і сокруше́нія о грісі́х на́ших і всеси́льною Своє́ю благода́тію да помо́жеть нам оста́вити путі́ нече́стія, приспева́ти же во вся́ком ді́лі бла́зі, да укріпи́ть нас в борбі́ со страстьми́ і похотьми́ на́шими; да всади́ть в се́рдці на́ше дух смире́нія і кро́тости, дух братолю́бія і незло́бія, дух терпі́нія і цілому́дрія, дух ре́вности к Сла́ві Бо́жієй і спасе́нію бли́жніх. Упраздни́ моли́твами твої́ми, проро́че, зли́я оби́чаї ми́ра, па́че же поги́бельний і тлетво́рний дух ві́ка сего́, заража́ющий христия́нський род неуваже́нієм к Боже́ственній Правосла́вній ві́рі, к уста́вом Святи́я Це́ркве і к за́повідем Госпо́днім, непочте́нієм к роди́телем і власте́м предержа́щим і низверга́ющий люде́й в бе́здну нече́стія, развраще́нія і поги́белі. Отврати́ от нас, пречу́дне проро́че, предста́тельством твої́м пра́ведний гнів Бо́жий і ізба́ви вся гра́ди і ве́сі от бездо́ждія і гла́да, от стра́шних бур і землетрясе́ній, от смертоно́сних язв і болі́зней, от наше́ствія враго́в і междоусо́бния бра́ні. Іспроси́, проро́че Бо́жий, от Го́спода па́стирем на́шим святу́ю ре́вность по Бо́зі, серде́чноє попече́ніє о спасе́нії пасо́мих, му́дрость в уче́нії і управле́нії, благоче́стіє і крі́пость во іскуше́ніїх, судія́м іспроси́ нелицеприя́тіє і безкори́стіє, правоту́ і сострада́ніє к оби́димим, всім нача́льствующим попече́ніє о подчине́нних, ми́лость і правосу́діє, подчине́нним же поко́рность і послуша́ніє ко власте́м і усе́рдноє ісполне́ніє свої́х об'я́занностей; да, та́ко в ми́рі і благоче́стії пожи́вше в сем ві́ці, сподо́бимся прича́стія ві́чних благ в Ца́рствії Го́спода і Спа́са на́шего Ісу́са Христа́, Єму́же подоба́єть честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва під час безводдя","ps":["О вели́кий і пресла́вний проро́че Бо́жий Іліє́, ре́вности ра́ди твоєя́ по сла́ві Го́спода Бо́га Вседержи́теля не терпі́вий зрі́ти ідолослуже́нія і нече́стія сино́в Ізра́їлевих, облича́вий законопресту́пнаго царя́ Аха́ва і в наказа́ніє тіх триле́тній глад на зе́млю Ізра́їлеву моли́твою твоє́ю от Го́спода іспроси́вий, да, отве́ргше ме́рзькия і́доли і отсту́пльше от непра́вд і беззако́ній, обратя́ться ко Єди́ному І́стинному Бо́гу і ісполне́нію святи́х Єго́ за́повідей, вдови́цю Саре́птськую в гла́ді пречу́дно препита́вий і си́на єя́ уме́рша моли́твою твоє́ю воскреси́вий, по проше́ствії же пронарече́ннаго вре́мене гла́да, собра́нний на го́ру Карми́льськую наро́д ізра́їльський в богоотсту́пстві і нече́стії укори́вий, та́же огнь моли́твою на же́ртву твою́ с небесе́ іспроси́вий і чу́дом сим Ізра́їля ко Го́споду обрати́вий, сту́дния же проро́ки Ваа́лови посрами́вий і умертви́вий, по сих же моли́твою па́ки не́бо разріши́вий і оби́льний дождь на зе́млю іспроси́вий і лю́ди Ізра́їлеви возвесели́вий! К тебі́, преди́вний уго́дниче Бо́жий, усе́рдно прибіга́єм, грі́шнії і смире́ннії, томи́ми бездо́ждієм і зно́єм: іспові́дуєм, я́ко недосто́йни єсьми́ ми́лості і благодія́ній Бо́жиїх, досто́йні же па́че лю́тих преще́ній гні́ва Єго́, ско́рби же і ну́жди і вся́ких зол і болі́зней. Не бо ходи́хом в стра́сі Бо́жії і в путеіх за́повідей Єго́, но в по́хотіх развраще́нних серде́ць на́ших і вся́кий вид гріха́ безчи́сленно сотвори́хом; беззако́нія на́ша превзидо́ша главу́ на́шу, і ні́сми досто́йні яви́тися пред лице́ Бо́жиє і зрі́ти на не́бо. Іспові́дуєм, я́ко і ми, я́коже дре́вній Ізра́їль, отступи́хом от Го́спода Бо́га на́шего, а́ще не ві́рою, то беззако́ньми на́шими, і а́ще не покланя́ємся Ваа́лу і други́м ме́рзьким і́долом, то раболе́пствуєм страсте́м і по́хотем на́шим, служа́ще і́долу чревоуго́дія і сластолю́бія, і́долу користолю́бія і честолю́бія, і́долу го́рдості і тщесла́вія, і вслід хо́дим богопроти́вним іноплеме́нним оби́чаєм і поги́бельному ду́ху вре́мене. Іспові́дуєм, я́ко сего́ ра́ди заключи́ся не́бо і сотвори́ся а́ки мі́дяно, я́ко заключи́ся се́рдце на́ше от милосе́рдія і і́стинния любве́ ко бли́жнему; сего́ ра́ди отверді́ земля́ і соді́лася безпло́дна, я́ко не прино́сим Го́споду на́шему плодо́в до́брих діл; сего́ ра́ди ність дождя́ і ро́си, я́ко не і́мами слез умиле́нія і животво́рний ро́си Богоми́слія; сего́ ра́ди ув'яде́ всяк злак і трава́ се́льная, я́ко і́зсше в нас вся́коє благо́є чу́вство; сего́ ра́ди омрачи́ся возду́х, я́ко ум наш омрачи́ся сту́дними помишле́ньми і се́рдце на́ше оскверни́ся беззако́нними похоті́ньми. Іспові́дуєм, я́ко і тебі́, проро́че Бо́жий, проси́ти ми недосто́йни єсьми́. Ти бо, подобостра́стен бив нам челові́к, А́нгелом в житії́ твоє́м уподо́бился єси́ і, а́ки безпло́тний, на не́бо восхи́щен єси́, ми же сту́дними по́мисли і дія́ньми на́шими безслове́сним ското́м уподо́бихомся і ду́шу на́шу я́ко плоть сотвори́хом. Ти посто́м і бді́нієм удиви́л єси́ А́нгелов і челові́ков, ми же, предаю́щеся невоздержа́нію і сластолю́бію, ското́м несми́сленним уподобля́ємся. Ти презі́льною ре́вностію о сла́ві Бо́жієй ви́ну горі́л єси́, ми же небреже́м о сла́ві на́шего Творця́ і Го́спода і стиді́мся іспові́дивати достопокланя́ємоє І́м'я Єго́. Ти нече́стіє і зли́я оби́чаї іскореня́л єси́, ми же ра́бствуєм ду́ху ві́ка сего́, поставля́юще богопроти́вния оби́чаї ми́ра па́че за́повідей Бо́жиїх і уста́вов Святи́я Це́ркве. І кий гріх і непра́вду не сотвори́хом ми, окая́ннії? Істощи́хом беззако́ньми на́шими долготерпі́ніє Бо́жиє. Ті́мже правосу́дний Госпо́дь прогні́вася на нас і во гні́ві Своє́м наказа́ нас. Оба́че ві́дуще ве́ліє дерзнове́ніє твоє́ пред Го́сподем і наді́ющеся на любо́в твою́ к ро́ду челові́чеському, дерза́єм моли́ти тя, прехва́льне проро́че: ми́лостив бу́ди к нам, недосто́йним і непотре́бним. Умоли́ Великодарови́таго і Всеще́драго Бо́га, да не до конця́ прогні́вається на ни і не погуби́ть нас со беззако́ньми на́шими, но да низпо́слеть на жа́ждущую і ізсо́хшую зе́млю дождь оби́льний і ми́рний, да да́руєть єй плодоно́сіє і благорастворе́ніє возду́ха. Преклони́ ді́йственним твої́м хода́тайством на ми́лость Царя́ Небе́снаго, а́ще не ра́ди нас, грі́шних і скве́рних, но ра́ди ізбра́нних рабо́в Єго́, не преклони́вших колі́на своя́ пред Ваа́лом ми́ра сего́, ра́ди незло́бивих і несми́сленних младе́нцев, ра́ди безслове́сних ското́в і птиць небе́сних, стра́ждущих за на́ша беззако́нія і істаєва́ющих от гла́да, зно́я і жа́жди. Іспроси́ нам твої́ми благоприя́тними моли́твами от Го́спода дух покая́нія і серде́чнаго умиле́нія, дух кро́тости і воздержа́нія, дух любве́ і терпі́нія, дух стра́ха Бо́жия і благоче́стія, да та́ко, возврати́вшеся от стезе́й нече́стія на пра́вий путь доброді́телі, хо́дим во сві́ті за́повідей Бо́жиїх і дости́гнем обітова́нних нам благи́х, благоволе́нієм Безнача́льнаго Бо́га Отця́, человіколю́бієм Єдиноро́днаго Си́на Єго́ і благода́тію Всесвята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Во пло́ті А́нгел, / проро́ков основа́ніє, / втори́й Предте́ча прише́ствія Христо́ва Ілия́ сла́вний, / сви́ше посла́вий Єлисе́єві благода́ть, / неду́ги отгоня́ти / і прокаже́нния очища́ти, // ті́мже і почита́ющим єго́ то́чить ісціле́нія."]},{"h":"Кондак, глас 2","ps":["Проро́че і прови́дче вели́ких діл Бо́га на́шего, / Іліє́ великоімени́те, / віща́нієм твої́м уста́вивий водото́чния о́блаки, // моли́ о нас єди́наго Человіколю́бця."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й сла́вний проро́че Бо́жий Іліє́, / і чтим, є́же на Небеса́ / на колесни́ці о́гненній, // пресла́вноє восхожде́ніє твоє́."]},{"h":"Інше величання","ps":["Велича́єм тя, / проро́че Іліє́ сла́вне, / і почита́єм, є́же на Небеса́ с пло́тію, // о́гненноє восхожде́ніє твоє́."]},{"h":"Інше величання","ps":["Велича́єм тя, / проро́че і предте́че прише́ствія Госпо́дня, Іліє́ сла́вний, / і чтим, є́же на Небеса́ с пло́тію, // о́гненноє восхожде́ніє твоє́."]}],"notes":[]},{"u":"Акафіст святим дев’яти мученикам Кизицьким","e":"Akathist to the Holy Nine Martyrs of Cyzicus","secs":[{"h":"Кондак 1","ps":["Ізбра́нії от Царя́ Сил, Го́спода Ісу́са, страстоте́рпці Христо́ви дев'яточи́сленнії, от разли́чних стран в гра́ді Ки́зиці во єди́но со́браннії і Христа́ дерзнове́нне, мук і сме́рті не убоя́вшеся, іспові́давшії, торжеству́єм духо́вні во святі́м пра́здниці ва́шем і, воспіва́юще благода́тную терпі́нія ва́шего до́блесть, мо́лим вас, во́ї Христо́ви многострада́льнії і утвержде́ннії во во́лі Христо́вой, і нам спасе́нія іспросі́те, зову́щим:","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Ікос 1","ps":["Я́ко А́нгели преми́рнії, возне́сшеся ми́слію от земни́х к небе́сним, ко Христу́, Влади́ці всіх, непреста́нно ві́ри очи́ма взира́юще, му́ченици святі́ї, Феогни́де, Ру́фе, Антипа́тре, Феости́хе, Арте́мо, Ма́гне, Феодо́те, Фавма́сіє, Филимо́не, посреді́ кумирослужи́телей гра́да Кизи́чеськаго іспові́дасте себі́ безбоя́зненно христия́ни би́ти і, си́лою Бо́жиєю укріпля́ємі, мно́гія му́ки му́жественні за Христа́ претерпі́сте і под меч глави́ ва́ша преклони́сте, ті́мже, ублажа́юще страда́нія ва́ша і усікнове́ніє, глаго́лем:","Ра́дуйтеся, земни́я ра́дости презрі́вшії;","Ра́дуйтеся, благ небе́сних возжела́вшії.","Ра́дуйтеся, іспові́дниці Христо́ви непобіди́мії, ві́ру непоро́чну соблю́дшії;","Ра́дуйтеся, стра́сті Христо́ві послі́довавшії і смерть Христо́ву сме́ртію своє́ю подража́вшії.","Ра́дуйтеся, си́лою Воскре́сшаго держа́ву а́дову попра́вшії;","Ра́дуйтеся, душі́ своя́ в ру́ці Бо́жії преда́вшії і побі́дния вінці́ приє́мшії.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 2","ps":["Ви́дяще і́долов полн сущ град Кизи́чеський, ви, о богому́дренноє му́чеников Христо́вих сочета́ніє дев'яточи́сленноє, возмути́стеся ду́хом і, ре́вностію о Бо́зі горя́ще і благода́тію Боже́ственною укріпля́ємі, нача́сте провіщава́ти і учи́ти о і́мені Го́спода Ісу́са, заблужде́ніє і́дольськоє облича́юще; лю́діє же, тьмо́ю неві́рія осліпле́ннії, взя́ша вас а́біє і свя́занних, а́ки злоді́єв, гра́дському в Ки́зиці кня́зю на істяза́ніє предста́виша; ви же ста́сте пред нечести́вим князе́м і, обо́лкшеся во вся ору́жія Бо́жия, я́ко во́їни Христо́ви ві́рнії, ніка́коже отступи́сте от взбра́ннаго Воєво́ди, Го́спода своєго́, взива́юще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́вше, я́ко претерпі́вий до конця́, той спасе́н бу́деть, терпі́нієм теко́сте, страстоте́рпці Христо́ви, на предлежа́щий вам по́двиг, взира́юще на Нача́льника ві́ри і Соверши́теля Ісу́са, і му́ки і терза́нія тіле́с ва́ших претерпі́ли єсте́, ра́дующеся і красу́ющеся ра́нами, я́же под'я́ли єсте́ за любо́в ко Го́споду ва́шему, ті́мже:","Ра́дуйтеся, я́ко Христа́ Го́спода, за ни ду́шу Свою́ на Кресті́ положи́вшаго, і ви, святі́ї му́ченици, взаї́м возлюби́сте;","Ра́дуйтеся, я́ко потща́стеся Тому́ би́ти подо́бни мук терпі́нієм.","Ра́дуйтеся, страда́нія і му́ки в торжество́ ві́ри обрати́вшії;","Ра́дуйтеся, Христа́ ра́ди ізлія́вшимися кро́вію просла́вленнії.","Ра́дуйтеся, я́ко блаже́нна земля́, напоі́вшаяся кро́вію ва́шими;","Ра́дуйтеся, я́ко ду́ші своя́ любо́вію за Христа́ положи́сте.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укрепля́ємії, му́ченици дев'яточи́сленнії преди́внії, не убоя́стеся преще́ній злове́рнаго кня́зя Кизи́чеськаго, ніже́ ко́зней неви́димаго кня́зя ми́ра сего́, но свиде́тельствовасте о Христі́ Ісу́се, усти́ ва́шими іспові́дающе Того́ і́стиннаго би́ти Бо́га, Той бо даде́ вам уста́ і прему́дрость, і́мже не можа́ше что проти́ву отвіща́ти мучи́тель, но посрамля́шеся, і́стиною побіжда́ємий, єще́ же і страда́ньми ва́шими свиде́тельствовасте все ва́ше к Бо́гу жела́ніє, і ужаса́хуся лю́діє, ви́дяще ва́ше до́блественноє терпі́ніє, і познава́ху на вас си́лу і по́мощ всеси́льнаго Бо́га, Єму́же взива́сте: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще в па́м'яті словеса́ Госпо́дня: і влас глави́ ва́шея не поги́бнеть, ві́ровасте та́ко: не то́кмо власи́, Христа́ ра́ди терза́ємії, ці́ли яв'я́ться во сла́ві воскресе́нія, но і са́моє ті́ло, ра́ни і раздробле́ніє за Христа́ претерпе́вшеє, ці́ло воста́неть со сла́вою мно́гою. Сего́ ра́ди, страстоте́рпці Христо́ви досточу́днії, ві́рою укріпля́ємі і о наде́жді сла́ви Бо́жия хва́лящеся, до́броє тече́ніє му́ченичеськаго по́двига соверши́сте і ду́ші своя́ святи́я в ру́ці Бо́га преда́сте, ті́мже і ми возно́сим вам сія́ пі́сненния хвали́:","Ра́дуйтеся, пречу́дноє му́жество яви́вшії;","Ра́дуйтеся, я́ко наде́ждою воскресе́нія Христо́с непобіди́ми вас пред мучи́телі сотвори́.","Ра́дуйтеся, я́ко Христо́с преобрази́ть ті́ло смире́нія ва́шего, во є́же би́ти сему́ сообра́зну ті́лу сла́ви Єго́;","Ра́дуйтеся, ві́чния блаже́нния жи́зні соприча́стници.","Ра́дуйтеся, я́ко со А́нгели піснь побі́дную воспіва́єте.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 4","ps":["Мучи́мий за святу́ю ві́ру во і́м'я Христа́ Го́спода, бу́ря іскуше́ній і бід возшуме́ на тя, Феогни́де, но не возмо́же поколеба́ти хра́мини душі́ твоєя́, основа́на бо бі на Ка́мені, І́же єсть Христо́с, Син Бо́га Жива́го; єгда́ бо приведо́ша тя ко кня́зю гра́дському на суди́щі, тебі́, во свиді́тельство мучи́телем, ні темни́ця, ні жесто́кая біє́нія і ра́ни не отверго́ша от Христа́, но, по земле́ протяже́нний і неща́дно жи́лами біє́мий і ногтьми́ желі́зними стружа́ємий, в страда́нії крі́пок і му́жествен яви́лся єси́, струя́ми же крове́й свої́х, я́ко багряни́цею, оді́явся і серде́чноє о́ко к Бо́гу впери́в, воспіва́л єси́ Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше гро́зноє повелі́ніє влади́ки нечести́ваго, да отве́ргшеся Христа́, же́ртви принесе́те і́долом, ви́дяще же мучи́тельськая ору́дія, угото́ванная на ви, страстоте́рпці достосла́внії, поми́слисте день втора́го прише́ствія на зе́млю Влади́ки Христа́ і нестерпи́мий гнів суда́ Єго́, єгда́ при́йдеть во сла́ві Своє́й с небе́с і всі святі́ї А́нгели с Ним; сего́ ра́ди, во́їни Христо́ви, неодоле́ннії в терпі́нії мно́зі, преда́стеся на ра́ни і му́ки Ца́рствія ра́ди Небе́снаго, приймі́те у́бо от нас хвале́бния пі́сні сія́:","Ра́дуйтеся, пом'яну́вшії словеса́ Госпо́дня: отве́ргшийся Мене́ пред челові́ки, отве́ржен бу́деть пред А́нгели Бо́жиїми;","Ра́дуйтеся, внима́вшії глаго́ланним от Христа́: не убо́йтеся от убива́ющих ті́ло, душі́ же не могу́щих уби́ти, убо́йтеся же па́че могу́щаго і ду́шу, і ті́ло погуби́ти в геє́нні.","Ра́дуйтеся, ре́кшії са́мі себе́: мучи́тельства я́рих челові́к вре́менна суть, му́ки же геє́нськия ві́чни; да ізбу́дем мук ві́чних, вре́менних убоя́тися не і́мами;","Ра́дуйтеся, раби́ Христо́ви, ві́рнії да́же до сме́рти, і́мже возда́сть Госпо́дь віне́ць живота́.","Ра́дуйтеся, я́ко на стра́шнім суди́щі Госпо́дь су́щим одесну́ю сопричте́ть вас і ча́сти возлюби́вших Єго́ сподо́бит;","Ра́дуйтеся, і́мже рече́ть Цар Сла́ви: прийді́те, благослове́ннії Отця́ Моєго́, наслі́дуйте угото́ванноє вам Ца́рствіє от сложе́нія ми́ра.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́, путеводя́щая к Со́лнцю Пра́вди Христу́ Бо́гу, яви́лся єси́, святи́й му́чениче Ру́фе, і сві́том по́двига твоєго́ страда́льчеськаго возсія́л єси́ лю́дем, во тьмі неві́рія сідя́щим, си́ла бо благода́ті Госпо́дні в не́мощі твоє́й соверша́шеся. Сего́ ра́ди, свя́занний по рука́ма і нога́ма, безче́стіє і поруга́ніє претерпі́л єси́, на му́ки дерзну́л єси́ і жи́зні не пощади́л єси́ за Го́спода своєго́, но, же́злієм і бичи́ узла́ти же́стоко біє́н і огне́м опаля́єм, взива́л єси́ к Нему́ велегла́сно: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше себі́ в у́зах стра́ждущия за і́м'я Го́спода Ісу́са Христа́, Єго́же возлюби́сте і в Него́же ві́ровасте, ви, страда́льці Христо́ви дев'яточи́сленнії, Ду́хом Святи́м в ско́рбі ва́шей і тісноті́ темни́чній утіша́ємі, ра́дующеся, друг ко дру́гу глаго́ласте: пло́ті і кро́ві не пощади́м, ста́нем небоя́зненно ко вся́кому муче́нію, у́мрем о Христі́, да во вся ві́ки поживе́м с Ним, лику́юще непреста́нно. Ті́мже, по́двиги ва́ша чу́дния сла́в'яще, восхваля́єм вас си́це:","Ра́дуйтеся, сердця́ ва́ша в ру́ці Бо́жії положи́вшії;","Ра́дуйтеся, благода́ті Свята́го Ду́ха ізбра́нії сосу́ди.","Ра́дуйтеся, прекра́сноє Ду́ха Свята́го жили́ще;","Ра́дуйтеся, пра́вду, мир і ра́дость о Ду́сі Свя́те стяжа́вшії.","Ра́дуйтеся, ві́чния нам ра́дости благоприя́тнії хода́таї;","Ра́дуйтеся, Ду́хом Влади́чним утвержде́ннії, І́мже ра́дость спасе́нія о Го́споді даде́ся.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 6","ps":["Пропові́дник Христо́ва нас ра́ди страда́нія яви́лся єси́, му́чениче святи́й Антипа́тре, к столбу́ бо прив'яза́нний і терно́вними розга́ми біє́н зло́бними мучи́телі, сообра́зен бил єси́ Христу́ Го́споду, вінце́м от те́рнія увенча́нну. Сего́ ра́ди ко Христу́ взира́л єси́, нас ра́ди уя́звленному і поруга́нному, і, терп'я́ за Него́ мно́гія му́ки, я́коже і Той претерпі́ за ни, воспіва́л єси́ Єму́, Влади́ці твоєму́, от любве́ крі́пкия: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́сте, святі́ї дев'яточи́сленнії страстоте́рпці, в гра́ді Ки́зиці све́точ доброді́телей христия́нських, я́ко світоно́сних звізд схожде́ніє, і просвіти́сте нощ глубо́кую ідолослуже́нія. Христо́с бо Госпо́дь ма́нієм Свої́м Боже́ственним посла́ вас, я́ко о́вці посреді́ волко́в; ви же А́гнцю Христу́, во́лею закла́нному за мир Си́ну Бо́жию, і́стиннії послі́дователіє показа́стеся, му́дростію Бо́жиєю, я́же о Ду́сі Свя́те, просвіща́ємії, уразуме́сте мимоходя́щую жизнь і неради́сте о му́ках, ві́чния ра́ди жи́зні пра́вую ві́ру соблюдо́сте, о чесо́м удивля́ющеся, вопіє́м к вам си́це:","Ра́дуйтеся, я́ко по сло́ву Госпо́дню, му́дри я́ко змі́я, му́дри во благо́є, і ці́ли я́ко го́лубіє, прости́ во зло́є, би́сте;","Ра́дуйтеся, я́ко подо́б'ящеся Христу́, І́же кро́ток бі і смире́н се́рдцем, і ви доса́ди і укоре́нія кро́тці претерпі́сте.","Ра́дуйтеся, я́ко в злострада́ніїх не проти́вистеся озлобля́вшим вас, но во смире́нії ва́шем я́ко о́вці на заколе́ніє ведо́стеся;","Ра́дуйтеся, я́ко доброді́телем Христо́вим подража́сте в житії́ своє́м.","Ра́дуйтеся, а́гнці, Христу́ себі́ в же́ртву прине́сшії;","Ра́дуйтеся, ї́хже Христо́с ублажи́ і наслі́дники землі́ живи́х показа́.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 7","ps":["Хотя́ враг спасе́нія ро́да челові́чеськаго устраши́ти тя, небоя́зненнаго во́їна Христо́ва, страстоте́рпче святи́й Феости́хе, подви́же на гнів і я́рость злочести́ваго кня́зя гра́да Ки́зика, і́же повелі́ лю́ті му́чити тя; ти же, біє́н бив па́лицями без пощаді́нія, чрепи́ стро́ган і рожни́ ізбоде́н, благодари́л єси́ Христа́, я́ко сподо́би тя муче́нія страда́ти, сла́ви ра́ди і́мене Єго́ свята́го. Си́лою Бо́жиєю укріпля́єм, отрази́л єси́ сові́т неви́димаго врага́ і ві́рно воспіва́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вний Христо́с Бог і прославля́яйся во святи́х Свої́х, дарова́ вам, му́ченици, не то́кмо єдиному́дренне в Него́ ві́ровати, но і ходи́ти єдиномишле́нієм в до́брім іспові́данії Божества́ Єго́ і по Нем страда́ти. Христо́с бо собра́ вас, пресві́тлоє му́ченичеськоє во́їнство, в собо́р му́чеников єди́н, в Це́рков Бо́га Жи́ва, і преби́сть с ва́ми, ті́мже ра́достно прино́сим вам такова́я:","Ра́дуйтеся, я́ко і вам рече́ Госпо́дь во Єва́нгелії: іді́же єста́ два іли́ тріє́, со́брани во і́м'я Моє́, ту єсьм посреді́ їх;","Ра́дуйтеся, я́ко і вас уті́ши єва́нгельським глаго́лом: в ми́рі ско́рбни бу́дете, но дерза́йте: Аз побіди́х мир.","Ра́дуйтеся, я́ко і вам обітова́, глаго́ля: се Аз с ва́ми єсьм во вся дні до сконча́нія ві́ка;","Ра́дуйтеся, я́ко даде́ся вам побі́да Го́сподем на́шим Ісу́сом Христо́м.","Ра́дуйтеся, я́ко благода́тію Бо́жиєю укріпля́ємі, проти́витися мучи́телем, па́че же і всей дия́вольстій си́лі, возмого́сте;","Ра́дуйтеся, я́ко Христо́с Бог бисть вам столп крі́пости от лиця́ вра́жия.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 8","ps":["Странноужа́сную і жесто́кую ше́ствовал єси́ стезю́, Арте́мо, му́чеником сла́во, ко колеси́ прив'яза́нний і с верху́ гори́ до́лу низпуще́нний, я́ко у́ди твої́ сокруши́шася. Путь же твоєго́ страда́нія подо́бно сві́ту сві́титься, Сві́та Незаходи́маго луча́ми озаре́н, зане́ на Го́спода взира́л єси́, ми́слію і любо́вію ко Христу́ прив'я́зан. Христо́с бо Си́ла, Бог і Госпо́дь, Єму́же взива́л єси́, страстоте́рпче: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь сонм ваш, му́ченици святі́ї дев'яточи́сленнії, наді́ястеся на Христа́ Бо́га на́шего, я́ко і́мать с висоти́ смотрі́ти на по́двиг ваш со мно́жеством святи́х А́нгелов і помога́ти вам, немощни́м, бу́деть. Ві́рен же Бог, І́же не оста́ви вас іскуси́тися па́че, є́же мого́сте, но сотвори́ со іскуше́нієм і ізбавле́ніє, я́ко возмощи́ вам понести́, ті́мже приймі́те от нас похвали́ сія́:","Ра́дуйтеся, я́ко Бог уті́ши вас во вся́кой ско́рби ва́шей;","Ра́дуйтеся, зане́ я́коже ізби́точествоваху страда́нія Христо́ва і вас, та́ко Христо́м ізби́точествова і утіше́ніє ва́ше.","Ра́дуйтеся, я́ко си́ла Христо́ва всели́ся во ви, сего́ ра́ди вся возмого́сте о укрепля́вшем ви Ісу́се Христе́;","Ра́дуйтеся, я́ко люби́ Бо́жия ізлія́ся в сердця́ ва́ша Ду́хом Святи́м і дарова́ вам упова́ніє сла́ви Бо́жия непости́дноє.","Ра́дуйтеся, я́ко Госпо́дь Сил, Помо́щник в ско́рбіх, с ва́ми бисть, і нічто́же возмо́же вас разлучи́ти от любве́ Бо́жия;","Ра́дуйтеся, я́ко ду́ші ва́ша, я́ко пти́ці, ізба́вишася от сі́ті лов'я́щих і возлеті́ша в прекра́сная селе́нія ра́йськая.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 9","ps":["Все ті́ло твоє́ уя́звенно до косте́й імі́л єси́, до́брий страда́льче Ма́гне, єгда́ мучи́тель, обнажи́в тя, на землі́ простре́ і бія́ше по хребту́ без ми́лості і по чре́ву надо́лзі, та́же клеща́ми разжже́нними терза́ше тя. Госпо́дь же, неви́димою си́лою тебі́ сопрису́тствуя, облегчава́ше болі́зні твоя́ і утвержда́ше се́рдце твоє́ в терпі́нії і любві́ Боже́ственній, ті́мже в му́ках воспіва́л єси́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не возмо́гуть ізрещи́ вам досто́йния хвали́, му́ченици Христо́ви дев'яточи́сленнії, мече́м бо преклони́сте ви́ї Христа́ ра́ди, прекло́ньшаго небеса́ і соше́дшаго, і ізлія́сте кров ва́шу, о́бщници Сего́ страсте́й би́вше. Ми же, недосто́йнії, сія́ пі́сненния да́ри прино́сим вам, глаго́люще:","Ра́дуйтеся, Христо́с бо даде́ вам ча́шу Свою́ пи́ти і креще́нієм, і́мже Сам крести́ся, крести́тися;","Ра́дуйтеся, я́ко пред очи́ма суть Бо́жіїма путіє́ і по́двизі ва́ші.","Ра́дуйтеся, Христа́ вседу́шно возлюби́вшії;","Ра́дуйтеся, я́ко со Христо́м пострада́сте, да с Ним і просла́вітеся.","Ра́дуйтеся, ві́чную сла́ву і одія́ніє нетлі́нія от Него́ приє́мшії;","Ра́дуйтеся, я́ко сокро́вища небе́сная вас прия́ша, я́ко пшени́цю зрі́лу.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 10","ps":["Спасти́ прише́дшаго мир, любо́вію Си́на Бо́жия разжига́єм, Феодо́те му́чениче, огня́ си́льнійший яви́лся єси́. На сковраду́ па́льну, вельми́ разжже́нну, наг возложе́нний, та́же в клоко́чущий коно́б вве́рженний, опале́ніє і му́ку го́ркую до́блественне презрі́л єси́; от любве́ же Христо́ви ніка́коже разлучи́вся, Тому́ піл єси́ умиле́нно: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Преві́чному, Христу́ во всем послушли́ви би́вше, му́ченици многострада́льнії, от разли́чних міст і стран в Ки́зиці собра́стеся во єди́но, і, во град вше́дше, Христа́ Си́на Бо́жия, во пло́ті прише́дшаго, пропові́дасте, сла́внії, і без стра́ха сло́во Бо́жиє глаго́ласте. Єгда́ же лю́діє гра́да Ки́зика благовіствова́нія Христо́ва не прия́ша, вас же му́кам і ка́знем і лю́тій сме́рті преда́ша, ви, благові́стници Бо́жії, ісходя́ще отту́да не ті́лом, но душе́ю, не прах, прилі́пший вам от гра́да, оттрясо́сте їм от ног ва́ших, но бре́нная тілеса́ ва́ша, за благові́стіє Христа́ уму́ченная, оста́висте во свиді́тельство на ня в день су́дний, ті́мже благогові́йно взива́єм вам:","Ра́дуйтеся, ва́шими христопосле́довательними стопа́ми во град Кизи́к ше́ствовавшії;","Ра́дуйтеся, Єва́нгелія Христо́ва благові́стници.","Ра́дуйтеся, я́ко Бо́га воплоще́нна пропові́дасте;","Ра́дуйтеся, я́ко му́ки, огнь і ме́чноє усіче́ніє за Него́ в сла́дость вміни́сте.","Ра́дуйтеся, я́ко лю́дем, і́же не прия́ша ви, ніже́ послу́шаша вас, во свиді́тельство по́двига ва́шего, во спасе́ніє їх под'я́таго, тілеса́ ва́ша честна́я оста́висте;","Ра́дуйтеся, я́ко тече́ніє му́ченичеськаго по́двига до́брі сконча́сте, ві́ру соблюдо́сте, про́чеє соблюде́ться вам віне́ць пра́вди.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 11","ps":["Пі́ніє прино́сим, Фавма́сіє, тебі́, му́чениче. Душа́ твоя́ яви́ крі́пкоє терпі́ніє і по́двига до́блесть, приложи́ша бо тебе́ неми́лостивії мучи́теліє ра́ни к ра́нам і болі́зні к болі́знем, і́бо ноже́м ізбожда́ху і рі́заху плоть твою́, єще́ же і копіє́м ре́бра твоя́ лю́ті пронзи́ша. Ти же, му́чениче Фавма́сіє, сообра́зен бив Христу́ Го́споду, на Кресті́ от єди́наго із во́їнов копіє́м в ре́бра прободе́нному, глаго́лал єси́, ра́дуяся і сла́в'я Бо́га: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная богосія́нная свіща́ су́щим во тьмі неві́рія і многобо́жія і́дольськаго яви́шася нетлі́нная тілеса́ ва́ша, святі́ї дев'яточи́сленнії му́ченици. Єгда́, воцари́вшуся вели́кому Константи́ну, преста́ гоне́ніє і світ благоче́стія возсія́ по вселе́нній, тогда́ бо в Ки́зиці, в хра́мі ва́шем, мно́гая чудеса́ і ісціле́нія от святи́х моще́й ва́ших би́ша, і того́ ра́ди мно́жество наро́да неві́рнаго обраща́хуся ко Христу́. Ті́мже в похвалу́ ва́шу зове́м:","Ра́дуйтеся, я́ко лю́діє гра́да Ки́зика, зря́ще благода́ть Бо́жию, в многоціле́бних мощеіх ва́ших чудоді́йствующую, прия́ша святу́ю ві́ру во Христі́;","Ра́дуйтеся, я́ко і́доли і і́дольстії хра́ми в Ки́зиці сокруши́шася, а вмі́сто тіх хра́ми Бо́жії воздвиго́шася.","Ра́дуйтеся, пода́теліє неоску́днії ісціле́ній;","Ра́дуйтеся, ве́лія бо ва́ша, му́ченик Христо́вих, богоблагода́тная си́ла, во гробі́х бо лежі́те і ду́хи зло́би прогоня́єте, і, я́ко жи́ви, ві́рою притека́ющим даєте́ проше́нія.","Ра́дуйтеся, я́ко чуде́с преди́вних сія́нієм ві́рния озаря́єте і неві́рния ко Христу́ обраща́єте;","Ра́дуйтеся, святи́я бо мо́щі ва́ша я́ко зна́м'я побі́дноє всім яви́шася.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственная укріпля́ше тя в му́ченичестім по́двизі, Филимо́не страстоте́рпче: за ре́бра багро́м желі́зним оцепле́нний і на дре́ві ужа́сно пове́шенний, непрекло́нен преби́л єси́ во іспові́данії Христа́ і Бо́га, Єму́же хвале́бную піснь воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́гая і пресла́вная чудотворе́нія ва́ша, восхваля́єм вас, всехва́льнії му́ченици Христо́ви дев'яточи́сленнії: єгда́ бо в Ки́зиці благові́рнії христия́не тілеса́ ва́ша, із под спу́да земна́го із'є́мше і нетлі́нная обрі́тше, в храм, во і́м'я ва́ше созда́нний, внесо́ша, чудеси́, я́ко сві́тлими луча́ми, возсія́сте от святи́х моще́й ва́ших. Ми же, любо́вію воспіва́юще да́нную вам от Бо́га благода́ть ісціле́ній, зове́м:","Ра́дуйтеся, я́ко по кончи́ні ва́шей чуде́сния ціле́б істо́чники істочи́ Христо́с Бог в прославле́ніє ва́ше;","Ра́дуйтеся, духо́в нечи́стих от челові́ка прогони́теліє.","Ра́дуйтеся, сляче́нних ціли́теліє і тряса́вичними болі́зньми одержи́мих всеконе́чнії уврачева́теліє;","Ра́дуйтеся, я́ко во́днаго труда́ ізба́вися муж ні́кий, прикосну́вся честні́й ра́ці моще́й ва́ших.","Ра́дуйтеся, я́ко і сами́м призива́нієм честни́х іме́н ва́ших тряса́вичний неду́г отгоня́ється і вся́кая болі́знь всіх с ві́рою притека́ющих врачу́ється;","Ра́дуйтеся, добропобі́днії му́ченици, вінці́ побі́ди от Христа́ Спа́са на́шего увенча́ннії, я́ко страда́нія ва́ша возме́ришася вам сла́вою і че́стію Ца́рствія Небе́снаго.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 13","ps":["О добропобі́днії і многострада́льнії му́ченици Христо́ви дев'яточи́сленнії, ми́лостивно приймі́те от нас, недосто́йних і грі́шних, возноси́моє к вам ни́ні хвале́бноє пісносло́віє; і, я́ко предстоя́теліє го́рнія сла́ви, іму́щії дерзнове́ніє мно́го ко Христу́ Бо́гу на́шему, пом'яні́те ни, ублажа́ющия вас любо́вію і чту́щия ва́ша чу́дния по́двиги; іспросі́те нам у Го́спода оставле́ніє гріхо́в, во ві́рі утвержде́ніє, в до́брих ді́ліх укріпле́ніє, от бід і напа́стей ізбавле́ніє, да всегда́ благода́рними усти́ воспіва́єм Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Я́ко А́нгели преми́рнії, возне́сшеся ми́слію от земни́х к небе́сним, ко Христу́, Влади́ці всіх, непреста́нно ві́ри очи́ма взира́юще, му́ченици святі́ї, Феогни́де, Ру́фе, Антипа́тре, Феости́хе, Арте́мо, Ма́гне, Феодо́те, Фавма́сіє, Филимо́не, посреді́ кумирослужи́телей гра́да Кизи́чеськаго іспові́дасте себі́ безбоя́зненно христия́ни би́ти і, си́лою Бо́жиєю укріпля́ємі, мно́гія му́ки му́жественні за Христа́ претерпі́сте і под меч глави́ ва́ша преклони́сте, ті́мже, ублажа́юще страда́нія ва́ша і усікнове́ніє, глаго́лем:","Ра́дуйтеся, земни́я ра́дости презрі́вшії;","Ра́дуйтеся, благ небе́сних возжела́вшії.","Ра́дуйтеся, іспові́дниці Христо́ви непобіди́мії, ві́ру непоро́чну соблю́дшії;","Ра́дуйтеся, стра́сті Христо́ві послі́довавшії і смерть Христо́ву сме́ртію своє́ю подража́вшії.","Ра́дуйтеся, си́лою Воскре́сшаго держа́ву а́дову попра́вшії;","Ра́дуйтеся, душі́ своя́ в ру́ці Бо́жії преда́вшії і побі́дния вінці́ приє́мшії.","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Кондак 1","ps":["Ізбра́нії от Царя́ Сил, Го́спода Ісу́са, страстоте́рпці Христо́ви дев'яточи́сленнії, от разли́чних стран в гра́ді Ки́зиці во єди́но со́браннії і Христа́ дерзнове́нне, мук і сме́рті не убоя́вшеся, іспові́давшії, торжеству́єм духо́вні во святі́м пра́здниці ва́шем і, воспіва́юще благода́тную терпі́нія ва́шего до́блесть, мо́лим вас, во́ї Христо́ви многострада́льнії і утвержде́ннії во во́лі Христо́вой, і нам спасе́нія іспросі́те, зову́щим:","Ра́дуйтеся, прехва́льнії му́ченици Христо́ви дев'яточи́сленнії."]},{"h":"Молитва перша","ps":["О всехва́льнії святі́ї му́ченици, до́блественнії раби́ Христо́ви, Феогни́де, Ру́фе, Антипа́тре, Феости́хе, Арте́мо, Ма́гне, Феодо́те, Фавма́сіє і Филимо́не, і́же Христа́ ра́ди от разли́чних стран собра́стеся і Того́ соверше́нна Бо́га і Челові́ка дерзнове́нно в Ки́зиці пропові́дасте; принужда́єми би́вше куми́ром поклони́тися, і́доли попра́сте і кня́зя посрами́сте, разли́чних томле́ній і о́гненних преще́ній не убоя́стеся, і по разли́чнім страда́нії о́стрієм меча́ посі́чени би́сте, і пролія́сте за Христа́ кров свою́, я́ко во́ду, і то́ю, я́ко багряни́цею, Це́рков Христо́ву, я́ко неві́сту, украси́сте; ті́мже і ни́ні, увенча́ннії неув'яда́ємим вінце́м безсме́ртния сла́ви, при́сно в неізглаго́ланній ра́дости с ли́ки а́нгельськими в небе́сних селе́ніїх водворя́єтеся, Боже́ственним сві́том облиста́ємі і зрі́нієм Єго́ добро́ти неізрече́нния наслажда́ющеся. Сего́ ра́ди і ми, смире́ннії, к вам притека́єм і, уми́льно на святи́й ваш о́браз взира́юще, мо́лим: ви моли́те за ни Христа́ Бо́га, я́ко дерзнове́ніє к Нему́ іму́щії, да ва́шими святи́ми моли́твами вся́каго неду́га душе́внаго і тіле́снаго ізба́вимся. Вам бо от Бо́га даде́ся враче́бний дар от вся́ких скорбе́й с ві́рою к вам припа́дающия ціли́ти, я́коже і о́наго сла́внаго му́жа от тряса́вичния болі́зні уврачева́сте, да і ми, ві́рнії, то́жде получи́вше, почита́єм вас, святі́ї му́ченици, толи́ка дарова́нія іму́щих от Христа́ Бо́га, Єму́же і сла́ва ку́пно со Отце́м і Ду́хом Святи́м всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́ції уго́дниці Бо́жії, святі́ї му́ченици Христо́ви: Феогни́де, Ру́фе, Антипа́тре, Феости́хе, Арте́мо, Ма́гне, Феодо́те, Фавма́сіє і Филимо́не! Ви Царя́ Христа́ ві́рнії слуги́ би́сте і по́двигом до́брим подвиза́стеся, претерпі́вше за Него́ му́ки; ті́мже, по нело́жному Єго́ глаго́лу: іді́же єсьм Аз, ту і слуга́ Мой бу́деть, і ви ни́ні со А́нгели предстоїте́ Влади́ці Христу́ і с висоти́ небе́сния сла́ви призира́єті ми́лостивно на храм ваш і на моля́щихся в нем.","Умолі́те у́бо Го́спода Сил Це́рков Єго́ Святу́ю і правосла́вноє Оте́чество на́ше сохрани́ти от напа́стей і бід, от всіх враг ви́димих і неви́димих, низложи́ти пре́лесть неві́рія і безбо́жия і ста́до Христо́во ізба́вити от волко́в, губ'я́щих є, глаго́лющих лука́воє до́броє, і до́броє лука́воє, полага́ющих тьму світ, і світ тьму; от шата́нія умо́в, я́ко трость, ві́тром коле́блемих, і от гріхо́внаго душ разслабле́нія.","Богодарова́нную благода́ть чуде́с ва́ших, му́ченици Христо́ви дев'яточи́сленнії, прострі́те ко всім нам, ві́рою к вам прибега́ющим, і вся на́ша неду́ги душе́вния і тіле́сния уврачу́йте, і вся проше́нія на́ша во бла́го іспо́лніте.","Єй, страстоте́рпці святі́ї, моли́те за ни Го́спода, да низпо́слеть нам Боже́ственную благода́ть і дар Свята́го Ду́ха, всегда́ немощна́я врачу́ющаго і оскудіва́ющая восполня́ющаго, во є́же соді́ловати нам спасе́ніє своє́, заступле́нієм Христа́ Спа́са на́шего, і ізба́витися нам от сі́ті вра́жия і гріхо́в, і поми́ловатися душа́м на́шим, да і ми ку́пно с ва́ми і всі́ми святи́ми просла́вим Бо́га, в Тро́йці сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Святі́ї дев'яточи́сленнії му́ченици, / от разли́чних градо́во во єди́н лик совокупи́вшеся ма́нієм Боже́ственним, / му́жественно за Христа́ пострада́сте, / неви́димаго врага́ побіди́сте, / злові́рния кня́зі і мучи́телі посрами́сте ва́шим терпі́нієм, / огне́м же любве́ Бо́жия разжиза́ємі, / веще́ственно вас огнь му́чащий в хлад преложи́сте, / ті́мже даде́ся вам от Христа́ Бо́га благода́ть / тряса́вичную ісціля́ти болі́знь, / от нея́же і многови́дних страсте́й, // ми́лостивно спаса́йте і нас предста́тельством ва́шим, мо́лимся."]},{"h":"Кондак, глас 2","ps":["Тве́рдий і всесві́тлий лик му́ченик дев'яти́, / Трисо́лнечнаго Божества́ іспові́дниці, / на суди́щі Тому́ нача́льно взива́ху: / кров і ду́ші на́ша с тілеси́, / я́ко непоро́чную же́ртву, прино́сим Тебі́, Влади́ко, // в ли́ціх Небе́сних Твої́х сопричти́, я́ко Бог Ми́лостивий."]},{"h":"Величання","ps":["Велича́єм вас, святі́ї дев'яточи́сленнії му́ченици, і чтим честна́я страда́нія ва́ша, я́же за Христа́ претерпі́ли єсте́."]}],"notes":[]}];
export default D;
